const AUDIO_UNLOCK_EVENTS = ["pointerdown", "keydown", "touchstart"];

function unlockAudioByUserGesture() {
  if (audioUserGestureUnlocked) {
    return;
  }
  audioUserGestureUnlocked = true;
  for (const eventName of AUDIO_UNLOCK_EVENTS) {
    window.removeEventListener(eventName, unlockAudioByUserGesture, true);
  }
}

(function applyTokenBootClassFromStorage() {
  try {
    const bootUrl = new URL(window.location.href);
    const desktopToken = String(bootUrl.searchParams.get("desktop_token") ?? "").trim();
    const storedToken = String(localStorage.getItem("yooh_token") ?? "").trim();
    const hasBootToken = Boolean(storedToken || desktopToken);
    document.documentElement.classList.toggle("yooh-has-token-boot", hasBootToken);
  } catch {
    // Ignore boot class detection errors.
  }
})();

for (const eventName of AUDIO_UNLOCK_EVENTS) {
  window.addEventListener(eventName, unlockAudioByUserGesture, { capture: true, once: true });
}

const FOLDER_RULE_VALUES = new Set(["all", "direct", "group", "channel", "server", "pinned", "unread"]);

function normalizeFolderRule(value) {
  const safeValue = String(value ?? "").trim().toLowerCase();
  return FOLDER_RULE_VALUES.has(safeValue) ? safeValue : "all";
}

function createFolderId() {
  if (globalThis.crypto?.randomUUID) {
    return `folder-${globalThis.crypto.randomUUID()}`;
  }
  return `folder-${Date.now().toString(36)}-${Math.random().toString(16).slice(2, 9)}`;
}

function normalizeFolderEntry(input = {}, fallbackIndex = 0) {
  const source = input && typeof input === "object" ? input : {};
  const rawId = String(source.id ?? "").trim();
  const id = rawId || createFolderId();
  const legacyMap = {
    family: { rule: "direct", icon: "users", titleKey: "folderPrivate" },
    school: { rule: "group", icon: "users", titleKey: "folderGroups" },
    projects: { rule: "channel", icon: "megaphone", titleKey: "folderChannels" },
    freaks: { rule: "pinned", icon: "star", titleKey: "folderPinned" },
  };
  const legacyPreset = legacyMap[id] ?? null;
  const title = String(source.title ?? "").trim().slice(0, 40);
  const titleKey = String(source.titleKey ?? legacyPreset?.titleKey ?? "").trim();
  const icon = String(source.icon ?? legacyPreset?.icon ?? "chat").trim() || "chat";
  const rule = normalizeFolderRule(source.rule ?? legacyPreset?.rule);
  const chatIds = Array.isArray(source.chatIds)
    ? [...new Set(source.chatIds.map((entry) => String(entry ?? "").trim()).filter(Boolean))]
    : [];
  const excludedChatIds = Array.isArray(source.excludedChatIds)
    ? [...new Set(source.excludedChatIds.map((entry) => String(entry ?? "").trim()).filter(Boolean))]
    : [];

  if (id === "all") {
    return {
      id: "all",
      title: "",
      titleKey: "folderAll",
      icon: "chat",
      rule: "all",
      chatIds: [],
      excludedChatIds: [],
      sort: Number.isFinite(Number(source.sort)) ? Number(source.sort) : fallbackIndex,
    };
  }

  return {
    id,
    title: title || `Folder ${fallbackIndex + 1}`,
    titleKey,
    icon,
    rule,
    chatIds,
    excludedChatIds,
    sort: Number.isFinite(Number(source.sort)) ? Number(source.sort) : fallbackIndex,
  };
}

function escapeHtml(value) {
  const source = String(value ?? "");
  return source
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function normalizeFolderEntries(source) {
  const list = Array.isArray(source) ? source : [];
  const normalized = [];
  const seen = new Set();

  for (let index = 0; index < list.length; index += 1) {
    const entry = normalizeFolderEntry(list[index], index);
    if (seen.has(entry.id)) {
      continue;
    }
    seen.add(entry.id);
    normalized.push(entry);
  }

  if (!normalized.some((entry) => entry.id === "all")) {
    normalized.unshift(normalizeFolderEntry({ id: "all" }, 0));
  }

  return normalized.map((entry, index) => ({
    ...entry,
    sort: index,
  }));
}

function readChatFolders() {
  try {
    const raw = localStorage.getItem(CHAT_FOLDERS_STORAGE_KEY);
    if (!raw) {
      return normalizeFolderEntries(DEFAULT_CHAT_FOLDERS);
    }

    const parsed = JSON.parse(raw);
    const source = Array.isArray(parsed) ? parsed : DEFAULT_CHAT_FOLDERS;
    return normalizeFolderEntries(source);
  } catch {
    return normalizeFolderEntries(DEFAULT_CHAT_FOLDERS);
  }
}

function normalizeDeepLinkUsername(value) {
  return String(value ?? "")
    .trim()
    .replace(/^[@*]+/, "")
    .replace(/[^\w.]/g, "");
}

function readPendingDeepLinkUsernameFromLocation() {
  try {
    const params = new URLSearchParams(window.location.search);
    const direct = params.get("yooh_qr") ?? params.get("chatWith") ?? "";
    return normalizeDeepLinkUsername(direct);
  } catch {
    return "";
  }
}

function readPendingOpenChatIdFromLocation() {
  try {
    const params = new URLSearchParams(window.location.search);
    return String(params.get("openChatId") ?? "").trim();
  } catch {
    return "";
  }
}

function detectBrowserName() {
  try {
    const ua = String(globalThis.navigator?.userAgent ?? "");
    if (/YoohDesktop\//i.test(ua) || /Electron\//i.test(ua)) {
      return "Desktop App";
    }
    if (/Edg\//i.test(ua)) {
      return "Edge";
    }
    if (/OPR\//i.test(ua)) {
      return "Opera";
    }
    if (/Firefox\//i.test(ua)) {
      return "Firefox";
    }
    if (/Chrome\//i.test(ua)) {
      return "Chrome";
    }
    if (/Safari\//i.test(ua)) {
      return "Safari";
    }
  } catch {
    // Ignore user agent parsing errors.
  }
  return "Browser";
}

function isDesktopAppRuntime() {
  try {
    if (globalThis.pywebview?.api) {
      return true;
    }
    const ua = String(globalThis.navigator?.userAgent ?? "");
    return /YoohDesktop\//i.test(ua) || /Electron\//i.test(ua) || desktopLaunchApp === "native" || desktopLaunchApp === "electron";
  } catch {
    return desktopLaunchApp === "native" || desktopLaunchApp === "electron";
  }
}

function getDeviceClientLabel(browserName = detectBrowserName()) {
  if (browserName === "Desktop App") {
    return "Yooh Desktop App";
  }
  return `Yooh Web (${browserName})`;
}

function detectCurrentDeviceName() {
  const platform = normalizePlatform(readLocalString("yooh_platform", ""));
  if (platform === "iphone") {
    return "iPhone";
  }
  if (platform === "android") {
    return "Android";
  }
  if (platform === "pc") {
    return "PC";
  }
  return "Web Device";
}

function detectCurrentDeviceLocation() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "Unknown";
  } catch {
    return "Unknown";
  }
}

function normalizeBlockedEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id ?? "").trim();
  if (!id) {
    return null;
  }
  return {
    id,
    chatId: String(entry.chatId ?? "").trim(),
    username: String(entry.username ?? "").trim(),
    displayName: String(entry.displayName ?? "").trim() || `User ${id.slice(-4)}`,
    avatar: String(entry.avatar ?? "").trim(),
    blockedAt: String(entry.blockedAt ?? "").trim() || new Date().toISOString(),
  };
}

function normalizeAuthorizedSiteEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id ?? "").trim() || `site-${Date.now().toString(36)}-${Math.random().toString(16).slice(2, 8)}`;
  const name = String(entry.name ?? "").trim();
  const url = String(entry.url ?? "").trim();
  if (!name || !url) {
    return null;
  }
  return {
    id,
    name,
    url,
    lastActiveAt: String(entry.lastActiveAt ?? "").trim() || new Date().toISOString(),
  };
}

function normalizePasskeyEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id ?? "").trim() || `passkey-${Date.now().toString(36)}-${Math.random().toString(16).slice(2, 8)}`;
  const name = String(entry.name ?? "").trim() || detectCurrentDeviceName();
  const createdAt = String(entry.createdAt ?? "").trim() || new Date().toISOString();
  const lastUsedAt = String(entry.lastUsedAt ?? "").trim() || createdAt;
  return {
    id,
    name,
    createdAt,
    lastUsedAt,
  };
}

