function getPrivacyStorageKey(userId) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return "";
  }
  return `yooh_privacy_preferences_${safeUserId}`;
}

function readPrivacyPreferences(userId = "") {
  const defaults = createDefaultPrivacyPreferences();
  const storageKey = getPrivacyStorageKey(userId);
  if (!storageKey) {
    return defaults;
  }
  try {
    const raw = localStorage.getItem(storageKey);
    if (!raw) {
      return defaults;
    }
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") {
      return defaults;
    }

    const rawSecurity = parsed.security && typeof parsed.security === "object" ? parsed.security : {};
    const rawSessions = parsed.sessions && typeof parsed.sessions === "object" ? parsed.sessions : {};
    const blockedUsers = Array.isArray(rawSecurity.blockedUsers)
      ? rawSecurity.blockedUsers.map((entry) => normalizeBlockedEntry(entry)).filter(Boolean)
      : [];
    const authorizedSites = Array.isArray(rawSecurity.authorizedSites)
      ? rawSecurity.authorizedSites.map((entry) => normalizeAuthorizedSiteEntry(entry)).filter(Boolean)
      : [];
    const passkeys = Array.isArray(rawSecurity.passkeys)
      ? rawSecurity.passkeys.map((entry) => normalizePasskeyEntry(entry)).filter(Boolean)
      : [];
    const sessionOthers = Array.isArray(rawSessions.others)
      ? rawSessions.others
          .map((entry) => {
            if (!entry || typeof entry !== "object") {
              return null;
            }
            const id = String(entry.id ?? "").trim();
            if (!id) {
              return null;
            }
            return {
              id,
              name: String(entry.name ?? "").trim() || "Web Device",
              client: String(entry.client ?? "").trim() || "Yooh Web",
              location: String(entry.location ?? "").trim() || "Unknown",
              lastSeen: String(entry.lastSeen ?? "").trim() || "",
              icon: String(entry.icon ?? "").trim() === "apple" ? "apple" : "desktop",
            };
          })
          .filter(Boolean)
      : defaults.sessions.others;
    const legacySessionIds = new Set(["ios-1", "pc-2"]);
    const normalizedSessionOthers =
      sessionOthers.length === legacySessionIds.size && sessionOthers.every((entry) => legacySessionIds.has(entry.id))
        ? []
        : sessionOthers;
    const loginEmailRaw = String(rawSecurity.loginEmail ?? "").trim();
    const sanitizedLoginEmail = loginEmailRaw === "v4***v@privaterel..." ? "" : loginEmailRaw;

    return {
      security: {
        ...defaults.security,
        ...rawSecurity,
        autoDeleteDays: Number.isFinite(Number(rawSecurity.autoDeleteDays))
          ? Math.max(0, Math.min(365, Number(rawSecurity.autoDeleteDays)))
          : defaults.security.autoDeleteDays,
        loginEmail: sanitizedLoginEmail,
        passwordHint: String(rawSecurity.passwordHint ?? "").trim(),
        recoveryEmail: String(rawSecurity.recoveryEmail ?? "").trim().toLowerCase(),
        autoLockMinutes: [0, 1, 5].includes(Number(rawSecurity.autoLockMinutes))
          ? Number(rawSecurity.autoLockMinutes)
          : defaults.security.autoLockMinutes,
        faceIdEnabled: Boolean(rawSecurity.faceIdEnabled),
        passcodeValue: String(rawSecurity.passcodeValue ?? "").trim(),
        blockedUsers,
        authorizedSites,
        passkeys,
      },
      sessions: {
        currentDevice: {
          ...defaults.sessions.currentDevice,
          name: String(rawSessions.currentDevice?.name ?? "").trim() || defaults.sessions.currentDevice.name,
        },
        others: normalizedSessionOthers,
      },
      phone: {
        ...defaults.phone,
        ...(parsed.phone ?? {}),
        alwaysShowIds: normalizePrivacyIdList(parsed.phone?.alwaysShowIds),
        alwaysShowCount: getPrivacyExceptionCount(parsed.phone ?? {}, "alwaysShowIds", "alwaysShowCount"),
      },
      lastSeen: {
        ...defaults.lastSeen,
        ...(parsed.lastSeen ?? {}),
        alwaysShowIds: normalizePrivacyIdList(parsed.lastSeen?.alwaysShowIds),
        alwaysShowCount: getPrivacyExceptionCount(parsed.lastSeen ?? {}, "alwaysShowIds", "alwaysShowCount"),
      },
      profilePhotos: {
        ...defaults.profilePhotos,
        ...(parsed.profilePhotos ?? {}),
        alwaysShowIds: normalizePrivacyIdList(parsed.profilePhotos?.alwaysShowIds),
        alwaysHideIds: normalizePrivacyIdList(parsed.profilePhotos?.alwaysHideIds),
        alwaysShowCount: getPrivacyExceptionCount(parsed.profilePhotos ?? {}, "alwaysShowIds", "alwaysShowCount"),
        alwaysHideCount: getPrivacyExceptionCount(parsed.profilePhotos ?? {}, "alwaysHideIds", "alwaysHideCount"),
      },
      forwards: {
        ...defaults.forwards,
        ...(parsed.forwards ?? {}),
        alwaysAllowIds: normalizePrivacyIdList(parsed.forwards?.alwaysAllowIds),
        alwaysDenyIds: normalizePrivacyIdList(parsed.forwards?.alwaysDenyIds),
        alwaysAllowCount: getPrivacyExceptionCount(parsed.forwards ?? {}, "alwaysAllowIds", "alwaysAllowCount"),
        alwaysDenyCount: getPrivacyExceptionCount(parsed.forwards ?? {}, "alwaysDenyIds", "alwaysDenyCount"),
      },
      calls: {
        ...defaults.calls,
        ...(parsed.calls ?? {}),
        alwaysAllowIds: normalizePrivacyIdList(parsed.calls?.alwaysAllowIds),
        alwaysDenyIds: normalizePrivacyIdList(parsed.calls?.alwaysDenyIds),
        alwaysAllowCount: getPrivacyExceptionCount(parsed.calls ?? {}, "alwaysAllowIds", "alwaysAllowCount"),
        alwaysDenyCount: getPrivacyExceptionCount(parsed.calls ?? {}, "alwaysDenyIds", "alwaysDenyCount"),
      },
      voice: {
        ...defaults.voice,
        ...(parsed.voice ?? {}),
        alwaysDenyIds: normalizePrivacyIdList(parsed.voice?.alwaysDenyIds),
        alwaysDenyCount: getPrivacyExceptionCount(parsed.voice ?? {}, "alwaysDenyIds", "alwaysDenyCount"),
      },
      messages: {
        ...defaults.messages,
        ...(parsed.messages ?? {}),
        alwaysAllowIds: normalizePrivacyIdList(parsed.messages?.alwaysAllowIds),
        alwaysDenyIds: normalizePrivacyIdList(parsed.messages?.alwaysDenyIds),
        alwaysAllowCount: getPrivacyExceptionCount(parsed.messages ?? {}, "alwaysAllowIds", "alwaysAllowCount"),
        alwaysDenyCount: getPrivacyExceptionCount(parsed.messages ?? {}, "alwaysDenyIds", "alwaysDenyCount"),
      },
      profileVisibility: {
        ...defaults.profileVisibility,
        ...(parsed.profileVisibility ?? {}),
        birthdayExceptionIds: normalizePrivacyIdList(parsed.profileVisibility?.birthdayExceptionIds),
        giftsExceptionIds: normalizePrivacyIdList(parsed.profileVisibility?.giftsExceptionIds),
        aboutExceptionIds: normalizePrivacyIdList(parsed.profileVisibility?.aboutExceptionIds),
        invitesExceptionIds: normalizePrivacyIdList(parsed.profileVisibility?.invitesExceptionIds),
        birthdayExceptionCount: getPrivacyExceptionCount(
          parsed.profileVisibility ?? {},
          "birthdayExceptionIds",
          "birthdayExceptionCount",
        ),
        giftsExceptionCount: getPrivacyExceptionCount(parsed.profileVisibility ?? {}, "giftsExceptionIds", "giftsExceptionCount"),
        aboutExceptionCount: getPrivacyExceptionCount(parsed.profileVisibility ?? {}, "aboutExceptionIds", "aboutExceptionCount"),
        invitesExceptionCount: getPrivacyExceptionCount(
          parsed.profileVisibility ?? {},
          "invitesExceptionIds",
          "invitesExceptionCount",
        ),
      },
    };
  } catch {
    return defaults;
  }
}

function savePrivacyPreferences() {
  const storageKey = getPrivacyStorageKey(state.user?.id);
  if (!storageKey) {
    return;
  }
  try {
    localStorage.setItem(storageKey, JSON.stringify(state.privacyPreferences));
    // Legacy global key could leak stale privacy values between different users.
    localStorage.removeItem("yooh_privacy_preferences");
  } catch {
    // Ignore localStorage errors.
  }
}

