if (desktopLaunchToken && !localStorage.getItem("yooh_token")) {
  localStorage.setItem("yooh_token", desktopLaunchToken);
}
if (desktopLaunchLang && !localStorage.getItem("yooh_lang")) {
  localStorage.setItem("yooh_lang", desktopLaunchLang);
}
if (desktopLaunchPlatform && !localStorage.getItem("yooh_platform")) {
  localStorage.setItem("yooh_platform", desktopLaunchPlatform);
}
if (desktopLaunchToken || desktopLaunchLang || desktopLaunchPlatform) {
  const sanitizedUrl = new URL(window.location.href);
  sanitizedUrl.searchParams.delete("desktop_token");
  sanitizedUrl.searchParams.delete("desktop_lang");
  sanitizedUrl.searchParams.delete("desktop_platform");
  window.history.replaceState({}, "", sanitizedUrl.toString());
}

function generateClientMessageId() {
  if (window.crypto?.randomUUID) {
    return window.crypto.randomUUID();
  }
  const seed = Math.random().toString(36).slice(2, 10);
  return `cmid-${Date.now()}-${seed}`;
}

function buildSendFingerprint({
  chatId = "",
  stream = "main",
  text = "",
  fileNames = [],
  replyToMessageId = "",
  threadRootId = "",
} = {}) {
  const safeChatId = String(chatId ?? "").trim();
  const safeStream = String(stream ?? "main").trim() || "main";
  const normalizedText = String(text ?? "").trim().replace(/\s+/g, " ").slice(0, 512);
  const files = Array.isArray(fileNames)
    ? fileNames
        .map((entry) => String(entry ?? "").trim().toLowerCase())
        .filter(Boolean)
        .sort()
    : [];
  const safeReply = String(replyToMessageId ?? "").trim();
  const safeThread = String(threadRootId ?? "").trim();
  return [safeChatId, safeStream, normalizedText, files.join(","), safeReply, safeThread].join("|");
}

function cleanupSendDeduper() {
  const map = state.sendDeduper?.map;
  if (!map || typeof map !== "object") {
    state.sendDeduper = { map: {} };
    return;
  }
  const now = Date.now();
  for (const [fingerprint, at] of Object.entries(map)) {
    if (!fingerprint || !Number.isFinite(Number(at))) {
      delete map[fingerprint];
      continue;
    }
    if (now - Number(at) > MESSAGE_SEND_DEDUPE_WINDOW_MS) {
      delete map[fingerprint];
    }
  }
}

function isDuplicateRecentSend(fingerprint) {
  const safeFingerprint = String(fingerprint ?? "").trim();
  if (!safeFingerprint) {
    return false;
  }
  cleanupSendDeduper();
  const map = state.sendDeduper?.map ?? {};
  const at = Number(map[safeFingerprint] ?? 0);
  if (!Number.isFinite(at) || at <= 0) {
    return false;
  }
  return Date.now() - at <= MESSAGE_SEND_DEDUPE_WINDOW_MS;
}

function rememberSendFingerprint(fingerprint) {
  const safeFingerprint = String(fingerprint ?? "").trim();
  if (!safeFingerprint) {
    return;
  }
  if (!state.sendDeduper || typeof state.sendDeduper !== "object") {
    state.sendDeduper = { map: {} };
  }
  if (!state.sendDeduper.map || typeof state.sendDeduper.map !== "object") {
    state.sendDeduper.map = {};
  }
  state.sendDeduper.map[safeFingerprint] = Date.now();
  cleanupSendDeduper();
}

function buildReadCursorKey(chatId, stream = "main") {
  const safeChatId = String(chatId ?? "").trim();
  const safeStream = String(stream ?? "main").trim() || "main";
  if (!safeChatId) {
    return "";
  }
  return `${safeChatId}:${safeStream}`;
}

function cleanupClosedCallSessions() {
  const entries = state.closedCallSessions;
  if (!entries || typeof entries !== "object") {
    state.closedCallSessions = {};
    return;
  }
  const now = Date.now();
  for (const [sessionId, at] of Object.entries(entries)) {
    if (!sessionId || !Number.isFinite(Number(at))) {
      delete entries[sessionId];
      continue;
    }
    if (now - Number(at) > 45_000) {
      delete entries[sessionId];
    }
  }
}

function markCallSessionClosed(sessionId) {
  const safeSessionId = String(sessionId ?? "").trim();
  if (!safeSessionId) {
    return;
  }
  cleanupClosedCallSessions();
  state.closedCallSessions[safeSessionId] = Date.now();
}

function isCallSessionClosed(sessionId) {
  const safeSessionId = String(sessionId ?? "").trim();
  if (!safeSessionId) {
    return false;
  }
  cleanupClosedCallSessions();
  const at = Number(state.closedCallSessions?.[safeSessionId] ?? 0);
  return Number.isFinite(at) && at > 0;
}

const TUNNEL_BYPASS_HEADER_NAME = "bypass-tunnel-reminder";
const TUNNEL_BYPASS_HEADER_VALUE = "1";

function getUnreadStorageKey(userId = state.user?.id) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return "";
  }
  return `yooh_unread_by_chat_${safeUserId}`;
}

function readUnreadByChat(userId = state.user?.id) {
  const key = getUnreadStorageKey(userId);
  if (!key) {
    return {};
  }
  const raw = readLocalMap(key);
  const normalized = {};
  for (const [chatId, value] of Object.entries(raw)) {
    const safeChatId = String(chatId ?? "").trim();
    if (!safeChatId) {
      continue;
    }
    const count = Number.parseInt(value, 10);
    if (Number.isFinite(count) && count > 0) {
      normalized[safeChatId] = count;
    }
  }
  return normalized;
}

function saveUnreadByChat() {
  const key = getUnreadStorageKey();
  if (!key) {
    return;
  }
  const payload = {};
  for (const [chatId, value] of Object.entries(state.unreadByChat ?? {})) {
    const safeChatId = String(chatId ?? "").trim();
    if (!safeChatId) {
      continue;
    }
    const count = Number.parseInt(value, 10);
    if (Number.isFinite(count) && count > 0) {
      payload[safeChatId] = count;
    }
  }
  try {
    localStorage.setItem(key, JSON.stringify(payload));
  } catch {
    // Ignore storage errors.
  }
}

function getUnreadCountForChat(chatOrId) {
  const chatId = typeof chatOrId === "string" ? chatOrId : String(chatOrId?.id ?? "").trim();
  if (!chatId) {
    return 0;
  }
  const localValue = Number.parseInt(state.unreadByChat?.[chatId] ?? 0, 10);
  if (Number.isFinite(localValue) && localValue > 0) {
    return localValue;
  }
  const chat = typeof chatOrId === "string" ? state.chats.find((entry) => entry.id === chatId) : chatOrId;
  const serverValue = Number.parseInt(chat?.unreadCount ?? 0, 10);
  return Number.isFinite(serverValue) && serverValue > 0 ? serverValue : 0;
}

function setUnreadCount(chatId, nextCount, { persist = true } = {}) {
  const safeChatId = String(chatId ?? "").trim();
  if (!safeChatId) {
    return;
  }
  const safeCount = Math.max(0, Number.parseInt(nextCount, 10) || 0);
  if (safeCount > 0) {
    state.unreadByChat[safeChatId] = safeCount;
  } else {
    delete state.unreadByChat[safeChatId];
  }
  const chat = state.chats.find((entry) => entry.id === safeChatId);
  if (chat) {
    chat.unreadCount = safeCount;
  }
  if (persist) {
    saveUnreadByChat();
  }
}

function markChatAsRead(chatId) {
  setUnreadCount(chatId, 0);
}

function incrementUnreadCount(chatId, amount = 1) {
  const current = getUnreadCountForChat(chatId);
  const delta = Math.max(1, Number.parseInt(amount, 10) || 1);
  setUnreadCount(chatId, current + delta);
}

function syncUnreadMapWithChats() {
  const allowedIds = new Set(state.chats.map((entry) => String(entry.id ?? "").trim()).filter(Boolean));
  let changed = false;
  for (const chatId of Object.keys(state.unreadByChat ?? {})) {
    if (!allowedIds.has(chatId)) {
      delete state.unreadByChat[chatId];
      changed = true;
    }
  }
  for (const chat of state.chats) {
    chat.unreadCount = getUnreadCountForChat(chat);
  }
  if (changed) {
    saveUnreadByChat();
  }
}

function getChatMembersCount(chat) {
  if (!chat) {
    return 0;
  }
  const explicit = Number.parseInt(chat.membersCount, 10);
  if (Number.isFinite(explicit) && explicit >= 0) {
    return explicit;
  }
  return Array.isArray(chat.members) ? chat.members.length : 0;
}

function formatMembersCountLabel(count) {
  const safeCount = Math.max(0, Number(count) || 0);
  if (state.lang === "ru") {
    const mod10 = safeCount % 10;
    const mod100 = safeCount % 100;
    let word = "участников";
    if (mod10 === 1 && mod100 !== 11) {
      word = "участник";
    } else if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) {
      word = "участника";
    }
    return `${safeCount} ${word}`;
  }
  return `${safeCount} ${t("members")}`;
}

function applyTunnelBypassHeader(headers) {
  const hasBypassHeader = Object.keys(headers).some(
    (name) => String(name).toLowerCase() === TUNNEL_BYPASS_HEADER_NAME,
  );
  if (!hasBypassHeader) {
    headers[TUNNEL_BYPASS_HEADER_NAME] = TUNNEL_BYPASS_HEADER_VALUE;
  }
  return headers;
}

