function isLocalOnlyChat(chat) {
  return Boolean(chat?.isLocalOnly || chat?.isSecretChat);
}

function isStandardDirectChat(chat) {
  return Boolean(chat && chat.type === "direct" && !isLocalOnlyChat(chat));
}

function getSecretChatMeta(chatOrId) {
  const safeChatId =
    typeof chatOrId === "string"
      ? String(chatOrId ?? "").trim()
      : String(chatOrId?.id ?? "").trim();
  if (!safeChatId) {
    return null;
  }
  const normalizedId = normalizeSecretChatId(safeChatId);
  const explicitMeta =
    state.secretChats?.[safeChatId] ??
    (safeChatId.startsWith(SECRET_CHAT_ID_PREFIX) ? state.secretChats?.[normalizedId] : null) ??
    null;
  if (explicitMeta) {
    return normalizeSecretChatMeta(explicitMeta, normalizedId);
  }
  if (typeof chatOrId === "object" && chatOrId?.isSecretChat && chatOrId?.secretBaseChatId) {
    return normalizeSecretChatMeta(
      {
        id: safeChatId,
        baseChatId: chatOrId.secretBaseChatId,
        peerUserId: getDirectPeer(chatOrId)?.userId ?? "",
      },
      safeChatId,
    );
  }
  return null;
}

function getSecretChatByBaseChatId(baseChatId) {
  const safeBaseChatId = String(baseChatId ?? "").trim();
  if (!safeBaseChatId) {
    return null;
  }
  return (
    Object.values(state.secretChats ?? {})
      .map((entry) => normalizeSecretChatMeta(entry))
      .find((entry) => entry?.baseChatId === safeBaseChatId) ?? null
  );
}

function getSecretChatMessages(chatId) {
  const safeChatId = normalizeSecretChatId(chatId);
  if (!safeChatId) {
    return [];
  }
  const messages = state.secretChatMessages?.[safeChatId];
  return Array.isArray(messages) ? [...messages] : [];
}

function getSecretChatLastMessage(chatId) {
  const messages = getSecretChatMessages(chatId);
  if (!messages.length) {
    return null;
  }
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (!isSecretMessageHidden(chatId, message.id)) {
      return message;
    }
  }
  return messages[messages.length - 1] ?? null;
}

function buildVirtualSecretChat(baseChat, meta) {
  if (!isStandardDirectChat(baseChat) || !meta?.id) {
    return null;
  }
  return {
    ...baseChat,
    id: meta.id,
    isLocalOnly: true,
    isSecretChat: true,
    secretBaseChatId: baseChat.id,
    lastMessage: getSecretChatLastMessage(meta.id),
    unreadCount: getUnreadCountForChat(meta.id),
    updatedAt: getSecretChatLastMessage(meta.id)?.createdAt || meta.createdAt || baseChat.updatedAt,
  };
}

function buildChatsWithVirtualSecrets(sourceChats = []) {
  const serverChats = Array.isArray(sourceChats)
    ? sourceChats
      .map((entry) => normalizeIncomingChatPayload(entry))
      .filter((entry) => entry && !isLocalOnlyChat(entry))
    : [];
  const nextChats = [];
  for (const chat of serverChats) {
    nextChats.push(chat);
    if (!isStandardDirectChat(chat) || isSavedMessagesChat(chat)) {
      continue;
    }
    const secretMeta = getSecretChatByBaseChatId(chat.id);
    const virtualChat = buildVirtualSecretChat(chat, secretMeta);
    if (virtualChat) {
      nextChats.push(virtualChat);
    }
  }
  return nextChats;
}

function rebuildChatsWithVirtualSecrets(sourceChats = null) {
  const baseChats = Array.isArray(sourceChats) ? sourceChats : state.chats.filter((entry) => !isLocalOnlyChat(entry));
  state.chats = buildChatsWithVirtualSecrets(baseChats);
}

function getSecretMessageKey(chatId, messageId) {
  const safeChatId = String(chatId ?? "").trim();
  const safeMessageId = String(messageId ?? "").trim();
  if (!safeChatId || !safeMessageId) {
    return "";
  }
  return `${safeChatId}:${safeMessageId}`;
}

function clearSecretMessageExpiryTimer(messageKey) {
  const safeKey = String(messageKey ?? "").trim();
  if (!safeKey || !secretMessageExpiryTimers[safeKey]) {
    return;
  }
  clearTimeout(secretMessageExpiryTimers[safeKey]);
  delete secretMessageExpiryTimers[safeKey];
}

function getSecretMessageExpiry(chatId, messageId) {
  const key = getSecretMessageKey(chatId, messageId);
  if (!key) {
    return 0;
  }
  const expiresAt = Number.parseInt(state.secretHiddenMessages?.[key] ?? 0, 10);
  return Number.isFinite(expiresAt) && expiresAt > 0 ? expiresAt : 0;
}

function isSecretMessageHidden(chatId, messageId, now = Date.now()) {
  const expiresAt = getSecretMessageExpiry(chatId, messageId);
  return expiresAt > 0 && expiresAt <= now;
}

function setSecretMessageExpiry(chatId, messageId, expiresAt) {
  const key = getSecretMessageKey(chatId, messageId);
  if (!key) {
    return 0;
  }
  const safeExpiresAt = Number.parseInt(expiresAt, 10);
  if (!Number.isFinite(safeExpiresAt) || safeExpiresAt <= 0) {
    delete state.secretHiddenMessages[key];
    clearSecretMessageExpiryTimer(key);
    saveSecretHiddenMessages();
    return 0;
  }
  state.secretHiddenMessages[key] = safeExpiresAt;
  saveSecretHiddenMessages();
  return safeExpiresAt;
}

function pruneSecretMessageExpiries(chatId, keepFuture = true) {
  const safeChatId = String(chatId ?? "").trim();
  if (!safeChatId) {
    return;
  }
  const now = Date.now();
  let dirty = false;
  for (const [key, value] of Object.entries(state.secretHiddenMessages ?? {})) {
    if (!key.startsWith(`${safeChatId}:`)) {
      continue;
    }
    const expiresAt = Number.parseInt(value, 10);
    if (!Number.isFinite(expiresAt) || expiresAt <= 0 || (!keepFuture || expiresAt > now)) {
      delete state.secretHiddenMessages[key];
      clearSecretMessageExpiryTimer(key);
      dirty = true;
    }
  }
  if (dirty) {
    saveSecretHiddenMessages();
  }
}

function isSecretChat(chatId) {
  return Boolean(getSecretChatMeta(chatId));
}

function getSecretChatTimer(chatId) {
  const safeChatId = normalizeSecretChatId(chatId);
  if (!safeChatId) {
    return 0;
  }
  const seconds = Number.parseInt(state.secretChatTimers?.[safeChatId] ?? 0, 10);
  return Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
}

function setSecretChatEnabled(chatId, enabled) {
  const meta = normalizeSecretChatMeta(chatId, typeof chatId === "string" ? chatId : chatId?.id);
  if (!meta?.id) {
    return "";
  }
  if (enabled) {
    const existing = getSecretChatMeta(meta.id);
    state.secretChats[meta.id] = {
      ...existing,
      ...meta,
      createdAt: existing?.createdAt || meta.createdAt || new Date().toISOString(),
    };
  } else {
    delete state.secretChats[meta.id];
    delete state.secretChatTimers[meta.id];
    delete state.secretChatMessages[meta.id];
    pruneSecretMessageExpiries(meta.id, false);
    saveSecretChatTimers();
    saveSecretChatMessages();
  }
  saveSecretChats();
  rebuildChatsWithVirtualSecrets();
  syncUnreadMapWithChats();
  return meta.id;
}

function setSecretChatTimer(chatId, seconds) {
  const safeChatId = normalizeSecretChatId(chatId);
  if (!safeChatId) {
    return 0;
  }
  const safeSeconds = Number.parseInt(seconds, 10);
  if (!Number.isFinite(safeSeconds) || safeSeconds <= 0) {
    delete state.secretChatTimers[safeChatId];
    pruneSecretMessageExpiries(safeChatId, false);
    saveSecretChatTimers();
    return 0;
  }
  state.secretChatTimers[safeChatId] = safeSeconds;
  pruneSecretMessageExpiries(safeChatId, true);
  saveSecretChatTimers();
  return safeSeconds;
}

function getSecretTimerOptions() {
  return [
    { value: "off", label: t("secretChatTimerOff") },
    { value: "1", label: t("secretChatTimer1s") },
    { value: "5", label: t("secretChatTimer5s") },
    { value: "10", label: t("secretChatTimer10s") },
    { value: "30", label: t("secretChatTimer30s") },
    { value: "60", label: t("secretChatTimer1m") },
    { value: "3600", label: t("secretChatTimer1h") },
    { value: "86400", label: t("secretChatTimer1d") },
  ];
}

function formatSecretTimerLabel(seconds) {
  const safeSeconds = Number.parseInt(seconds, 10);
  if (!Number.isFinite(safeSeconds) || safeSeconds <= 0) {
    return t("secretChatTimerOff");
  }
  const option = getSecretTimerOptions().find((entry) => Number.parseInt(entry.value, 10) === safeSeconds);
  return option?.label ?? `${safeSeconds}s`;
}

async function promptSecretChatTimer(chatId) {
  const safeChatId = String(chatId ?? "").trim();
  if (!safeChatId) {
    return null;
  }
  const currentValue = getSecretChatTimer(safeChatId);
  const selected = await selectDialog({
    title: t("secretChatTimer"),
    value: currentValue > 0 ? String(currentValue) : "off",
    options: getSecretTimerOptions(),
    submitText: t("saveSettings"),
  });
  if (selected === null) {
    return null;
  }
  return setSecretChatTimer(safeChatId, selected === "off" ? 0 : selected);
}

function setSecretChatMessages(chatId, messages) {
  const safeChatId = normalizeSecretChatId(chatId);
  if (!safeChatId) {
    return [];
  }
  const nextMessages = Array.isArray(messages)
    ? messages
        .filter((entry) => entry && typeof entry === "object")
        .map((entry) => ({
          ...entry,
          chatId: safeChatId,
        }))
    : [];
  if (nextMessages.length) {
    state.secretChatMessages[safeChatId] = nextMessages;
  } else {
    delete state.secretChatMessages[safeChatId];
  }
  saveSecretChatMessages();
  rebuildChatsWithVirtualSecrets();
  return nextMessages;
}

function scheduleSecretMessageExpiry(chatId, message) {
  const safeChatId = String(chatId ?? "").trim();
  const safeMessageId = String(message?.id ?? "").trim();
  if (!safeChatId || !safeMessageId || !isSecretChat(safeChatId)) {
    return;
  }
  const timerSeconds = getSecretChatTimer(safeChatId);
  if (timerSeconds <= 0) {
    return;
  }

  const messageKey = getSecretMessageKey(safeChatId, safeMessageId);
  const now = Date.now();
  let expiresAt = getSecretMessageExpiry(safeChatId, safeMessageId);
  if (!expiresAt) {
    expiresAt = setSecretMessageExpiry(safeChatId, safeMessageId, now + timerSeconds * 1000);
  }
  if (expiresAt <= now) {
    clearSecretMessageExpiryTimer(messageKey);
    if (safeChatId === state.activeChatId) {
      renderMessages({ keepScrollPosition: true });
    }
    return;
  }
  if (secretMessageExpiryTimers[messageKey]) {
    return;
  }
  secretMessageExpiryTimers[messageKey] = setTimeout(() => {
    clearSecretMessageExpiryTimer(messageKey);
    if (safeChatId === state.activeChatId) {
      renderMessages({ keepScrollPosition: true });
      updatePinnedStrip();
    }
  }, Math.max(20, expiresAt - now));
}

