function reindexUnreadCounters() {
  const nextUnreadByChat = {};
  for (const chat of state.chats) {
    const chatId = String(chat?.id ?? "").trim();
    if (!chatId) {
      continue;
    }
    const unreadCount = Math.max(0, Number.parseInt(chat?.unreadCount ?? 0, 10) || 0);
    if (unreadCount > 0) {
      nextUnreadByChat[chatId] = unreadCount;
    }
    chat.unreadCount = unreadCount;
  }
  state.unreadByChat = nextUnreadByChat;
  saveUnreadByChat();
  renderChats();
  renderActiveChat();
}

