const PREMIUM_BADGE_DEFAULT_COLOR = "#f4c84c";

function normalizePremiumBadgeColor(value, fallback = PREMIUM_BADGE_DEFAULT_COLOR) {
  const normalizedFallback = /^#[0-9a-f]{6}$/i.test(String(fallback ?? "").trim())
    ? String(fallback).trim().toLowerCase()
    : PREMIUM_BADGE_DEFAULT_COLOR;
  const safeValue = String(value ?? "").trim().toLowerCase();
  if (/^#[0-9a-f]{6}$/i.test(safeValue)) {
    return safeValue;
  }
  return normalizedFallback;
}

function normalizeClientPremiumBadge(input = {}) {
  const source = input && typeof input === "object" ? input : {};
  const allowedTypes = new Set(["none", "star", "svg", "photo"]);
  const requestedType = String(source.type ?? "").trim().toLowerCase();
  return {
    type: allowedTypes.has(requestedType) ? requestedType : "star",
    star: String(source.star ?? "⭐").trim().slice(0, 8) || "⭐",
    svg: String(source.svg ?? "").trim().slice(0, 120_000),
    photo: String(source.photo ?? "").trim().slice(0, 2_000_000),
    size: Math.max(12, Math.min(36, Number.parseInt(source.size ?? 16, 10) || 16)),
    offsetX: Math.max(-24, Math.min(24, Number.parseInt(source.offsetX ?? 0, 10) || 0)),
    offsetY: Math.max(-24, Math.min(24, Number.parseInt(source.offsetY ?? 0, 10) || 0)),
    bgColor: normalizePremiumBadgeColor(source.bgColor, PREMIUM_BADGE_DEFAULT_COLOR),
  };
}

function parsePremiumBooleanLike(value) {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "number") {
    if (value === 1) {
      return true;
    }
    if (value === 0) {
      return false;
    }
  }
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (!normalized) {
      return null;
    }
    if (["1", "true", "yes", "on", "premium", "plus"].includes(normalized)) {
      return true;
    }
    if (["0", "false", "no", "off", "free"].includes(normalized)) {
      return false;
    }
  }
  return null;
}

function isPremiumUntilActive(value) {
  const safeValue = String(value ?? "").trim();
  if (!safeValue) {
    return false;
  }
  const timestamp = Date.parse(safeValue);
  return Number.isFinite(timestamp) && timestamp > Date.now();
}

function normalizePremiumUserLike(userLike) {
  if (!userLike || typeof userLike !== "object") {
    return userLike ?? null;
  }
  const explicitPremium =
    parsePremiumBooleanLike(userLike.isPremium) ??
    parsePremiumBooleanLike(userLike.isPlus) ??
    parsePremiumBooleanLike(userLike.plus) ??
    parsePremiumBooleanLike(userLike.premium);
  const isPremium = Boolean(explicitPremium === true || isPremiumUntilActive(userLike.premiumUntil));
  return {
    ...userLike,
    isPremium,
    isPlus: isPremium,
    premium: isPremium,
    premiumBadge: normalizeClientPremiumBadge(userLike.premiumBadge),
  };
}

function normalizeIncomingMessagePayload(messageLike) {
  if (!messageLike || typeof messageLike !== "object") {
    return null;
  }
  const normalized = { ...messageLike };
  if (normalized.sender && typeof normalized.sender === "object") {
    normalized.sender = normalizePremiumUserLike(normalized.sender);
  }
  if (normalized.replyTo && typeof normalized.replyTo === "object" && normalized.replyTo.sender) {
    normalized.replyTo = {
      ...normalized.replyTo,
      sender: normalizePremiumUserLike(normalized.replyTo.sender),
    };
  }
  return normalized;
}

function normalizeIncomingMessagesList(messages) {
  if (!Array.isArray(messages)) {
    return [];
  }
  return messages
    .map((entry) => normalizeIncomingMessagePayload(entry))
    .filter((entry) => entry && typeof entry === "object");
}

function normalizeIncomingChatPayload(chatLike) {
  if (!chatLike || typeof chatLike !== "object") {
    return null;
  }
  const normalized = { ...chatLike };
  if (Array.isArray(chatLike.members)) {
    normalized.members = chatLike.members.map((member) => normalizePremiumUserLike(member));
  }
  if (chatLike.lastMessage && typeof chatLike.lastMessage === "object") {
    normalized.lastMessage = normalizeIncomingMessagePayload(chatLike.lastMessage);
  }
  if (chatLike.owner && typeof chatLike.owner === "object") {
    normalized.owner = normalizePremiumUserLike(chatLike.owner);
  }
  return normalized;
}

function isPremiumUserLike(userLike) {
  return Boolean(normalizePremiumUserLike(userLike)?.isPremium);
}

function getPremiumBadgeForUser(userLike) {
  const normalizedUserLike = normalizePremiumUserLike(userLike);
  if (!normalizedUserLike?.isPremium) {
    return null;
  }
  const badge = normalizeClientPremiumBadge(normalizedUserLike.premiumBadge);
  if (badge.type === "none") {
    return null;
  }
  return badge;
}

function resolvePremiumBadgeImageSource(rawValue) {
  const safeValue = String(rawValue ?? "").trim();
  if (!safeValue) {
    return "";
  }
  if (safeValue.startsWith("<svg")) {
    return `data:image/svg+xml;utf8,${encodeURIComponent(safeValue)}`;
  }
  return safeValue;
}

function createPremiumBadgeNode(userLike) {
  const badge = getPremiumBadgeForUser(userLike);
  if (!badge) {
    return null;
  }

  const node = document.createElement("span");
  node.className = "premium-name-badge";
  node.style.width = `${badge.size}px`;
  node.style.height = `${badge.size}px`;
  node.style.minWidth = `${badge.size}px`;
  node.style.setProperty("--badge-color", normalizePremiumBadgeColor(badge.bgColor, PREMIUM_BADGE_DEFAULT_COLOR));
  if (badge.offsetX || badge.offsetY) {
    node.style.transform = `translate(${badge.offsetX}px, ${badge.offsetY}px)`;
  } else {
    node.style.removeProperty("transform");
  }

  if (badge.type === "star") {
    node.textContent = badge.star || "⭐";
    return node;
  }

  const sourceValue = badge.type === "photo" ? badge.photo : badge.svg;
  const imageSrc = resolvePremiumBadgeImageSource(sourceValue);
  if (!imageSrc) {
    node.textContent = badge.star || "⭐";
    return node;
  }

  const image = document.createElement("img");
  image.src = imageSrc;
  image.alt = "Plus";
  image.loading = "lazy";
  image.decoding = "async";
  node.appendChild(image);
  return node;
}

function renderNameWithPremiumBadge(targetNode, displayName, userLike, options = {}) {
  if (!targetNode) {
    return;
  }
  const safeName = String(displayName ?? "").trim() || t("unknownUser");
  const useEllipsis = options.ellipsis !== false;
  targetNode.textContent = "";

  const wrap = document.createElement("span");
  wrap.className = "premium-name";

  const text = document.createElement("span");
  text.className = `premium-name-text${useEllipsis ? " ellipsis" : ""}`;
  text.textContent = safeName;
  wrap.appendChild(text);

  const badge = createPremiumBadgeNode(userLike);
  if (badge) {
    wrap.appendChild(badge);
  }

  targetNode.appendChild(wrap);
}

function getDirectPeer(chat) {
  if (!chat || chat.type !== "direct") {
    return null;
  }

  const members = Array.isArray(chat.members) ? chat.members : [];
  const peer = members.find((entry) => entry.userId !== state.user?.id) ?? null;
  return normalizePremiumUserLike(peer);
}

function isBotUser(userLike) {
  const username = String(userLike?.username ?? "").trim().toLowerCase();
  return Boolean(userLike?.isBot || userLike?.isSystemBot || username.endsWith("_bot"));
}

function getUserStatusLabelForChat(chatId, userLike) {
  if (!userLike) {
    return "";
  }
  if (isBotUser(userLike)) {
    return t("botStatus");
  }
  const userId = String(userLike.userId ?? userLike.id ?? "").trim();
  const online = userId ? isMemberOnline(chatId, userId) : false;
  if (online) {
    return t("onlineNow");
  }
  return formatRelativeTime(getMemberLastActivityAt(chatId, userId));
}

function isSavedMessagesChat(chat) {
  if (!chat || chat.type !== "direct") {
    return false;
  }
  return !getDirectPeer(chat);
}

function fontSizeToScalePercent(fontSize) {
  const safe = normalizeFontSize(fontSize);
  const raw = Math.round((safe / 16) * 100);
  return Math.max(80, Math.min(160, raw));
}

function scalePercentToFontSize(percent) {
  const safe = Number(percent);
  const clamped = Number.isFinite(safe) ? Math.max(80, Math.min(160, safe)) : 100;
  return normalizeFontSize(Math.round((16 * clamped) / 100));
}

function getLanguageDisplayLabel() {
  return state.lang === "ru" ? "Русский" : "English";
}

function bindSettingsHome() {
  if (!elements.settingsHomeCard) {
    return;
  }

  const displayName = getUserDisplayName(state.user);
  if (elements.settingsHomeName) {
    renderNameWithPremiumBadge(elements.settingsHomeName, displayName || "User", state.user, { ellipsis: true });
  }
  if (elements.settingsHomePhone) {
    elements.settingsHomePhone.textContent = state.user?.phone ?? "-";
  }
  if (elements.settingsHomeUsername) {
    const starsLabel = Math.max(0, Number.parseInt(state.user?.starsBalance ?? 0, 10) || 0);
    elements.settingsHomeUsername.textContent = `@${state.user?.username ?? ""}${starsLabel > 0 ? ` · ⭐ ${starsLabel}` : ""}`;
  }
  if (elements.settingsHomeLanguageValue) {
    elements.settingsHomeLanguageValue.textContent = getLanguageDisplayLabel();
  }
  if (elements.settingsHomeAvatar) {
    applyAvatarNode(elements.settingsHomeAvatar, displayName || "Y", state.user?.avatar ?? "", "Y");
  }

  syncSettingsHomeTabs();

  const baseSize = normalizeFontSize(state.settings?.appearance?.fontSize);
  const percent = fontSizeToScalePercent(baseSize);
  if (elements.settingsScaleRange) {
    elements.settingsScaleRange.value = String(percent);
  }
  if (elements.settingsScaleValue) {
    elements.settingsScaleValue.textContent = `${percent}%`;
  }
  if (elements.settingsScaleDefault) {
    elements.settingsScaleDefault.checked = percent === 100;
  }
}

function syncSettingsHomeTabs() {
  const tabs = [...document.querySelectorAll(".settings-home-tab")];
  if (!tabs.length) {
    return;
  }
  const rawSection = String(state.settingsSection ?? "").trim() || "account";
  const activeSection = (() => {
    if (rawSection.startsWith("notifications-")) return "notifications";
    if (rawSection.startsWith("stories-")) return "stories";
    if (rawSection.startsWith("privacy")) return "account";
    if (rawSection === "qr" || rawSection === "language" || rawSection === "developer") return "account";
    return rawSection;
  })();
  for (const tab of tabs) {
    const target = String(tab.dataset.settingsAction ?? "").trim();
    tab.classList.toggle("active", target === activeSection);
  }
}

async function saveSettingsPayloadSilently() {
  if (!state.token) {
    return;
  }
  const payload = await api("/api/me/settings", {
    method: "PATCH",
    body: collectSettingsPayload(),
  });
  state.settings = payload.settings;
  bindSettingsToForm();
}

async function applyScaleFromSettingsHome(percentValue) {
  const percent = Number(percentValue);
  const safePercent = Number.isFinite(percent) ? Math.max(80, Math.min(160, Math.round(percent / 5) * 5)) : 100;
  const fontSize = scalePercentToFontSize(safePercent);
  const chatFontSize = normalizeChatFontSize(fontSize);

  if (elements.settingsScaleRange) {
    elements.settingsScaleRange.value = String(safePercent);
  }
  if (elements.settingsScaleValue) {
    elements.settingsScaleValue.textContent = `${safePercent}%`;
  }
  if (elements.settingsScaleDefault) {
    elements.settingsScaleDefault.checked = safePercent === 100;
  }

  elements.sFontSize.value = String(fontSize);
  elements.sChatFontSize.value = String(chatFontSize);
  applyAppearance({
    theme: normalizeTheme(state.settings?.appearance?.theme ?? elements.sTheme?.value),
    fontSize,
    chatFontSize,
  });

  await saveSettingsPayloadSilently();
}

function closeSettingsHomeMoreMenu() {
  elements.settingsHomeMoreMenu?.classList.add("hidden");
}

function clearPendingDeepLinkFromUrl() {
  try {
    const params = new URLSearchParams(window.location.search);
    params.delete("yooh_qr");
    params.delete("chatWith");
    params.delete("openChatId");
    const query = params.toString();
    const nextUrl = `${window.location.pathname}${query ? `?${query}` : ""}`;
    window.history.replaceState(window.history.state ?? {}, "", nextUrl);
  } catch {
    // Ignore URL rewrite errors.
  }
}

function findDirectChatByUsername(username) {
  const safeUsername = String(username ?? "").trim().toLowerCase();
  if (!safeUsername) {
    return null;
  }
  return (
    state.chats.find((chat) => {
      if (!isStandardDirectChat(chat)) {
        return false;
      }
      const peer = getDirectPeer(chat);
      return String(peer?.username ?? "").trim().toLowerCase() === safeUsername;
    }) ?? null
  );
}

async function openOrCreateDirectChatByUsername(username) {
  const safeUsername = normalizeDeepLinkUsername(username);
  if (!safeUsername) {
    return null;
  }

  const existing = findDirectChatByUsername(safeUsername);
  if (existing) {
    await loadChats(existing.id, false);
    return existing;
  }

  const payload = await api("/api/chats", {
    method: "POST",
    body: {
      type: "direct",
      memberUsername: safeUsername,
    },
  });
  await loadChats(payload.chat.id, false);
  return payload.chat;
}

function findDirectChatByUserId(userId) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return null;
  }
  return (
    state.chats.find((chat) => {
      if (!isStandardDirectChat(chat)) {
        return false;
      }
      return String(getDirectPeer(chat)?.userId ?? "").trim() === safeUserId;
    }) ?? null
  );
}

function findSecretChatByUserId(userId) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return null;
  }
  return (
    state.chats.find((chat) => {
      if (!isSecretChat(chat.id) || chat.type !== "direct") {
        return false;
      }
      return String(getDirectPeer(chat)?.userId ?? "").trim() === safeUserId;
    }) ?? null
  );
}

async function ensureDirectChatWithUser(userLike) {
  const safeUserId = String(userLike?.id ?? userLike?.userId ?? "").trim();
  if (!safeUserId) {
    return null;
  }
  const existing = findDirectChatByUserId(safeUserId);
  if (existing) {
    return existing;
  }
  const payload = await api("/api/chats", {
    method: "POST",
    body: {
      type: "direct",
      memberId: safeUserId,
    },
  });
  await loadChats(payload.chat.id, false);
  return payload.chat ?? null;
}

async function ensureSecretChatWithUser(userLike) {
  const baseChat = await ensureDirectChatWithUser(userLike);
  if (!baseChat?.id) {
    return null;
  }
  const peerUserId = String(getDirectPeer(baseChat)?.userId ?? userLike?.id ?? userLike?.userId ?? "").trim();
  const existingMeta = getSecretChatByBaseChatId(baseChat.id);
  const secretChatId = setSecretChatEnabled(
    {
      id: existingMeta?.id ?? normalizeSecretChatId(baseChat.id),
      baseChatId: baseChat.id,
      peerUserId,
      createdAt: existingMeta?.createdAt || new Date().toISOString(),
    },
    true,
  );
  return state.chats.find((chat) => chat.id === secretChatId) ?? buildVirtualSecretChat(baseChat, getSecretChatMeta(secretChatId));
}

function findSelfDirectChat() {
  const selfUserId = String(state.user?.id ?? "").trim();
  if (!selfUserId) {
    return null;
  }
  return (
    state.chats.find((chat) => {
      if (!isStandardDirectChat(chat)) {
        return false;
      }
      const peer = getDirectPeer(chat);
      if (!peer?.userId) {
        return true;
      }
      return String(peer.userId) === selfUserId;
    }) ?? null
  );
}

async function getOrCreateSavedMessagesChat() {
  const existing = findSelfDirectChat();
  if (existing) {
    return existing;
  }
  if (!state.user?.id) {
    return null;
  }
  const payload = await api("/api/chats", {
    method: "POST",
    body: {
      type: "direct",
      memberId: state.user.id,
    },
  });
  await loadChats(payload.chat.id, false);
  return payload.chat;
}

async function processPendingDeepLink() {
  const target = normalizeDeepLinkUsername(state.pendingDeepLinkUsername);
  if (!target || !state.user?.username) {
    return;
  }

  if (target.toLowerCase() === String(state.user.username).toLowerCase()) {
    state.pendingDeepLinkUsername = "";
    clearPendingDeepLinkFromUrl();
    return;
  }

  try {
    await openOrCreateDirectChatByUsername(target);
  } catch (error) {
    alert(error.message);
  } finally {
    state.pendingDeepLinkUsername = "";
    clearPendingDeepLinkFromUrl();
  }
}

function closeSettingsSection() {
  state.settingsSection = "";
  state.settingsSectionHistory = [];
  resetSettingsDeveloperTapSequence();
  stopSettingsCameraPreview();
  elements.settingsDetailCard?.classList.add("hidden");
  elements.settingsHomeCard?.classList.remove("hidden");
  const settingsTab = document.getElementById("drawer-tab-settings");
  settingsTab?.scrollTo({ top: 0, left: 0, behavior: "auto" });
  syncSettingsHomeTabs();
  syncDrawerHeader();
}

