function resetSettingsDeveloperTapSequence() {
  state.settingsDeveloperTapCount = 0;
  state.settingsDeveloperTapAt = 0;
}

function registerSettingsDeveloperTap() {
  if (state.drawerTab !== "settings" || elements.settingsHomeCard?.classList.contains("hidden")) {
    resetSettingsDeveloperTapSequence();
    return;
  }
  const now = Date.now();
  if (now - state.settingsDeveloperTapAt > 1400) {
    state.settingsDeveloperTapCount = 0;
  }
  state.settingsDeveloperTapAt = now;
  state.settingsDeveloperTapCount += 1;
  if (state.settingsDeveloperTapCount >= 10) {
    resetSettingsDeveloperTapSequence();
    openSettingsSection("developer");
  }
}

function goBackSettingsSection() {
  stopSettingsCameraPreview();
  if (state.settingsSectionHistory.length) {
    state.settingsSection = state.settingsSectionHistory.pop() ?? "";
    renderSettingsSection();
    const settingsTab = document.getElementById("drawer-tab-settings");
    settingsTab?.scrollTo({ top: 0, left: 0, behavior: "auto" });
    elements.settingsDetailContent?.scrollTo({ top: 0, left: 0, behavior: "auto" });
    syncDrawerHeader();
    return;
  }
  closeSettingsSection();
}

function openSettingsSection(sectionId, options = {}) {
  const { replaceHistory = false } = options;
  const safeSection = String(sectionId ?? "").trim();
  if (!safeSection || !elements.settingsDetailCard || !elements.settingsDetailContent) {
    return;
  }
  if (!replaceHistory && state.settingsSection && state.settingsSection !== safeSection) {
    state.settingsSectionHistory.push(state.settingsSection);
  }
  if (replaceHistory && state.settingsSectionHistory.length) {
    state.settingsSectionHistory[state.settingsSectionHistory.length - 1] = state.settingsSection;
  }
  state.settingsSection = safeSection;
  elements.settingsHomeCard?.classList.add("hidden");
  elements.settingsDetailCard.classList.remove("hidden");
  const settingsTab = document.getElementById("drawer-tab-settings");
  settingsTab?.scrollTo({ top: 0, left: 0, behavior: "auto" });
  elements.settingsDetailContent.scrollTo({ top: 0, left: 0, behavior: "auto" });
  renderSettingsSection();
  syncSettingsHomeTabs();
  syncDrawerHeader();
}

function bindSettingsAutoSaveControl(control, mirror, applyLocal = null) {
  if (!control || !mirror) {
    return;
  }
  control.addEventListener("change", async () => {
    mirror.type === "checkbox" ? (mirror.checked = control.checked) : (mirror.value = control.value);
    if (typeof applyLocal === "function") {
      applyLocal();
    }
    try {
      await saveSettingsPayloadSilently();
    } catch (error) {
      alert(error.message);
    }
  });
}

function createSettingsSwitchRow({ id, icon, label, checked = false }) {
  const row = document.createElement("label");
  row.className = "settings-switch-row";
  row.innerHTML = `
    <span class="settings-switch-main">
      <span class="svg-icon" data-svg-icon="${icon}"></span>
      <span>${label}</span>
    </span>
    <input id="${id}" class="settings-switch-input" type="checkbox" ${checked ? "checked" : ""} />
  `;
  return row;
}

function createSettingsSelectRow({ id, icon, label, value, options = [] }) {
  const row = document.createElement("label");
  row.className = "settings-notify-row";
  row.innerHTML = `
    <span class="settings-switch-main">
      <span class="svg-icon" data-svg-icon="${icon}"></span>
      <span>${label}</span>
    </span>
    <select id="${id}" class="settings-notify-select"></select>
  `;
  const select = row.querySelector("select");
  for (const option of options) {
    const node = document.createElement("option");
    node.value = option.value;
    node.textContent = option.label;
    select.appendChild(node);
  }
  select.value = value;
  return row;
}

function getNotificationSettings() {
  const notifications = state.settings?.notifications ?? {};
  const systemPermissions = notifications.systemPermissions ?? {};
  return {
    ...notifications,
    inAppSounds: notifications.inAppSounds !== false,
    sendSound: notifications.sendSound !== false,
    contactNotifications: notifications.contactNotifications !== false,
    ringtone: normalizeNotificationSoundId(notifications.ringtone, { kind: "call" }),
    messageSound: normalizeNotificationSoundId(notifications.messageSound ?? "iphone-x", { kind: "message" }),
    bannerStyle: String(notifications.bannerStyle ?? "temporary"),
    previewMode: String(notifications.previewMode ?? "always"),
    callVibration: String(notifications.callVibration ?? "always"),
    badgeMode: String(notifications.badgeMode ?? "messages"),
    badgeIncludeChannels: notifications.badgeIncludeChannels !== false,
    badgeIncludeMuted: Boolean(notifications.badgeIncludeMuted),
    customSounds: normalizeCustomNotificationSounds(notifications.customSounds ?? state.customNotificationSounds),
    systemPermissions: {
      allow: systemPermissions.allow !== false,
      lockScreen: systemPermissions.lockScreen !== false,
      notificationCenter: systemPermissions.notificationCenter !== false,
      banners: systemPermissions.banners !== false,
      sounds: systemPermissions.sounds !== false,
      badges: systemPermissions.badges !== false,
    },
  };
}

const BUILTIN_CALL_SOUND_OPTIONS = [
  { value: "iphone-x", label: "iPhone X", src: "/sounds/iphone-x-ringtone.mp3" },
  { value: "iphone-5", label: "iPhone 5", src: "/sounds/iphone-5-ringtone.mp3" },
  { value: "iphone-7", label: "iPhone 7", src: "/sounds/iphone-7-ringtone.mp3" },
  { value: "smartphone", label: "Smartphone", src: "/sounds/smartphone-ringtone.mp3" },
];

const BUILTIN_MESSAGE_SOUND_OPTIONS = [
  { value: "iphone-x", label: "iPhone X", src: "/sounds/notification.mp3" },
  { value: "iphone-5", label: "iPhone 5", src: "/sounds/iphone-5-ringtone.mp3" },
  { value: "iphone-7", label: "iPhone 7", src: "/sounds/iphone-7-ringtone.mp3" },
  { value: "smartphone", label: "Smartphone", src: "/sounds/smartphone-ringtone.mp3" },
];

function getBuiltInNotificationSoundOptions(kind = "message") {
  return kind === "call" ? BUILTIN_CALL_SOUND_OPTIONS : BUILTIN_MESSAGE_SOUND_OPTIONS;
}

function normalizeNotificationSoundId(soundId, { includeDefault = false, kind = "message" } = {}) {
  const safeId = String(soundId ?? "").trim();
  if (includeDefault && safeId === "default") {
    return "default";
  }
  const builtInIds = getBuiltInNotificationSoundOptions(kind).map((entry) => entry.value);
  if (builtInIds.includes(safeId)) {
    return safeId;
  }
  if (getCustomNotificationSounds().some((entry) => entry.id === safeId)) {
    return safeId;
  }
  return "iphone-x";
}

function normalizeCustomNotificationSounds(source) {
  const entries = Array.isArray(source) ? source : Object.values(source ?? {});
  return entries
    .map((entry) => ({
      id: String(entry?.id ?? "").trim(),
      label: String(entry?.label ?? "").trim(),
      dataUrl: String(entry?.dataUrl ?? "").trim(),
      mimeType: String(entry?.mimeType ?? "").trim(),
      sizeBytes: Math.max(0, Number(entry?.sizeBytes ?? 0) || 0),
      durationSeconds: Math.max(0, Number(entry?.durationSeconds ?? 0) || 0),
    }))
    .filter((entry) => entry.id && entry.label && entry.dataUrl)
    .slice(0, 24);
}

function updateNotificationSettings(patch = {}) {
  if (!state.settings || typeof state.settings !== "object") {
    state.settings = {};
  }
  const current = getNotificationSettings();
  const nextPatch = { ...patch };
  if (Object.hasOwn(nextPatch, "ringtone")) {
    nextPatch.ringtone = normalizeNotificationSoundId(nextPatch.ringtone, { kind: "call" });
  }
  if (Object.hasOwn(nextPatch, "messageSound")) {
    nextPatch.messageSound = normalizeNotificationSoundId(nextPatch.messageSound, { kind: "message" });
  }
  state.settings.notifications = {
    ...current,
    ...nextPatch,
  };
}

function getStoryFeatureSettings() {
  const stories = state.settings?.stories ?? {};
  return {
    ...stories,
    stealthMode: Boolean(stories.stealthMode),
  };
}

function updateStoryFeatureSettings(patch = {}) {
  if (!state.settings || typeof state.settings !== "object") {
    state.settings = {};
  }
  const current = getStoryFeatureSettings();
  state.settings.stories = {
    ...current,
    ...patch,
  };
}

function isStoryStealthModeEnabled() {
  return Boolean(getStoryFeatureSettings().stealthMode);
}

function getCustomNotificationSounds() {
  return normalizeCustomNotificationSounds(state.customNotificationSounds);
}

function saveCustomNotificationSounds() {
  try {
    localStorage.setItem("yooh_notification_sounds", JSON.stringify(getCustomNotificationSounds()));
  } catch {
    // Ignore localStorage errors.
  }
}

async function syncCustomNotificationSoundsToBackend() {
  if (!state.token) {
    return;
  }
  updateNotificationSettings({ customSounds: getCustomNotificationSounds() });
  const payload = await api("/api/me/settings", {
    method: "PATCH",
    body: {
      notifications: {
        ...getNotificationSettings(),
      },
    },
    retryTransient: true,
    retries: 3,
    retryDelayMs: 450,
  });
  if (payload?.settings && typeof payload.settings === "object") {
    state.settings = payload.settings;
  }
}

function getNotificationSoundOptions({ includeDefault = false, kind = "message" } = {}) {
  const options = [];
  if (includeDefault) {
    options.push({ value: "default", label: t("chatNotificationUseDefault") });
  }
  options.push(...getBuiltInNotificationSoundOptions(kind));
  for (const sound of getCustomNotificationSounds()) {
    options.push({ value: sound.id, label: sound.label });
  }
  return options;
}

function getBuiltInNotificationSoundEntry(soundId, { kind = "message" } = {}) {
  const safeId = normalizeNotificationSoundId(soundId, { kind });
  return getBuiltInNotificationSoundOptions(kind).find((entry) => entry.value === safeId) ?? null;
}

function getNotificationSoundLabel(soundId, options = {}) {
  const safeId = normalizeNotificationSoundId(soundId, options);
  const match = getNotificationSoundOptions(options).find((entry) => entry.value === safeId);
  return match?.label ?? safeId;
}

async function blobToDataUrl(blob) {
  return await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
    reader.onerror = () => reject(new Error("Failed to read audio blob"));
    reader.readAsDataURL(blob);
  });
}

async function getAudioBlobDurationSeconds(blob) {
  const objectUrl = URL.createObjectURL(blob);
  try {
    const audio = document.createElement("audio");
    audio.preload = "metadata";
    audio.src = objectUrl;
    return await new Promise((resolve) => {
      const cleanup = () => {
        audio.onloadedmetadata = null;
        audio.onerror = null;
        URL.revokeObjectURL(objectUrl);
      };
      audio.onloadedmetadata = () => {
        const duration = Number(audio.duration);
        cleanup();
        resolve(Number.isFinite(duration) ? duration : 0);
      };
      audio.onerror = () => {
        cleanup();
        resolve(0);
      };
    });
  } catch {
    URL.revokeObjectURL(objectUrl);
    return 0;
  }
}

async function saveCustomNotificationSoundEntry({ blob, label = "", soundId = "" } = {}) {
  if (!(blob instanceof Blob)) {
    throw new Error(t("settingsNotificationSoundInvalid"));
  }
  const safeMimeType = String(blob.type || "").toLowerCase();
  const supportedSound = ["audio/mpeg", "audio/mp3", "audio/mp4", "audio/x-m4a", "audio/aac", "audio/ogg", "audio/opus"].some(
    (value) => safeMimeType.includes(value.replace("audio/", "")) || safeMimeType === value,
  );
  const durationSeconds = await getAudioBlobDurationSeconds(blob);
  if (!supportedSound || blob.size > 300 * 1024 || durationSeconds <= 0 || durationSeconds > 5.05) {
    throw new Error(t("settingsNotificationSoundInvalid"));
  }
  const safeId = String(soundId ?? "").trim() || `custom:${Date.now().toString(36)}:${Math.random().toString(36).slice(2, 8)}`;
  const baseLabel = String(label ?? "").trim() || "Custom sound";
  const nextEntry = {
    id: safeId,
    label: baseLabel.length > 48 ? `${baseLabel.slice(0, 45)}...` : baseLabel,
    dataUrl: await blobToDataUrl(blob),
    mimeType: blob.type || "audio/mpeg",
    sizeBytes: blob.size,
    durationSeconds,
  };
  const nextSounds = getCustomNotificationSounds().filter((entry) => entry.id !== safeId);
  nextSounds.unshift(nextEntry);
  state.customNotificationSounds = nextSounds.slice(0, 24);
  saveCustomNotificationSounds();
  updateNotificationSettings({ customSounds: state.customNotificationSounds });
  try {
    await syncCustomNotificationSoundsToBackend();
  } catch {
    // Keep the local copy even if backend sync fails.
  }
  return nextEntry;
}

async function saveCustomNotificationSoundFromMessage(message) {
  if (!message?.file?.id || !String(message.file.mimeType ?? "").startsWith("audio/")) {
    return;
  }
  const response = await fetch(buildFileUrl(message.file.id, "download"), {
    headers: state.token ? { Authorization: `Bearer ${state.token}` } : {},
  });
  if (!response.ok) {
    throw new Error(`Failed to load sound: ${response.status}`);
  }
  const blob = await response.blob();
  await saveCustomNotificationSoundEntry({
    blob,
    soundId: `custom:${message.file.id}`,
    label: getDisplayFileName(message.file.originalName ?? message.text ?? "Custom sound"),
  });
}

async function saveCustomNotificationSoundFromUpload(file) {
  if (!(file instanceof Blob)) {
    throw new Error(t("settingsNotificationSoundInvalid"));
  }
  return saveCustomNotificationSoundEntry({
    blob: file,
    label: String(file.name ?? "Custom sound").trim() || "Custom sound",
  });
}

const STICKER_PACK_OPTIONS = [
  { id: "telegram-basics", title: "Telegram Basics", subtitleKey: "settingsStickerPackOfficial" },
  { id: "funny-faces", title: "Funny Faces", subtitleKey: "settingsStickerPackFun" },
  { id: "mood-reactions", title: "Mood Reactions", subtitleKey: "settingsStickerPackMood" },
];

function getDataStorageSettings() {
  const data = state.settings?.data ?? {};
  return {
    ...data,
    cacheSizeMb: Math.max(64, Number(data.cacheSizeMb ?? 768) || 768),
    keepMedia: String(data.keepMedia ?? "month"),
    autoplayVideos: Boolean(data.autoplayVideos),
    pauseMusicOnVideoMessages: data.pauseMusicOnVideoMessages !== false,
    autoDownloadMobile: data.autoDownloadMobile !== false,
    autoDownloadWifi: data.autoDownloadWifi !== false,
    autoDownloadRoaming: Boolean(data.autoDownloadRoaming),
    useLessDataForCalls: String(data.useLessDataForCalls ?? "mobile"),
    uploadPhotoQuality: String(data.uploadPhotoQuality ?? "optimized"),
    uploadVideoQuality: String(data.uploadVideoQuality ?? "optimized"),
  };
}

function updateDataStorageSettings(patch = {}) {
  if (!state.settings || typeof state.settings !== "object") {
    state.settings = {};
  }
  const current = getDataStorageSettings();
  state.settings.data = {
    ...current,
    ...patch,
  };
}

function getStickerSettings() {
  const raw = state.settings?.stickersEmoji ?? {};
  const installedSets = Array.isArray(raw.installedSets)
    ? raw.installedSets.map((entry) => String(entry ?? "").trim()).filter(Boolean)
    : ["telegram-basics"];
  return {
    ...raw,
    suggestedStickers: raw.suggestedStickers !== false,
    emojiStatus: String(raw.emojiStatus ?? "none"),
    installedSets,
  };
}

function updateStickerSettings(patch = {}) {
  if (!state.settings || typeof state.settings !== "object") {
    state.settings = {};
  }
  const current = getStickerSettings();
  state.settings.stickersEmoji = {
    ...current,
    ...patch,
  };
}

