function openSettingsNotificationChat(chatId, options = {}) {
  state.settingsNotificationChatId = String(chatId ?? "").trim();
  openSettingsSection("notifications-chat", options);
}

async function promptNotificationExceptionChat() {
  const candidates = state.chats
    .filter((chat) => !isChatNotificationException(chat.id))
    .map((chat) => ({ value: chat.id, label: getChatTitle(chat) }));
  if (!candidates.length) {
    return "";
  }
  const chatId = await selectDialog({
    title: t("settingsNotificationAddException"),
    options: candidates,
    submitText: t("settingsNotificationAddException"),
  });
  return String(chatId ?? "").trim();
}

function renderSettingsNotificationExceptionsSection() {
  if (!elements.settingsDetailContent) {
    return;
  }

  const wrap = document.createElement("div");
  wrap.className = "settings-section-body";

  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.id = "settings-notification-add-exception-btn";
  addButton.className = "small ghost";
  addButton.textContent = t("settingsNotificationAddException");
  addButton.addEventListener("click", async () => {
    const chatId = await promptNotificationExceptionChat();
    if (!chatId) {
      return;
    }
    setChatNotificationConfig(chatId, { custom: true });
    openSettingsNotificationChat(chatId);
  });
  wrap.appendChild(addButton);

  const chats = getChatNotificationExceptionChats();
  if (chats.length) {
    for (const chat of chats) {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "settings-privacy-exception-row settings-notify-chat-row";
      row.dataset.chatId = chat.id;
      row.innerHTML = `
        <span class="settings-privacy-row-main">
          <span class="svg-icon" data-svg-icon="${isChatNotificationsEnabled(chat.id) ? "alert" : "volume-off"}"></span>
          <span>${escapeHtml(getChatTitle(chat))}</span>
        </span>
        <span class="settings-privacy-row-value">${escapeHtml(getChatNotificationSummary(chat.id))}</span>
      `;
      row.addEventListener("click", () => {
        openSettingsNotificationChat(chat.id);
      });
      wrap.appendChild(row);
    }
  } else {
    const empty = document.createElement("div");
    empty.className = "settings-list-empty";
    empty.textContent = t("settingsNotificationNoExceptions");
    wrap.appendChild(empty);
  }

  elements.settingsDetailContent.innerHTML = "";
  elements.settingsDetailContent.appendChild(wrap);
  renderSvgIcons(elements.settingsDetailContent);
}

function renderSettingsNotificationChatSection() {
  if (!elements.settingsDetailContent) {
    return;
  }
  const chat = state.chats.find((entry) => entry.id === state.settingsNotificationChatId) ?? null;
  if (!chat) {
    goBackSettingsSection();
    return;
  }

  const config = getChatNotificationConfig(chat.id);
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body settings-privacy-subsection";
  wrap.innerHTML = `
    <div class="settings-privacy-subtitle">${escapeHtml(getChatTitle(chat))}</div>
    <label class="settings-switch-row">
      <span class="settings-switch-main">
        <span class="svg-icon" data-svg-icon="alert"></span>
        <span>${t("chatNotificationSettingsTitle")}</span>
      </span>
      <input id="settings-chat-notification-enabled" class="settings-switch-input" type="checkbox" ${
        config.enabled ? "checked" : ""
      } />
    </label>
    ${createSettingsSelectRow({
      id: "settings-chat-notification-sound",
      icon: "volume",
      label: t("chatNotificationSound"),
      value: config.sound,
      options: getNotificationSoundOptions({ includeDefault: true, kind: "message" }),
    }).outerHTML}
    <label class="settings-switch-row">
      <span class="settings-switch-main">
        <span class="svg-icon" data-svg-icon="alert"></span>
        <span>${t("chatNotificationShowPreviews")}</span>
      </span>
      <input id="settings-chat-notification-previews" class="settings-switch-input" type="checkbox" ${
        config.showPreviews ? "checked" : ""
      } />
    </label>
    ${createSettingsSelectRow({
      id: "settings-chat-notification-mute",
      icon: "volume-off",
      label: t("chatNotificationMuteTimer"),
      value: config.enabled ? "off" : config.muteUntil === "forever" ? "forever" : "1h",
      options: [
        { value: "off", label: t("settingsEnabledShort") },
        { value: "1h", label: t("chatNotificationMuteHour") },
        { value: "1d", label: t("chatNotificationMuteDay") },
        { value: "1w", label: t("chatNotificationMuteWeek") },
        { value: "forever", label: t("chatNotificationMuteForever") },
      ],
    }).outerHTML}
    <div class="settings-section-actions">
      <button type="button" id="settings-chat-notification-reset-btn" class="small ghost danger">${escapeHtml(
        t("settingsNotificationResetChat"),
      )}</button>
    </div>
  `;

  elements.settingsDetailContent.innerHTML = "";
  elements.settingsDetailContent.appendChild(wrap);
  renderSvgIcons(elements.settingsDetailContent);
  const soundSelect = elements.settingsDetailContent.querySelector("#settings-chat-notification-sound");
  if (soundSelect) {
    soundSelect.value = config.sound;
  }
  const muteSelect = elements.settingsDetailContent.querySelector("#settings-chat-notification-mute");
  if (muteSelect) {
    muteSelect.value = config.enabled ? "off" : config.muteUntil === "forever" ? "forever" : "1h";
  }

  const saveNotificationSettings = async () => {
    renderChats();
    try {
      await saveSettingsPayloadSilently();
    } catch (error) {
      alert(error.message);
    }
  };

  elements.settingsDetailContent.querySelector("#settings-chat-notification-enabled")?.addEventListener("change", async (event) => {
    setChatNotificationsEnabled(chat.id, event.target.checked, { custom: true });
    await saveNotificationSettings();
  });
  soundSelect?.addEventListener("change", async (event) => {
    setChatNotificationConfig(chat.id, {
      sound: String(event.target.value ?? "default"),
      custom: true,
    });
    await saveNotificationSettings();
  });
  elements.settingsDetailContent.querySelector("#settings-chat-notification-previews")?.addEventListener("change", async (event) => {
    setChatNotificationConfig(chat.id, {
      showPreviews: Boolean(event.target.checked),
      custom: true,
    });
    await saveNotificationSettings();
  });
  muteSelect?.addEventListener("change", async (event) => {
    const value = String(event.target.value ?? "off");
    if (value === "off") {
      setChatNotificationsEnabled(chat.id, true, { custom: true });
    } else {
      const durationMs =
        value === "1d"
          ? 24 * 60 * 60 * 1000
          : value === "1w"
            ? 7 * 24 * 60 * 60 * 1000
            : 60 * 60 * 1000;
      const muteUntil = value === "forever" ? "forever" : new Date(Date.now() + durationMs).toISOString();
      setChatNotificationsEnabled(chat.id, false, { muteUntil, custom: true });
    }
    await saveNotificationSettings();
  });
  elements.settingsDetailContent.querySelector("#settings-chat-notification-reset-btn")?.addEventListener("click", async () => {
    clearChatNotificationConfig(chat.id);
    await saveNotificationSettings();
    goBackSettingsSection();
  });
}

function getAudienceLabel(value) {
  const safeValue = String(value ?? "").trim();
  if (safeValue === "everyone") {
    return t("everybody");
  }
  if (safeValue === "contacts") {
    return t("myContacts");
  }
  if (safeValue === "nobody") {
    return t("nobody");
  }
  if (safeValue === "contacts-plus" || safeValue === "contacts-premium") {
    return t("settingsContactsPlusPremium");
  }
  if (safeValue === "miniapps") {
    return t("settingsMiniApps");
  }
  return t("everybody");
}

function formatAudienceWithCount(value, count) {
  const label = getAudienceLabel(value);
  const safeCount = Number.isFinite(Number(count)) ? Number(count) : 0;
  if (safeCount > 0) {
    return `${label} (+${safeCount})`;
  }
  return label;
}

function collectKnownUsersForPrivacy() {
  const map = new Map();
  const addCandidate = (candidate = {}) => {
    const id = String(candidate.id ?? candidate.userId ?? "").trim();
    if (!id || id === String(state.user?.id ?? "")) {
      return;
    }
    if (map.has(id)) {
      return;
    }
    map.set(id, {
      id,
      chatId: String(candidate.chatId ?? "").trim(),
      username: String(candidate.username ?? "").trim(),
      displayName: getUserDisplayName({
        id,
        displayName: String(candidate.displayName ?? "").trim(),
      }),
      avatar: String(candidate.avatar ?? "").trim(),
    });
  };

  for (const chat of state.chats) {
    if (chat.type === "direct") {
      addCandidate(getDirectPeer(chat));
    }
    for (const member of chat.members ?? []) {
      addCandidate(member);
    }
  }

  for (const message of state.currentMessages) {
    addCandidate(message.sender);
  }

  return [...map.values()].sort((a, b) => a.displayName.localeCompare(b.displayName, state.lang === "ru" ? "ru" : "en"));
}

function normalizePrivacyIdList(value) {
  if (!Array.isArray(value)) {
    return [];
  }
  return [...new Set(value.map((entry) => String(entry ?? "").trim()).filter(Boolean))];
}

function getPrivacyExceptionCount(target, idsKey, _countKey) {
  const ids = normalizePrivacyIdList(target?.[idsKey]);
  if (ids.length > 0) {
    return ids.length;
  }
  return 0;
}

function setPrivacyExceptionIds(target, idsKey, countKey, ids) {
  const safeIds = normalizePrivacyIdList(ids);
  target[idsKey] = safeIds;
  target[countKey] = safeIds.length;
}

async function promptPrivacyExceptionContact(title, excludeIds = []) {
  const excluded = new Set(normalizePrivacyIdList(excludeIds));
  const candidates = collectKnownUsersForPrivacy().filter((entry) => !excluded.has(String(entry.id ?? "").trim()));
  if (!candidates.length) {
    alert(t("noContacts"));
    return null;
  }
  const selectedId = await selectDialog({
    title,
    options: candidates.map((entry) => ({
      value: entry.id,
      label: `${entry.displayName}${entry.username ? ` (@${entry.username})` : ""}`,
    })),
    submitText: t("settingsAdd"),
  });
  return selectedId ? String(selectedId) : null;
}

function getBlockedUsers() {
  return Array.isArray(state.privacyPreferences?.security?.blockedUsers) ? state.privacyPreferences.security.blockedUsers : [];
}

function getAuthorizedSites() {
  return Array.isArray(state.privacyPreferences?.security?.authorizedSites)
    ? state.privacyPreferences.security.authorizedSites
    : [];
}

function getPrivacyPasskeys() {
  return Array.isArray(state.privacyPreferences?.security?.passkeys) ? state.privacyPreferences.security.passkeys : [];
}

function getAutoLockLabel(minutes) {
  const safeMinutes = Number(minutes);
  if (safeMinutes <= 0) {
    return state.lang === "ru" ? "Сразу" : "Immediately";
  }
  if (safeMinutes === 1) {
    return state.lang === "ru" ? "Через 1 минуту" : "After 1 minute";
  }
  if (safeMinutes === 5) {
    return state.lang === "ru" ? "Через 5 минут" : "After 5 minutes";
  }
  return state.lang === "ru" ? `${safeMinutes} мин.` : `${safeMinutes} min`;
}

async function resolveUserForPrivacyBlock(query) {
  const raw = String(query ?? "").trim();
  if (!raw) {
    return null;
  }
  const normalized = normalizeUsernameInput(raw).toLowerCase();
  const known = collectKnownUsersForPrivacy().find((entry) => {
    if (!entry) {
      return false;
    }
    return (
      String(entry.id ?? "").toLowerCase() === raw.toLowerCase() ||
      String(entry.chatId ?? "").toLowerCase() === raw.toLowerCase() ||
      String(entry.username ?? "").toLowerCase() === normalized
    );
  });
  if (known) {
    return known;
  }

  const payload = await api(`/api/users/search?q=${encodeURIComponent(normalized || raw)}`);
  const users = Array.isArray(payload.users) ? payload.users : [];
  const entry = users.find((item) => String(item.id ?? "").trim() !== String(state.user?.id ?? "").trim());
  if (!entry) {
    return null;
  }
  return {
    id: String(entry.id),
    chatId: String(entry.chatId ?? ""),
    username: String(entry.username ?? ""),
    displayName: getUserDisplayName(entry),
    avatar: String(entry.avatar ?? ""),
  };
}

function getPrivacySessionsCount() {
  const serverCurrent = state.authSessions?.current ? 1 : 0;
  const serverOthers = Array.isArray(state.authSessions?.others) ? state.authSessions.others.length : 0;
  if (serverCurrent || serverOthers) {
    return serverCurrent + serverOthers;
  }
  return 1 + (state.privacyPreferences?.sessions?.others?.length ?? 0);
}

function savePrivacyAndRefresh() {
  savePrivacyPreferences();
  saveSettingsPayloadSilently().catch(() => {
    // Ignore privacy sync failures and keep local state.
  });
  renderSettingsSection();
}

function getAutoDeleteLabel(enabled, days) {
  if (!enabled) {
    return t("settingsDisabledShort");
  }
  const safeDays = Number.isFinite(Number(days)) ? Number(days) : 0;
  if (safeDays > 0) {
    return state.lang === "ru" ? `${safeDays} дн.` : `${safeDays} d`;
  }
  return t("settingsEnabledShort");
}

