function renderSettingsStoriesSection() {
  if (!elements.settingsDetailContent) {
    return;
  }

  const { all, active, archived, saved } = getOwnStoryCollections();
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body";

  const actions = document.createElement("div");
  actions.className = "settings-section-actions settings-story-top-actions";
  actions.innerHTML = `
    <button type="button" id="settings-story-create-btn" class="small">${t("storyCreate")}</button>
    <button type="button" id="settings-story-hidden-btn" class="small ghost">${t("storyManageHidden")}</button>
  `;
  wrap.appendChild(actions);

  const stealthRow = createSettingsSwitchRow({
    id: "settings-story-stealth-toggle",
    icon: "eye-off",
    label: t("storyStealthMode"),
    checked: isStoryStealthModeEnabled(),
  });
  wrap.appendChild(stealthRow);
  const stealthHint = document.createElement("div");
  stealthHint.className = "hint";
  stealthHint.textContent = t("storyStealthModeHint");
  wrap.appendChild(stealthHint);

  const createStorySection = (title, stories, emptyLabel) => {
    const titleNode = document.createElement("div");
    titleNode.className = "section-title";
    titleNode.textContent = title;
    wrap.appendChild(titleNode);

    const list = document.createElement("div");
    list.className = "settings-sessions-list settings-story-list";
    if (!stories.length) {
      const empty = document.createElement("div");
      empty.className = "hint settings-story-empty";
      empty.textContent = emptyLabel;
      list.appendChild(empty);
    }

    stories.forEach((story) => {
      const row = document.createElement("div");
      row.className = "settings-story-row";
      row.dataset.storyId = story.id;
      row.innerHTML = `
        <div class="settings-story-thumb"></div>
        <div class="settings-story-main">
          <strong>${escapeHtml(story.caption || story.title)}</strong>
          <span>${escapeHtml(formatDateTime(story.createdAt) || t("storyJustNow"))}</span>
          <span>${escapeHtml(`${getStoryPrivacyValueLabel(story.privacy)} • ${getStoryExpirationValueLabel(story.expiresHours)}`)}</span>
        </div>
        <div class="settings-story-actions">
          <button type="button" class="small ghost settings-story-open-btn">${t("storyOpen")}</button>
          <button type="button" class="small ghost settings-story-views-btn">${t("storyViews")}</button>
          <button type="button" class="small ghost settings-story-edit-btn">${t("storyEdit")}</button>
          <button type="button" class="small ghost settings-story-save-btn">${t("storySaveToProfile")}</button>
          <button type="button" class="small ghost danger settings-story-delete-btn">${t("storyDelete")}</button>
        </div>
      `;
      const thumb = row.querySelector(".settings-story-thumb");
      if (thumb) {
        thumb.style.background = story.image ? "#10131a" : getStoryBackgroundStyle(story.background);
        if (story.image) {
          thumb.style.backgroundImage = `url("${story.image}")`;
          thumb.style.backgroundSize = "cover";
          thumb.style.backgroundPosition = "center";
        } else {
          thumb.textContent = getInitialSymbol(story.title || story.caption, "Y");
        }
      }
      if (story.saveToProfile) {
        const chip = document.createElement("span");
        chip.className = "settings-story-chip";
        chip.textContent = t("storySaveToProfile");
        row.querySelector(".settings-story-main")?.appendChild(chip);
      }
      row.querySelector(".settings-story-open-btn")?.addEventListener("click", () => {
        closeDrawer();
        const storySet = all.length ? all : [story];
        const storyIndex = Math.max(0, storySet.findIndex((entry) => entry.id === story.id));
        openStoryViewer(storyIndex, storySet);
      });
      row.querySelector(".settings-story-views-btn")?.addEventListener("click", () => {
        openStoryViewsSection(story);
      });
      row.querySelector(".settings-story-edit-btn")?.addEventListener("click", () => {
        closeDrawer();
        openStoryEditor(story);
      });
      row.querySelector(".settings-story-save-btn")?.addEventListener("click", async () => {
        try {
          await api(`/api/stories/${encodeURIComponent(story.id)}`, {
            method: "PATCH",
            body: {
              saveToProfile: !story.saveToProfile,
            },
          });
          await loadStories();
        } catch (error) {
          alert(error.message);
        }
      });
      row.querySelector(".settings-story-delete-btn")?.addEventListener("click", async () => {
        try {
          await api(`/api/stories/${encodeURIComponent(story.id)}`, {
            method: "DELETE",
          });
          if (state.storySettingsStoryId === story.id) {
            state.storySettingsStoryId = "";
          }
          await loadStories();
        } catch (error) {
          alert(error.message);
        }
      });
      list.appendChild(row);
    });
    wrap.appendChild(list);
  };

  createStorySection(t("storyActiveTitle"), active, t("storyNoActive"));
  createStorySection(t("storyArchiveTitle"), archived, t("storyNoArchive"));
  createStorySection(t("storySavedTitle"), saved, t("storyNoSaved"));

  elements.settingsDetailContent.innerHTML = "";
  elements.settingsDetailContent.appendChild(wrap);
  renderSvgIcons(elements.settingsDetailContent);

  elements.settingsDetailContent.querySelector("#settings-story-stealth-toggle")?.addEventListener("change", async (event) => {
    updateStoryFeatureSettings({ stealthMode: event.target.checked });
    try {
      await saveSettingsPayloadSilently();
    } catch (error) {
      alert(error.message);
    }
  });

  elements.settingsDetailContent.querySelector("#settings-story-create-btn")?.addEventListener("click", () => {
    closeDrawer();
    openStoryEditor();
  });
  elements.settingsDetailContent.querySelector("#settings-story-hidden-btn")?.addEventListener("click", () => {
    openSettingsSection("stories-hidden");
  });
}

