function openStoryViewsSection(storyLike = null) {
  const safeStory = storyLike && typeof storyLike === "object"
    ? normalizeStoryEntry(storyLike) ?? storyLike
    : getOwnStoryById(storyLike) ?? getActiveStory();
  if (!safeStory?.id) {
    return;
  }
  state.storySettingsStoryId = safeStory.id;
  state.storyViewsFilter = "all";
  state.storyViewsQuery = "";
  closeStoryViewer();
  const openViewsScreen = () => {
    setDrawerTab("settings", {
      presentation: state.platform === "iphone" ? "push" : "modal",
    });
    openSettingsSection("stories-views");
  };
  const scheduleOpen = globalThis.requestAnimationFrame ?? ((callback) => setTimeout(callback, 0));
  scheduleOpen(() => {
    openViewsScreen();
  });
}

function renderSettingsStoryViewsSection() {
  if (!elements.settingsDetailContent) {
    return;
  }

  const story = getOwnStoryById(state.storySettingsStoryId);
  if (!story) {
    openSettingsSection("stories", { replaceHistory: true });
    return;
  }

  const allViewers = (Array.isArray(story.viewers) ? story.viewers : []).map((entry, index) => normalizeStoryViewerEntry(entry, index));
  const query = String(state.storyViewsQuery ?? "").trim().toLowerCase();
  const filter = String(state.storyViewsFilter ?? "all").trim() || "all";
  const filteredViewers = allViewers.filter((entry) => {
    if (filter === "contacts" && !entry.isContact) {
      return false;
    }
    if (filter === "reactions" && !entry.reaction) {
      return false;
    }
    if (!query) {
      return true;
    }
    return `${entry.name} ${entry.username}`.toLowerCase().includes(query);
  });
  if (filter === "date") {
    filteredViewers.sort((a, b) => new Date(b.viewedAt || 0).getTime() - new Date(a.viewedAt || 0).getTime());
  }

  const wrap = document.createElement("div");
  wrap.className = "settings-section-body";
  wrap.innerHTML = `
    <div class="settings-story-stats-toolbar">
      <div class="settings-story-stats-summary">
        <strong>${escapeHtml(story.caption || story.title)}</strong>
        <span>${allViewers.length} ${t("storyViewsSummary")}</span>
      </div>
      <button type="button" id="settings-story-stats-open-btn" class="small ghost">${t("storyOpen")}</button>
    </div>
    <div class="settings-story-viewers-controls">
      <input id="settings-story-viewers-search" placeholder="${escapeHtml(t("storyViewsSearchPlaceholder"))}" value="${escapeHtml(state.storyViewsQuery)}" />
      <select id="settings-story-viewers-filter">
        <option value="all">${t("storyViewsFilterAll")}</option>
        <option value="contacts">${t("storyViewsFilterContacts")}</option>
        <option value="reactions">${t("storyViewsFilterReactions")}</option>
        <option value="date">${t("storyViewsFilterDate")}</option>
      </select>
    </div>
  `;

  const list = document.createElement("div");
  list.className = "settings-sessions-list settings-story-list";
  if (!filteredViewers.length) {
    const empty = document.createElement("div");
    empty.className = "hint settings-story-empty";
    empty.textContent = t("storyStatsEmpty");
    list.appendChild(empty);
  }

  filteredViewers.forEach((entry) => {
    const row = document.createElement("div");
    row.className = "settings-story-row";
    row.innerHTML = `
      <span class="avatar settings-story-avatar"></span>
      <div class="settings-story-main">
        <strong>${escapeHtml(entry.name)}</strong>
        <span>${escapeHtml(entry.username ? `@${entry.username}` : formatDateTime(entry.viewedAt) || t("storyJustNow"))}</span>
      </div>
      <div class="settings-story-actions">
        ${entry.reaction ? `<span class="settings-story-chip">${escapeHtml(entry.reaction)}</span>` : ""}
      </div>
    `;
    applyAvatarNode(row.querySelector(".settings-story-avatar"), entry.name, entry.avatar, "Y");
    list.appendChild(row);
  });

  wrap.appendChild(list);
  elements.settingsDetailContent.innerHTML = "";
  elements.settingsDetailContent.appendChild(wrap);

  const searchInput = elements.settingsDetailContent.querySelector("#settings-story-viewers-search");
  const filterSelect = elements.settingsDetailContent.querySelector("#settings-story-viewers-filter");
  if (filterSelect) {
    filterSelect.value = filter;
  }
  searchInput?.addEventListener("input", () => {
    state.storyViewsQuery = String(searchInput.value ?? "");
    renderSettingsStoryViewsSection();
  });
  filterSelect?.addEventListener("change", () => {
    state.storyViewsFilter = String(filterSelect.value ?? "all");
    renderSettingsStoryViewsSection();
  });
  elements.settingsDetailContent.querySelector("#settings-story-stats-open-btn")?.addEventListener("click", () => {
    closeDrawer();
    openStoryViewer(0, [story]);
  });
}

