function updateCreateFlowTypeUi() {
  const isChannel = state.createFlow.type === "channel";
  if (elements.createFlowTitleLabel) {
    elements.createFlowTitleLabel.textContent = isChannel ? t("createFlowChannelName") : t("createFlowGroupName");
  }
  if (elements.createFlowTitleInput) {
    elements.createFlowTitleInput.placeholder = isChannel ? t("createFlowChannelName") : t("createFlowGroupName");
  }
  if (elements.createFlowDescriptionInput) {
    elements.createFlowDescriptionInput.classList.remove("hidden");
  }
  const visibilityValue = getCreateFlowVisibilityValue();
  if (elements.createFlowHandleInput) {
    elements.createFlowHandleInput.classList.toggle("hidden", visibilityValue !== "public");
  }
}

function getCreateFlowVisibilityValue() {
  const radio = document.querySelector('input[name="create-flow-visibility"]:checked');
  return radio ? String(radio.value ?? "private") : "private";
}

let createFlowSearchDebounceTimer = null;

async function updateCreateFlowRemoteCandidates() {
  const mode = String(state.createFlow.mode ?? "");
  if (!state.createFlow.open || (mode !== "add-members" && mode !== "add-bots")) {
    return;
  }
  renderCreateFlowMembers();
}

function getCreateFlowContactPool({ botsOnly = false } = {}) {
  const users = new Map();
  const selfId = String(state.user?.id ?? "").trim();
  for (const chat of state.chats) {
    if (chat.type !== "direct") {
      continue;
    }
    const peer = getDirectPeer(chat);
    const userId = String(peer?.userId ?? "").trim();
    if (!userId || userId === selfId || isContactHidden(userId)) {
      continue;
    }
    const bot = isBotUser(peer);
    if (botsOnly ? !bot : bot) {
      continue;
    }
    if (users.has(userId)) {
      continue;
    }
    const online = isMemberOnline(chat.id, userId);
    const lastSeen = getMemberLastActivityAt(chat.id, userId);
    users.set(userId, {
      userId,
      displayName: getUserDisplayName({ id: userId, displayName: peer.displayName }),
      username: String(peer.username ?? "").trim(),
      avatar: String(peer.avatar ?? "").trim(),
      isBot: bot,
      online,
      status: bot ? t("botStatus") : online ? t("onlineNow") : formatRelativeTime(lastSeen),
      sortSeenAt: lastSeen ? lastSeen.getTime() : 0,
    });
  }
  return [...users.values()];
}

function getCreateFlowCandidates() {
  const mode = String(state.createFlow.mode ?? "create");
  const targetChat = state.createFlow.targetChatId
    ? state.chats.find((entry) => entry.id === state.createFlow.targetChatId) ?? null
    : null;
  const existingMembers = new Set((targetChat?.members ?? []).map((entry) => String(entry.userId ?? "").trim()).filter(Boolean));

  if (mode === "add-bots") {
    return (Array.isArray(state.createFlow.botCandidates) ? state.createFlow.botCandidates : getCreateFlowContactPool({ botsOnly: true }))
      .filter((entry) => String(entry?.userId ?? "").trim())
      .filter((entry) => !existingMembers.has(String(entry.userId ?? "").trim()))
      .sort((a, b) => a.displayName.localeCompare(b.displayName, state.lang === "ru" ? "ru" : "en"));
  }

  const candidates = (Array.isArray(state.createFlow.memberCandidates) ? state.createFlow.memberCandidates : getCreateFlowContactPool({ botsOnly: false }))
    .filter((entry) => String(entry?.userId ?? "").trim())
    .filter((entry) => !existingMembers.has(String(entry.userId ?? "").trim()));
  return candidates.sort((a, b) => {
    if (a.online !== b.online) {
      return Number(b.online) - Number(a.online);
    }
    if (a.sortSeenAt !== b.sortSeenAt) {
      return b.sortSeenAt - a.sortSeenAt;
    }
    return a.displayName.localeCompare(b.displayName, state.lang === "ru" ? "ru" : "en");
  });
}

function updateCreateFlowSelectedCount() {
  if (!elements.createFlowSelectedCount) {
    return;
  }
  const selectedCount = state.createFlow.selectedMemberIds.length;
  elements.createFlowSelectedCount.textContent = `${selectedCount} / 200000`;
}

function renderCreateFlowMembers() {
  if (!elements.createFlowMembersList) {
    return;
  }

  const selected = new Set(state.createFlow.selectedMemberIds);
  const query = String(elements.createFlowMemberSearch?.value ?? "")
    .trim()
    .toLowerCase();
  const candidates = getCreateFlowCandidates().filter((entry) => {
    if (!query) {
      return true;
    }
    return `${entry.displayName} ${entry.username} ${entry.status}`.toLowerCase().includes(query);
  });

  elements.createFlowMembersList.innerHTML = "";
  if (!candidates.length) {
    const hint = document.createElement("div");
    hint.className = "hint";
    hint.textContent = state.createFlow.mode === "add-bots" ? t("addBotsEmpty") : t("noContacts");
    elements.createFlowMembersList.appendChild(hint);
    updateCreateFlowSelectedCount();
    return;
  }

  for (const entry of candidates) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "create-flow-member-item";
    button.classList.toggle("selected", selected.has(entry.userId));
    button.dataset.userId = entry.userId;
    button.innerHTML = `
      <span class="avatar create-flow-member-avatar"></span>
      <span class="create-flow-member-meta">
        <strong>${entry.displayName}</strong>
        <span class="hint">${entry.status}</span>
      </span>
    `;
    const avatar = button.querySelector(".create-flow-member-avatar");
    applyAvatarNode(avatar, entry.displayName, entry.avatar, "Y");
    button.addEventListener("click", () => {
      const next = new Set(state.createFlow.selectedMemberIds);
      if (next.has(entry.userId)) {
        next.delete(entry.userId);
      } else {
        next.add(entry.userId);
      }
      state.createFlow.selectedMemberIds = [...next];
      renderCreateFlowMembers();
    });
    elements.createFlowMembersList.appendChild(button);
  }

  updateCreateFlowSelectedCount();
}

function openCreateFlow(type) {
  const safeType = String(type) === "channel" ? "channel" : "group";
  state.createFlow = {
    open: true,
    mode: "create",
    targetChatId: null,
    type: safeType,
    title: "",
    description: "",
    avatar: "",
    visibility: "private",
    handle: "",
    autoDelete: "off",
    search: "",
    botCandidates: [],
    memberCandidates: [],
    selectedMemberIds: [],
  };

  updateCreateFlowTypeUi();
  document.querySelectorAll('input[name="create-flow-visibility"]').forEach((input) => {
    input.checked = input.value === "private";
  });
  state.createFlow.visibility = getCreateFlowVisibilityValue();
  if (elements.createFlowTitleInput) {
    elements.createFlowTitleInput.value = "";
  }
  if (elements.createFlowDescriptionInput) {
    elements.createFlowDescriptionInput.value = "";
  }
  if (elements.createFlowHandleInput) {
    elements.createFlowHandleInput.value = "";
    elements.createFlowHandleInput.classList.add("hidden");
  }
  if (elements.createFlowAutoDelete) {
    elements.createFlowAutoDelete.value = "off";
  }
  if (elements.createFlowMemberSearch) {
    elements.createFlowMemberSearch.value = "";
    elements.createFlowMemberSearch.placeholder = t("createFlowMembersSearch");
  }
  const createFlowHeadTitle = elements.createFlowPanel?.querySelector(".create-flow-members-head strong");
  if (createFlowHeadTitle) {
    createFlowHeadTitle.textContent = t("createFlowAddMembers");
  }
  if (elements.createFlowCreateBtn) {
    elements.createFlowCreateBtn.textContent = t("create");
  }
  if (elements.createFlowBackBtn) {
    elements.createFlowBackBtn.textContent = t("cancel");
  }
  updateCreateFlowSelectedCount();
  if (elements.createFlowAvatarBtn) {
    elements.createFlowAvatarBtn.style.backgroundImage = "";
    elements.createFlowAvatarBtn.dataset.svgIcon = "camera";
    renderSvgIcons(elements.createFlowAvatarBtn);
  }
  elements.createFlowStepOne?.classList.remove("hidden");
  elements.createFlowStepTwo?.classList.add("hidden");
  elements.createFlowPanel?.classList.remove("hidden");
  syncSidebarResizerInteractivity();
}

async function openChatAddFlow(chat, mode = "members") {
  if (!chat || chat.type === "direct") {
    return;
  }

  const addBots = mode === "bots";
  if ((addBots && !canManageChat(chat)) || (!addBots && !canInviteMembers(chat))) {
    return;
  }
  state.createFlow = {
    open: true,
    mode: addBots ? "add-bots" : "add-members",
    targetChatId: chat.id,
    type: chat.type === "channel" ? "channel" : "group",
    title: chat.title || "",
    description: "",
    avatar: "",
    visibility: "private",
    handle: "",
    autoDelete: "off",
    search: "",
    botCandidates: [],
    memberCandidates: [],
    selectedMemberIds: [],
  };

  if (elements.createFlowMemberSearch) {
    elements.createFlowMemberSearch.value = "";
    elements.createFlowMemberSearch.placeholder = addBots ? t("createFlowSearchBots") : t("createFlowMembersSearch");
  }

  const createFlowHeadTitle = elements.createFlowPanel?.querySelector(".create-flow-members-head strong");
  if (createFlowHeadTitle) {
    createFlowHeadTitle.textContent = addBots ? t("createFlowAddBots") : t("createFlowAddMembers");
  }
  if (elements.createFlowCreateBtn) {
    elements.createFlowCreateBtn.textContent = addBots ? t("addBots") : t("createFlowAddToChat");
  }
  if (elements.createFlowBackBtn) {
    elements.createFlowBackBtn.textContent = t("cancel");
  }

  if (addBots) {
    state.createFlow.botCandidates = getCreateFlowContactPool({ botsOnly: true });
  } else {
    state.createFlow.memberCandidates = getCreateFlowContactPool({ botsOnly: false });
  }

  elements.createFlowStepOne?.classList.add("hidden");
  elements.createFlowStepTwo?.classList.remove("hidden");
  elements.createFlowPanel?.classList.remove("hidden");
  updateCreateFlowSelectedCount();
  renderCreateFlowMembers();
  syncSidebarResizerInteractivity();
}
function closeCreateFlow() {
  state.createFlow.open = false;
  elements.createFlowPanel?.classList.add("hidden");
  syncSidebarResizerInteractivity();
}

function goToCreateFlowStepTwo() {
  const title = String(elements.createFlowTitleInput?.value ?? "").trim();
  if (!title) {
    return;
  }
  if (state.createFlow.type === "group" && !isValidGroupTitleInput(title)) {
    alert(t("invalidGroupTitle"));
    return;
  }
  state.createFlow.visibility = getCreateFlowVisibilityValue();
  state.createFlow.handle = normalizeHandleInput(elements.createFlowHandleInput?.value ?? "");
  state.createFlow.autoDelete = String(elements.createFlowAutoDelete?.value ?? "off");
  if (state.createFlow.visibility === "public" && !state.createFlow.handle) {
    alert(t("handleRequired"));
    return;
  }
  state.createFlow.title = title;
  state.createFlow.description = String(elements.createFlowDescriptionInput?.value ?? "").trim();
  elements.createFlowStepOne?.classList.add("hidden");
  elements.createFlowStepTwo?.classList.remove("hidden");
  renderCreateFlowMembers();
}

async function submitCreateFlow() {
  const mode = String(state.createFlow.mode ?? "create");
  const selectedMemberIds = [...new Set(state.createFlow.selectedMemberIds.map((value) => String(value ?? "").trim()).filter(Boolean))];

  if (mode === "add-members" || mode === "add-bots") {
    const targetChatId = String(state.createFlow.targetChatId ?? "").trim();
    if (!targetChatId || !selectedMemberIds.length) {
      return;
    }

    const asBot = mode === "add-bots";
    const failedMemberIds = [];
    for (const memberId of selectedMemberIds) {
      try {
        if (asBot) {
          await addChatMemberByPayload(targetChatId, { memberId }, { asBot: true });
        } else {
          await addChatMemberWithBotFallback(targetChatId, { memberId }, { forceBots: false });
        }
      } catch {
        failedMemberIds.push(memberId);
      }
    }

    closeCreateFlow();
    closeDrawer();
    await loadChats(targetChatId, true);
    if (state.activeChatId === targetChatId) {
      await loadMessages();
    }
    if (failedMemberIds.length) {
      alert(t("someMembersNotAdded"));
    }
    return;
  }

  const title = String(state.createFlow.title ?? "").trim();
  if (!title) {
    return;
  }
  const isPublic = state.createFlow.visibility === "public";
  const handle = isPublic ? normalizeHandleInput(state.createFlow.handle ?? "") : "";
  const autoDeleteDays = state.createFlow.autoDelete === "off" ? 0 : Number.parseInt(state.createFlow.autoDelete, 10) || 0;

  const payload = await api("/api/chats", {
    method: "POST",
    body: {
      type: state.createFlow.type,
      title,
      description: state.createFlow.description || undefined,
      isPublic,
      handle: handle || undefined,
      interfaceMode: isGameMode() ? "game" : "chat",
      settings: {
        allowMemberInvites: true,
        commentsEnabled: state.createFlow.type === "channel",
        autoDeleteDays,
      },
    },
  });

  for (const memberId of selectedMemberIds) {
    try {
      await addChatMemberByPayload(payload.chat.id, { memberId }, { asBot: false });
    } catch {
      // Skip users that could not be added (duplicates or permission race).
    }
  }

  closeCreateFlow();
  closeDrawer();
  await loadChats(payload.chat.id, false);
}

function getDrawerTabTitle(tab) {
  const titles = {
    menu: t("menu"),
    settings: t("settings"),
    create: t("createChat"),
    contacts: t("contactsTab"),
    calls: t("callsTab"),
    profile: t("profileMyTitle"),
  };
  return titles[tab] ?? t("menu");
}

function getDrawerHeaderTitle() {
  const override = String(state.drawerTitleOverride ?? "").trim();
  if (override) {
    return override;
  }
  if (state.drawerTab === "settings" && state.settingsSection) {
    return getSettingsSectionTitle(state.settingsSection);
  }
  return getDrawerTabTitle(state.drawerTab);
}

function syncDrawerHeader() {
  if (!elements.drawerPanel || !elements.drawerCloseBtn || !elements.drawerHeadTitle || !elements.drawerBackBtn) {
    return;
  }
  const onIphone = isIphonePlatform();
  const drawerOpen = Boolean(state.drawerOpen);
  if (!onIphone) {
    elements.drawerPanel.classList.remove("drawer-fullscreen-mode", "drawer-push-mode", "drawer-sheet-mode");
    elements.drawerHeadTitle.textContent = "";
    elements.drawerHeadTitle.classList.add("hidden");
    elements.drawerBackBtn.classList.add("hidden");
    elements.drawerBackBtn.disabled = true;
    elements.drawerCloseBtn.classList.remove("hidden");
    elements.drawerCloseBtn.disabled = !drawerOpen;
    delete elements.drawerPanel.dataset.drawerPresentation;
    delete elements.drawerPanel.dataset.drawerTitle;
    renderSvgIcons(elements.drawerPanel);
    return;
  }
  const menuMode = state.drawerPresentation === "menu";
  const fullscreenMode = drawerOpen && onIphone && !menuMode;
  const pushMode = fullscreenMode && state.drawerPresentation === "push";
  const modalMode = fullscreenMode && state.drawerPresentation === "modal";
  const showTitle = onIphone && drawerOpen;
  elements.drawerPanel.classList.toggle("drawer-fullscreen-mode", fullscreenMode);
  elements.drawerPanel.classList.toggle("drawer-push-mode", pushMode);
  elements.drawerPanel.classList.toggle("drawer-sheet-mode", modalMode);
  elements.drawerHeadTitle.textContent = getDrawerHeaderTitle();
  elements.drawerHeadTitle.classList.toggle("hidden", !showTitle);
  elements.drawerBackBtn.classList.toggle("hidden", !onIphone || !pushMode);
  elements.drawerCloseBtn.classList.toggle("hidden", onIphone && pushMode);
  elements.drawerBackBtn.disabled = !pushMode;
  elements.drawerCloseBtn.disabled = !drawerOpen;
  elements.drawerPanel.dataset.drawerPresentation = state.drawerPresentation;
  elements.drawerPanel.dataset.drawerTitle = getDrawerHeaderTitle();
  if (pushMode) {
    elements.drawerBackBtn.dataset.i18nTitle = state.drawerTab === "settings" && state.settingsSection ? "backToSettings" : "backToChats";
    elements.drawerBackBtn.title = state.drawerTab === "settings" && state.settingsSection ? t("backToSettings") : t("backToChats");
  }
  if (menuMode) {
    elements.drawerCloseBtn.dataset.i18nTitle = "close";
    elements.drawerCloseBtn.title = t("close");
  }
  if (modalMode) {
    elements.drawerCloseBtn.dataset.i18nTitle = "close";
    elements.drawerCloseBtn.title = t("close");
  }
  renderSvgIcons(elements.drawerPanel);
}

function setDrawerTab(tab, options = {}) {
  const allowed = isGameMode()
    ? new Set(["menu", "settings", "create", "profile"])
    : new Set(["menu", "settings", "create", "contacts", "calls", "profile"]);
  state.drawerTab = allowed.has(tab) ? tab : "menu";
  if (isIphonePlatform()) {
    const requestedPresentation = String(options.presentation ?? "").trim();
    state.drawerPresentation = state.drawerTab === "menu" ? "menu" : requestedPresentation || "push";
    state.drawerTitleOverride = String(options.title ?? "").trim();
  } else {
    state.drawerPresentation = state.drawerTab === "menu" ? "menu" : "modal";
    state.drawerTitleOverride = "";
  }
  if (state.drawerTab !== "create") {
    state.createPresetType = "";
  }
  state.drawerOpen = true;

  elements.drawerPanel.classList.remove("hidden");
  elements.drawerPanel.classList.toggle("drawer-menu-mode", state.drawerTab === "menu");
  const modalTab = state.drawerTab !== "menu";
  elements.drawerPanel.classList.toggle("drawer-modal-mode", modalTab);
  elements.drawerPanel.dataset.drawerTab = state.drawerTab;
  document.body.classList.toggle("drawer-open", isIphonePlatform());
  document.body.classList.toggle("drawer-modal-open", modalTab);
  drawerNavButtons.forEach((button) => {
    button.classList.toggle("active", button.dataset.drawerTab === state.drawerTab);
  });

  for (const pane of document.querySelectorAll(".drawer-tab")) {
    pane.classList.toggle("hidden", state.drawerTab === "menu" || pane.id !== `drawer-tab-${state.drawerTab}`);
  }

  closeCallsMoreMenu();
  closeSettingsHomeMoreMenu();

  if (state.drawerTab !== "settings") {
    closeSettingsSection();
  }
  if (state.drawerTab !== "profile") {
    state.profileEditorOpen = false;
    state.profilePremiumEditorOpen = false;
  }

  if (state.drawerTab === "contacts") {
    renderContacts();
  }
  if (state.drawerTab === "calls") {
    renderCalls();
  }
  if (state.drawerTab === "profile") {
    state.profileEditorOpen = true;
    bindProfileToForm();
    syncProfilePanelVisibility();
  } else {
    syncProfilePanelVisibility();
  }
  if (state.drawerTab === "settings") {
    bindSettingsHome();
    if (state.settingsSection) {
      renderSettingsSection();
    }
  }
  if (state.drawerTab === "calls") {
    loadCalls().catch(() => {
      // Ignore transient call tab sync errors.
    });
  }
  syncDrawerHeader();
  syncSidebarResizerInteractivity();
}

function closeDrawer() {
  state.drawerOpen = false;
  state.drawerPresentation = "menu";
  state.drawerTitleOverride = "";
  state.profilePremiumEditorOpen = false;
  closeSettingsHomeMoreMenu();
  closeSettingsSection();
  elements.drawerPanel.classList.remove("drawer-menu-mode");
  elements.drawerPanel.classList.remove("drawer-modal-mode");
  elements.drawerPanel.classList.remove("drawer-fullscreen-mode");
  elements.drawerPanel.classList.remove("drawer-push-mode");
  elements.drawerPanel.classList.remove("drawer-sheet-mode");
  delete elements.drawerPanel.dataset.drawerTab;
  delete elements.drawerPanel.dataset.drawerPresentation;
  delete elements.drawerPanel.dataset.drawerTitle;
  syncProfilePremiumEditorPanelVisibility();
  document.body.classList.remove("drawer-modal-open");
  document.body.classList.remove("drawer-open");
  elements.drawerPanel.classList.add("hidden");
  syncDrawerHeader();
  syncSidebarResizerInteractivity();
}

