function setMenuButtonLabel(button, label) {
  if (!button) {
    return;
  }
  const labelNode = button.querySelector(".menu-label");
  if (labelNode) {
    labelNode.textContent = label;
  } else {
    button.textContent = label;
  }
}

function positionFloatingMenu(menu, left, top, { fallbackWidth = 240, fallbackHeight = 180, padding = 8 } = {}) {
  if (!menu) {
    return;
  }
  const safePadding = Number.isFinite(Number(padding)) ? Math.max(0, Number(padding)) : 8;
  const wasHidden = menu.classList.contains("hidden");
  const previousVisibility = menu.style.visibility;
  if (wasHidden) {
    menu.style.visibility = "hidden";
    menu.classList.remove("hidden");
  }

  const rect = menu.getBoundingClientRect();
  const initialMenuWidth = rect.width || Number(fallbackWidth) || 240;
  const initialMenuHeight = rect.height || Number(fallbackHeight) || 180;
  const viewportWidth = Math.max(window.innerWidth || 0, document.documentElement?.clientWidth || 0, initialMenuWidth + safePadding * 2);
  const viewportHeight = Math.max(window.innerHeight || 0, document.documentElement?.clientHeight || 0, initialMenuHeight + safePadding * 2);
  let nextLeft = Number.isFinite(Number(left)) ? Number(left) : safePadding;
  let nextTop = Number.isFinite(Number(top)) ? Number(top) : safePadding;
  const maxHeight = Math.max(120, viewportHeight - safePadding * 2);
  menu.style.maxHeight = `${maxHeight}px`;
  menu.style.overflowY = "auto";
  menu.style.overflowX = "hidden";
  const measuredRect = menu.getBoundingClientRect();
  const menuWidth = measuredRect.width || initialMenuWidth;
  const menuHeight = Math.min(measuredRect.height || initialMenuHeight, maxHeight);

  const spaceRight = viewportWidth - nextLeft - safePadding;
  const spaceLeft = nextLeft - safePadding;
  if (spaceRight < menuWidth && spaceLeft > spaceRight) {
    nextLeft = nextLeft - menuWidth;
  }

  const spaceBelow = viewportHeight - nextTop - safePadding;
  const spaceAbove = nextTop - safePadding;
  if (spaceBelow < menuHeight && spaceAbove > spaceBelow) {
    nextTop = nextTop - menuHeight;
  }

  nextLeft = Math.min(nextLeft, viewportWidth - menuWidth - safePadding);
  nextTop = Math.min(nextTop, viewportHeight - menuHeight - safePadding);
  nextLeft = Math.max(safePadding, nextLeft);
  nextTop = Math.max(safePadding, nextTop);
  menu.style.left = `${nextLeft}px`;
  menu.style.top = `${nextTop}px`;
  menu.style.visibility = previousVisibility || "";
  if (wasHidden) {
    menu.classList.remove("hidden");
  }
}

function openAdaptiveFloatingMenu(
  menu,
  anchor,
  {
    preferredVertical = "bottom",
    preferredHorizontal = "left",
    offset = 8,
    fallbackWidth = 240,
    fallbackHeight = 180,
    padding = 8,
  } = {},
) {
  if (!menu || !anchor) {
    return false;
  }

  const anchorRect = anchor.getBoundingClientRect();
  const safeOffset = Number.isFinite(Number(offset)) ? Math.max(0, Number(offset)) : 8;
  const safePadding = Number.isFinite(Number(padding)) ? Math.max(0, Number(padding)) : 8;
  const wasHidden = menu.classList.contains("hidden");
  const previousVisibility = menu.style.visibility;
  const previousPosition = menu.style.position;
  if (wasHidden) {
    menu.style.visibility = "hidden";
    menu.classList.remove("hidden");
  }

  const rect = menu.getBoundingClientRect();
  const menuWidth = rect.width || Number(fallbackWidth) || 240;
  const menuHeight = rect.height || Number(fallbackHeight) || 180;

  if (wasHidden) {
    menu.classList.add("hidden");
  }
  menu.style.visibility = previousVisibility || "";
  menu.style.position = previousPosition || "";

  const viewportWidth = Math.max(window.innerWidth || 0, document.documentElement?.clientWidth || 0, menuWidth + safePadding * 2);
  const viewportHeight = Math.max(window.innerHeight || 0, document.documentElement?.clientHeight || 0, menuHeight + safePadding * 2);
  const spaceBelow = viewportHeight - anchorRect.bottom - safePadding;
  const spaceAbove = anchorRect.top - safePadding;
  const spaceRight = viewportWidth - anchorRect.left - safePadding;
  const spaceLeft = anchorRect.right - safePadding;

  const canOpenBelow = spaceBelow >= menuHeight + safeOffset;
  const canOpenAbove = spaceAbove >= menuHeight + safeOffset;
  const preferTop = preferredVertical === "top";
  const openAbove = preferTop
    ? canOpenAbove || (!canOpenBelow && spaceAbove > spaceBelow)
    : !canOpenBelow && canOpenAbove;

  const startLeft = anchorRect.left;
  const endLeft = anchorRect.right - menuWidth;
  const canAlignStart = startLeft >= safePadding && startLeft + menuWidth <= viewportWidth - safePadding;
  const canAlignEnd = endLeft >= safePadding && endLeft + menuWidth <= viewportWidth - safePadding;
  const preferRight = preferredHorizontal === "right";
  const alignEnd = preferRight
    ? canAlignEnd || (!canAlignStart && spaceLeft > spaceRight)
    : !canAlignStart && canAlignEnd;

  const preferredLeft = alignEnd ? endLeft : startLeft;
  const preferredTop = openAbove ? anchorRect.top - menuHeight - safeOffset : anchorRect.bottom + safeOffset;

  menu.style.position = "fixed";
  menu.classList.remove("hidden");
  positionFloatingMenu(menu, preferredLeft, preferredTop, {
    fallbackWidth,
    fallbackHeight,
    padding: safePadding,
  });
  return true;
}

function toggleAdaptiveFloatingMenu(menu, anchor, options) {
  if (!menu || !anchor) {
    return;
  }
  if (!menu.classList.contains("hidden")) {
    menu.classList.add("hidden");
    return;
  }
  openAdaptiveFloatingMenu(menu, anchor, options);
}

function toggleSearchHelpPopover(anchor = elements.searchHelpBtn) {
  const nextOpen = !state.searchHelpOpen;
  state.searchHelpOpen = nextOpen;
  if (!nextOpen) {
    elements.searchHelpPopover?.classList.add("hidden");
    return;
  }
  const opened = openAdaptiveFloatingMenu(elements.searchHelpPopover, anchor, {
    preferredVertical: "bottom",
    preferredHorizontal: "left",
    offset: 8,
    fallbackWidth: 260,
    fallbackHeight: 150,
    padding: 10,
  });
  if (!opened) {
    state.searchHelpOpen = false;
  }
}

function openChatContextMenu(x, y, chatId, folderId = state.activeFolderId) {
  if (!elements.chatContextMenu || !chatId) {
    return;
  }

  closeMessageContextMenu();
  state.chatContextChatId = chatId;
  state.chatContextFolderId = normalizeFolderId(folderId);
  const chat = state.chats.find((entry) => entry.id === chatId) ?? null;
  if (elements.chatContextPinBtn) {
    setMenuButtonLabel(elements.chatContextPinBtn, isChatPinned(chatId) ? t("unpinChat") : t("pinChat"));
  }
  if (elements.chatContextArchiveBtn) {
    setMenuButtonLabel(elements.chatContextArchiveBtn, isChatArchived(chatId) ? t("unarchiveChat") : t("archiveChat"));
  }
  if (elements.chatContextNotificationsBtn) {
    setMenuButtonLabel(elements.chatContextNotificationsBtn, getChatNotificationsMenuLabel(chatId));
  }
  if (elements.chatContextReadToggleBtn) {
    const unreadCount = getUnreadCountForChat(chatId);
    setMenuButtonLabel(elements.chatContextReadToggleBtn, unreadCount > 0 ? t("markAsRead") : t("markAsUnread"));
  }
  if (elements.chatContextLeaveBtn) {
    const canLeave = canLeaveChat(chat);
    const leaveLabel = chat?.type === "channel" ? t("entityLeaveChannel") : t("entityLeaveGroup");
    setMenuButtonLabel(elements.chatContextLeaveBtn, canLeave ? leaveLabel : t("leaveChat"));
    elements.chatContextLeaveBtn.classList.toggle("hidden", !canLeave);
  }
  if (elements.chatContextClearHistoryBtn) {
    elements.chatContextClearHistoryBtn.classList.toggle("hidden", !canClearChatHistory(chat));
  }
  if (elements.chatContextDeleteBtn) {
    const canDelete = Boolean(chat && (chat.type === "direct" || canManageChat(chat)));
    elements.chatContextDeleteBtn.classList.toggle("hidden", !canDelete);
  }
  if (elements.chatContextRemoveFromFolderBtn) {
    const folder = getFolderById(state.chatContextFolderId);
    const canRemove = Boolean(folder) && folder.id !== "all";
    setMenuButtonLabel(elements.chatContextRemoveFromFolderBtn, t("removeFromGroup"));
    elements.chatContextRemoveFromFolderBtn.classList.toggle("hidden", !canRemove);
  }

  elements.chatContextMenu.classList.remove("hidden");
  positionFloatingMenu(elements.chatContextMenu, x, y, {
    fallbackWidth: 250,
    fallbackHeight: 190,
  });
}

function closeMessageContextMenu() {
  state.messageContextMessageId = null;
  elements.messageContextMenu?.classList.add("hidden");
}

function openMessageContextMenu(x, y, messageId) {
  if (!elements.messageContextMenu || !messageId) {
    return;
  }
  const chat = getActiveChat();
  const message = findCurrentMessage(messageId);
  if (!chat || !message) {
    return;
  }

  closeChatContextMenu();
  state.messageContextMessageId = messageId;

  if (elements.messageContextPinBtn) {
    setMenuButtonLabel(elements.messageContextPinBtn, isMessagePinned(state.activeChatId, messageId) ? t("unpinMessage") : t("pinMessage"));
  }
  if (elements.messageContextEditBtn) {
    elements.messageContextEditBtn.classList.toggle("hidden", !canEditMessage(chat, message));
  }
  if (elements.messageContextDeleteBtn) {
    elements.messageContextDeleteBtn.classList.toggle("hidden", !canDeleteMessage(chat, message));
  }
  if (elements.messageContextCopyBtn) {
    const canCopy = Boolean(getMessagePreviewText(message).trim());
    elements.messageContextCopyBtn.classList.toggle("hidden", !canCopy);
  }
  if (elements.messageContextSaveSoundBtn) {
    const canSaveSound = Boolean(message.file?.id) && String(message.file?.mimeType ?? "").startsWith("audio/");
    elements.messageContextSaveSoundBtn.classList.toggle("hidden", !canSaveSound);
  }
  if (elements.messageContextForwardBtn) {
    elements.messageContextForwardBtn.classList.toggle("hidden", isSecretChat(state.activeChatId));
  }
  if (elements.messageContextReactions) {
    elements.messageContextReactions.innerHTML = "";
    for (const emoji of QUICK_REACTIONS) {
      const reactionBtn = document.createElement("button");
      reactionBtn.type = "button";
      reactionBtn.className = "message-context-reaction-btn";
      reactionBtn.dataset.emoji = emoji;
      reactionBtn.dataset.messageId = messageId;
      reactionBtn.appendChild(createEmojiGlyphNode(emoji));
      const existing = Array.isArray(message.reactions) ? message.reactions.find((entry) => entry.emoji === emoji) : null;
      reactionBtn.classList.toggle("active", Boolean(existing?.mine));
      elements.messageContextReactions.appendChild(reactionBtn);
    }
  }

  elements.messageContextMenu.classList.remove("hidden");
  positionFloatingMenu(elements.messageContextMenu, x, y, {
    fallbackWidth: 252,
    fallbackHeight: 290,
  });
}

function getCallChat() {
  if (!state.call.chatId) {
    return null;
  }

  return state.chats.find((entry) => entry.id === state.call.chatId) ?? null;
}

function getCallSelfParticipant() {
  if (!state.user?.id) {
    return null;
  }

  return {
    id: String(state.user.id),
    chatId: state.user.chatId ?? "",
    username: state.user.username ?? "",
    displayName: getUserDisplayName(state.user),
    avatar: String(state.user.avatar ?? ""),
  };
}

function normalizeCallParticipant(input) {
  const safeId = String(input?.id ?? input?.userId ?? "").trim();
  if (!safeId) {
    return null;
  }

  const known = findKnownUserById(safeId);
  const displayName = getUserDisplayName({
    id: safeId,
    displayName: input?.displayName ?? known?.displayName ?? input?.username ?? known?.username ?? t("unknownUser"),
  });

  return {
    id: safeId,
    chatId: String(input?.chatId ?? known?.chatId ?? "").trim(),
    username: String(input?.username ?? known?.username ?? "").trim(),
    displayName,
    avatar: String(input?.avatar ?? known?.avatar ?? "").trim(),
  };
}

function upsertCallParticipant(input) {
  const participant = normalizeCallParticipant(input);
  if (!participant) {
    return null;
  }

  state.call.participants[participant.id] = participant;
  return participant;
}

function removeCallParticipant(userId) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return;
  }
  delete state.call.participants[safeUserId];
}

function ensureCallSelfParticipant() {
  const participant = getCallSelfParticipant();
  if (!participant) {
    return;
  }
  state.call.participants[participant.id] = participant;
}

function setCallParticipants(participants = []) {
  state.call.participants = {};
  for (const participant of participants) {
    upsertCallParticipant(participant);
  }
  ensureCallSelfParticipant();
}

function mergeCallParticipants(participants = []) {
  for (const participant of participants) {
    upsertCallParticipant(participant);
  }
  ensureCallSelfParticipant();
}

function getCallParticipantsList() {
  ensureCallSelfParticipant();
  const participants = Object.values(state.call.participants ?? {});
  participants.sort((a, b) => {
    if (a.id === String(state.user?.id ?? "")) {
      return -1;
    }
    if (b.id === String(state.user?.id ?? "")) {
      return 1;
    }
    return String(a.displayName ?? "").localeCompare(String(b.displayName ?? ""), state.lang, { sensitivity: "base" });
  });
  return participants;
}

function buildCallParticipantsForChat(chat) {
  const participants = {};
  const selfParticipant = getCallSelfParticipant();
  if (selfParticipant) {
    participants[selfParticipant.id] = selfParticipant;
  }
  if (!chat) {
    return participants;
  }

  if (chat.type === "direct") {
    const normalizedPeer = normalizeCallParticipant(getDirectPeer(chat));
    if (normalizedPeer) {
      participants[normalizedPeer.id] = normalizedPeer;
    }
    return participants;
  }

  for (const member of chat.members ?? []) {
    const normalizedMember = normalizeCallParticipant(member);
    if (normalizedMember) {
      participants[normalizedMember.id] = normalizedMember;
    }
  }
  return participants;
}

function isGroupCallChat(chat = getCallChat()) {
  return chat?.type === "group" || isServerChat(chat);
}

function getPrimaryRemoteParticipant() {
  const selfId = String(state.user?.id ?? "");
  const participants = getCallParticipantsList();
  return participants.find((participant) => participant.id !== selfId) ?? null;
}

function shouldInitiateCallOffer(peerId) {
  const safePeerId = String(peerId ?? "").trim();
  const selfId = String(state.user?.id ?? "").trim();
  if (!safePeerId || !selfId || safePeerId === selfId) {
    return false;
  }
  return selfId.localeCompare(safePeerId) > 0;
}

function getInitialSymbol(value, fallback = "Y") {
  const text = String(value ?? "").trim();
  if (!text) {
    return fallback;
  }
  return text.charAt(0).toUpperCase();
}

function getChatTypeIconName(type) {
  if (type === "group") {
    return "users";
  }
  if (type === "channel") {
    return "megaphone";
  }
  if (type === "server") {
    return "home";
  }
  return "";
}

function applyChatAvatarNode(node, chat, title) {
  if (!node) {
    return;
  }

  node.classList.remove("chat-avatar-group", "chat-avatar-channel", "chat-avatar-server", "chat-avatar-icon-only", "avatar-has-image");
  const safeAvatar = String(chat?.avatar ?? "").trim();
  if (safeAvatar) {
    applyAvatarNode(node, title, safeAvatar, "Y");
    return;
  }

  const iconName = getChatTypeIconName(chat?.type);
  if (!iconName) {
    applyAvatarNode(node, title, "", "Y");
    return;
  }

  node.style.backgroundImage = "";
  node.textContent = "";
  node.classList.add("chat-avatar-icon-only", `chat-avatar-${chat.type}`);
  const iconNode = document.createElement("span");
  iconNode.className = "chat-type-avatar-icon svg-icon";
  iconNode.dataset.svgIcon = iconName;
  node.appendChild(iconNode);
  renderSvgIcons(node);
}

function applyAvatarNode(node, name, avatarUrl, fallback = "Y") {
  if (!node) {
    return;
  }

  const safeAvatar = String(avatarUrl ?? "").trim();
  const fallbackSymbol = getInitialSymbol(name, fallback);
  const clearImageNode = () => {
    const imageNode = node.querySelector("img.avatar-image");
    if (imageNode) {
      imageNode.remove();
    }
  };
  if (safeAvatar) {
    node.classList.remove("chat-avatar-group", "chat-avatar-channel", "chat-avatar-server", "chat-avatar-icon-only");
    node.classList.add("avatar-has-image");
    node.style.backgroundImage = "";
    node.textContent = "";
    let imageNode = node.querySelector("img.avatar-image");
    if (!imageNode) {
      imageNode = document.createElement("img");
      imageNode.className = "avatar-image";
      imageNode.loading = "lazy";
      imageNode.decoding = "async";
      node.appendChild(imageNode);
    }
    imageNode.src = safeAvatar;
    imageNode.alt = String(name ?? fallbackSymbol);
    imageNode.onerror = () => {
      clearImageNode();
      node.classList.remove("avatar-has-image");
      node.textContent = fallbackSymbol;
    };
    return;
  }

  clearImageNode();
  node.classList.remove("avatar-has-image");
  node.style.backgroundImage = "";
  node.textContent = fallbackSymbol;
}

function openMyProfilePanel() {
  if (isMobilePlatform() && state.mobileChatView === "chat") {
    setMobileChatView("list");
  }
  if (state.platform === "iphone") {
    openIphoneDrawerTab("profile", { presentation: "push" });
    return;
  }
  setDrawerTab("profile");
}

function getCallPeerIdentity() {
  const chat = getCallChat();
  if (isGroupCallChat(chat)) {
    const focused = state.call.focusParticipantId ? state.call.participants[state.call.focusParticipantId] : null;
    const mainParticipant = focused && focused.id !== String(state.user?.id ?? "") ? focused : getPrimaryRemoteParticipant();
    if (mainParticipant) {
      return {
        displayName: mainParticipant.displayName,
        username: String(mainParticipant.username ?? "").trim(),
        avatar: String(mainParticipant.avatar ?? "").trim(),
      };
    }

    return {
      displayName: chat?.title ?? localizeType(chat?.type ?? "group"),
      username: "",
      avatar: "",
    };
  }

  const fallbackPeer = getDirectPeer(chat);
  const participantPeer = state.call.peer?.id ? state.call.participants[state.call.peer.id] : null;
  const fallbackDisplayName =
    participantPeer?.displayName ?? state.call.peer?.displayName ?? fallbackPeer?.displayName ?? chat?.title ?? localizeType(chat?.type ?? "direct");
  const fallbackUsername = participantPeer?.username ?? state.call.peer?.username ?? fallbackPeer?.username ?? chat?.handle ?? "";
  const fallbackAvatar = participantPeer?.avatar ?? state.call.peer?.avatar ?? fallbackPeer?.avatar ?? "";

  const displayName = getUserDisplayName({
    id: participantPeer?.id ?? state.call.peer?.id ?? fallbackPeer?.userId,
    userId: participantPeer?.id ?? state.call.peer?.id ?? fallbackPeer?.userId,
    displayName: fallbackDisplayName,
  });
  const username = String(fallbackUsername).trim();
  const avatar = String(fallbackAvatar).trim();

  return {
    displayName,
    username,
    avatar,
  };
}

function normalizeCallMode(value) {
  return String(value ?? "").trim() === "video" ? "video" : "audio";
}

function getCallModeIcon(mode) {
  return normalizeCallMode(mode) === "video" ? t("callVideoLabel") : t("callAudioLabel");
}

function getCallModeLabel(mode) {
  return normalizeCallMode(mode) === "video" ? t("callVideoLabel") : t("callAudioLabel");
}

function isVideoCallMode(mode) {
  return normalizeCallMode(mode) === "video";
}

function isServerChat(chat) {
  return chat?.type === "server";
}

function setServerChatMode(active) {
  const enabled = Boolean(active) || isGameMode();
  document.body.classList.toggle("server-chat-active", enabled);
  elements.chatMain?.classList.toggle("server-chat-active", enabled);
  elements.serverChannelPanel?.classList.toggle("hidden", !enabled);
  elements.serverMembersPanel?.classList.toggle("hidden", !enabled);
  elements.streamSwitch?.classList.toggle("hidden", enabled);
}

function isChannelLikeChat(chat) {
  return chat?.type === "channel" || isServerChat(chat);
}

function canCallInChat(chat) {
  if (!chat) {
    return false;
  }

  if (chat.type === "direct") {
    const peer = getDirectPeer(chat);
    if (peer && isBotUser(peer)) {
      return false;
    }
    return true;
  }

  return chat.type === "group" || isServerChat(chat);
}

function getCallStatusLabel() {
  let statusLabel = "";

  if (state.call.status === "incoming") {
    statusLabel = t("callStatusIncoming");
  }

  if (state.call.status === "calling") {
    statusLabel = t("callStatusCalling");
  }

  if (state.call.status === "connecting") {
    statusLabel = t("callStatusConnecting");
  }

  if (state.call.status === "connected") {
    statusLabel = t("callStatusConnected");
  }

  if (state.call.status === "ended") {
    const duration = Math.max(0, Number(state.call.endedDurationSeconds) || 0);
    return duration > 0 ? `${t("callEnded")} · ${formatDuration(duration)}` : t("callEnded");
  }

  if (!statusLabel) {
    return "";
  }

  const chat = getCallChat();
  if (isGroupCallChat(chat)) {
    const participants = Math.max(0, getCallParticipantsList().length - 1);
    return `${statusLabel} · ${getCallModeLabel(state.call.mode)} · ${participants + 1}`;
  }

  return `${statusLabel} · ${getCallModeLabel(state.call.mode)}`;
}

function hashStringToUint32(value) {
  const input = String(value ?? "");
  let hash = 2166136261;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function getCallVerificationEmojis() {
  const sessionId = String(state.call.sessionId ?? "").trim();
  const chatId = String(state.call.chatId ?? "").trim();
  if (!sessionId || !chatId) {
    return [];
  }
  const participantKey = getCallParticipantsList()
    .map((participant) => String(participant.id ?? "").trim())
    .filter(Boolean)
    .sort()
    .join("|");
  let seed = hashStringToUint32(`${sessionId}|${chatId}|${state.call.mode}|${participantKey}`);
  const picked = [];
  const used = new Set();
  for (let attempts = 0; attempts < 32 && picked.length < 4; attempts += 1) {
    seed = (Math.imul(seed ^ (attempts + 1), 1664525) + 1013904223) >>> 0;
    const emoji = CALL_VERIFICATION_EMOJI[seed % CALL_VERIFICATION_EMOJI.length];
    if (!used.has(emoji)) {
      used.add(emoji);
      picked.push(emoji);
    }
  }
  return picked;
}

function renderCallVerification({ groupMode = false, inProgress = false } = {}) {
  if (!elements.callVerificationStrip || !elements.callVerificationEmojis) {
    return;
  }
  const visible = Boolean(groupMode && inProgress);
  elements.callVerificationStrip.classList.toggle("hidden", !visible);
  elements.callVerificationEmojis.innerHTML = "";
  if (!visible) {
    return;
  }
  for (const emoji of getCallVerificationEmojis()) {
    const token = document.createElement("span");
    token.className = "call-verification-emoji";
    token.appendChild(createEmojiGlyphNode(emoji));
    elements.callVerificationEmojis.appendChild(token);
  }
}

function hasActiveVideoTrack(stream) {
  const tracks = stream?.getVideoTracks?.() ?? [];
  return tracks.some((track) => track.readyState === "live" && track.enabled !== false);
}

function hasLiveAudioTrack(stream) {
  const tracks = stream?.getAudioTracks?.() ?? [];
  return tracks.some((track) => track.readyState === "live");
}

function getCallMiniSize(wrapRect) {
  const miniWidth = Math.min(190, Math.max(108, wrapRect.width * 0.19));
  const miniHeight = (miniWidth * 4) / 3;
  return { miniWidth, miniHeight };
}

function applyCallMiniPosition() {
  if (!elements.callVideoWrap) {
    return;
  }

  const position = state.call.miniPosition;
  if (!position) {
    elements.callVideoWrap.style.removeProperty("--mini-left");
    elements.callVideoWrap.style.removeProperty("--mini-top");
    elements.callVideoWrap.style.removeProperty("--mini-right");
    elements.callVideoWrap.style.removeProperty("--mini-bottom");
    return;
  }

  const wrapRect = elements.callVideoWrap.getBoundingClientRect();
  const { miniWidth, miniHeight } = getCallMiniSize(wrapRect);
  const maxLeft = Math.max(0, wrapRect.width - miniWidth);
  const maxTop = Math.max(0, wrapRect.height - miniHeight);
  const left = Math.max(0, Math.min(maxLeft, Number(position.left) || 0));
  const top = Math.max(0, Math.min(maxTop, Number(position.top) || 0));

  elements.callVideoWrap.style.setProperty("--mini-left", `${left}px`);
  elements.callVideoWrap.style.setProperty("--mini-top", `${top}px`);
  elements.callVideoWrap.style.setProperty("--mini-right", "auto");
  elements.callVideoWrap.style.setProperty("--mini-bottom", "auto");
}

function isCallFullscreenActive() {
  return document.fullscreenElement === elements.callCard;
}

function getCallStreamByParticipantId(participantId) {
  const safeParticipantId = String(participantId ?? "").trim();
  if (!safeParticipantId) {
    return null;
  }

  if (safeParticipantId === String(state.user?.id ?? "").trim()) {
    return state.call.localStream ?? null;
  }

  return state.call.remoteStreamsByPeer[safeParticipantId] ?? null;
}

function participantHasVideo(participantId, stream) {
  const safeParticipantId = String(participantId ?? "").trim();
  if (!safeParticipantId) {
    return false;
  }

  const hasVideo = hasActiveVideoTrack(stream);
  if (safeParticipantId === String(state.user?.id ?? "").trim()) {
    return Boolean(state.call.videoEnabled && hasVideo && !state.call.screenSharing);
  }

  return hasVideo;
}

function createGroupCallTile(participant, { large = false } = {}) {
  const participantId = String(participant?.id ?? "").trim();
  if (!participantId) {
    return null;
  }

  const stream = getCallStreamByParticipantId(participantId);
  const hasVideo = participantHasVideo(participantId, stream);
  const isSelf = participantId === String(state.user?.id ?? "").trim();

  const tile = document.createElement("button");
  tile.type = "button";
  tile.className = `call-group-tile${large ? " large" : ""}`;
  tile.classList.toggle("self", isSelf);
  tile.classList.toggle("focused", state.call.focusParticipantId === participantId);
  tile.title = participant.displayName ?? t("unknownUser");

  const video = document.createElement("video");
  video.autoplay = true;
  video.playsInline = true;
  video.muted = isSelf;
  video.className = "call-group-video";
  video.srcObject = stream ?? null;
  video.classList.toggle("hidden", !hasVideo);
  safePlayMediaElement(video);
  tile.appendChild(video);

  if (!isSelf) {
    const audio = document.createElement("audio");
    audio.autoplay = true;
    audio.playsInline = true;
    audio.className = "hidden";
    audio.srcObject = stream ?? null;
    safePlayMediaElement(audio);
    tile.appendChild(audio);
  }

  const fallback = document.createElement("div");
  fallback.className = "call-group-fallback";
  fallback.classList.toggle("hidden", hasVideo);
  const avatar = document.createElement("div");
  avatar.className = "call-group-fallback-avatar";
  applyAvatarNode(avatar, participant.displayName, participant.avatar, "Y");
  fallback.appendChild(avatar);
  tile.appendChild(fallback);

  const label = document.createElement("div");
  label.className = "call-group-label";
  label.textContent = participant.displayName ?? t("unknownUser");
  tile.appendChild(label);

  tile.addEventListener("click", () => {
    if (large) {
      state.call.focusParticipantId = null;
      renderCallState();
      return;
    }
    state.call.focusParticipantId = state.call.focusParticipantId === participantId ? null : participantId;
    renderCallState();
  });

  return tile;
}

function renderGroupCallStage() {
  if (!elements.callGroupStage || !elements.callGroupGrid || !elements.callGroupMain) {
    return;
  }

  const participants = getCallParticipantsList();
  if (!participants.length) {
    elements.callGroupStage.classList.add("hidden");
    return;
  }

  elements.callGroupStage.classList.remove("hidden");
  elements.callGroupGrid.innerHTML = "";
  elements.callGroupMain.innerHTML = "";

  const validFocus = participants.some((participant) => participant.id === state.call.focusParticipantId);
  if (!validFocus) {
    state.call.focusParticipantId = null;
  }

  if (state.call.focusParticipantId) {
    const focused = participants.find((participant) => participant.id === state.call.focusParticipantId) ?? null;
    if (focused) {
      const focusedTile = createGroupCallTile(focused, { large: true });
      if (focusedTile) {
        elements.callGroupMain.appendChild(focusedTile);
        elements.callGroupMain.classList.remove("hidden");
      } else {
        elements.callGroupMain.classList.add("hidden");
      }
    }
  } else {
    elements.callGroupMain.classList.add("hidden");
  }

  const gridParticipants = state.call.focusParticipantId
    ? participants.filter((participant) => participant.id !== state.call.focusParticipantId)
    : participants;
  elements.callGroupGrid.classList.toggle("with-focus", Boolean(state.call.focusParticipantId));
  for (const participant of gridParticipants) {
    const tile = createGroupCallTile(participant);
    if (tile) {
      elements.callGroupGrid.appendChild(tile);
    }
  }
}

function updateScreenMiniStrip({ show, hasRemoteVideo, hasLocalVideo, peerIdentity }) {
  if (!elements.callScreenMiniStrip) {
    return;
  }

  elements.callScreenMiniStrip.classList.toggle("hidden", !show);
  if (!show) {
    if (elements.callScreenMiniRemoteVideo) {
      elements.callScreenMiniRemoteVideo.srcObject = null;
    }
    if (elements.callScreenMiniLocalVideo) {
      elements.callScreenMiniLocalVideo.srcObject = null;
    }
    return;
  }

  if (elements.callScreenMiniRemoteVideo) {
    elements.callScreenMiniRemoteVideo.srcObject = state.call.remoteStream ?? null;
    elements.callScreenMiniRemoteVideo.muted = true;
    elements.callScreenMiniRemoteVideo.classList.toggle("hidden", !hasRemoteVideo);
    safePlayMediaElement(elements.callScreenMiniRemoteVideo);
  }
  if (elements.callScreenMiniLocalVideo) {
    elements.callScreenMiniLocalVideo.srcObject = state.call.localStream ?? null;
    elements.callScreenMiniLocalVideo.muted = true;
    elements.callScreenMiniLocalVideo.classList.toggle("hidden", !hasLocalVideo);
    safePlayMediaElement(elements.callScreenMiniLocalVideo);
  }
  if (elements.callScreenMiniRemoteAvatar) {
    applyAvatarNode(elements.callScreenMiniRemoteAvatar, peerIdentity.displayName, peerIdentity.avatar, "Y");
  }
  if (elements.callScreenMiniLocalAvatar) {
    applyAvatarNode(
      elements.callScreenMiniLocalAvatar,
      getUserDisplayName(state.user),
      String(state.user?.avatar ?? ""),
      "Y",
    );
  }
  if (elements.callScreenMiniRemoteFallback) {
    elements.callScreenMiniRemoteFallback.classList.toggle("hidden", hasRemoteVideo);
  }
  if (elements.callScreenMiniLocalFallback) {
    elements.callScreenMiniLocalFallback.classList.toggle("hidden", hasLocalVideo);
  }
}

function safePlayMediaElement(node) {
  if (!node || typeof node.play !== "function") {
    return;
  }
  node.play().catch(() => {
    // Autoplay can be blocked until a user gesture on some devices.
  });
}

function renderCallState() {
  const active = state.call.status !== "idle";
  elements.callPanel.classList.toggle("hidden", !active);
  if (!active) {
    clearCallConnectWatchdog();
    elements.callRemoteAudio.srcObject = null;
    if (elements.callRemoteVideo) {
      elements.callRemoteVideo.srcObject = null;
    }
    if (elements.callLocalVideo) {
      elements.callLocalVideo.srcObject = null;
    }
    if (elements.callVideoWrap) {
      elements.callVideoWrap.classList.add("hidden");
      elements.callVideoWrap.classList.remove("local-focus");
    }
    if (elements.callGroupStage) {
      elements.callGroupStage.classList.add("hidden");
    }
    if (elements.callGroupMain) {
      elements.callGroupMain.innerHTML = "";
    }
    if (elements.callGroupGrid) {
      elements.callGroupGrid.innerHTML = "";
    }
    if (elements.callScreenMiniStrip) {
      elements.callScreenMiniStrip.classList.add("hidden");
    }
    if (elements.callMiniBtn) {
      elements.callMiniBtn.classList.add("hidden");
      elements.callMiniBtn.classList.remove("active");
    }
    if (elements.callFullscreenBtn) {
      elements.callFullscreenBtn.classList.add("hidden");
      elements.callFullscreenBtn.classList.remove("active");
    }
    state.call.controlsExpanded = false;
    state.call.keypadOpen = false;
    state.call.keypadDigits = "";
    if (elements.callExtraPanel) {
      elements.callExtraPanel.classList.add("hidden");
    }
    if (elements.callAddBtn) {
      elements.callAddBtn.classList.add("hidden");
    }
    if (elements.callKeypadBtn) {
      elements.callKeypadBtn.classList.add("hidden");
      elements.callKeypadBtn.classList.remove("active");
    }
    if (elements.callKeypadPanel) {
      elements.callKeypadPanel.classList.add("hidden");
    }
    if (elements.callKeypadDisplay) {
      elements.callKeypadDisplay.textContent = t("callKeypadEmpty");
    }
    if (elements.callIncomingNote) {
      elements.callIncomingNote.classList.add("hidden");
    }
    if (elements.callVerificationStrip) {
      elements.callVerificationStrip.classList.add("hidden");
    }
    if (elements.callVerificationEmojis) {
      elements.callVerificationEmojis.innerHTML = "";
    }
    if (elements.callCard) {
      elements.callCard.classList.remove("incoming-mode");
      elements.callCard.classList.remove("video-mode");
      elements.callCard.classList.remove("video-focus");
      elements.callCard.classList.remove("group-mode");
      elements.callCard.classList.remove("call-controls-expanded");
    }
    if (elements.callPeerAvatar) {
      applyAvatarNode(elements.callPeerAvatar, "Y", "", "Y");
      elements.callPeerAvatar.title = "";
    }
    if (elements.callPeerUsername) {
      elements.callPeerUsername.textContent = "";
    }
    if (elements.callModeBadge) {
      elements.callModeBadge.textContent = "";
      elements.callModeBadge.dataset.svgIcon = "phone";
      renderSvgIcons(elements.callModeBadge);
    }
    if (elements.callRemoteFallback) {
      elements.callRemoteFallback.classList.add("hidden");
    }
    if (elements.callLocalFallback) {
      elements.callLocalFallback.classList.add("hidden");
    }
    if (elements.callScreenMiniRemoteVideo) {
      elements.callScreenMiniRemoteVideo.srcObject = null;
    }
    if (elements.callScreenMiniLocalVideo) {
      elements.callScreenMiniLocalVideo.srcObject = null;
    }
    applyCallMiniPosition();
    elements.callStatus.textContent = "";
    return;
  }

  ensureCallSelfParticipant();
  const peerIdentity = getCallPeerIdentity();
  elements.callPeer.textContent = peerIdentity.displayName;
  if (elements.callPeerUsername) {
    const showUsername = !isGroupCallChat(getCallChat()) && peerIdentity.username;
    elements.callPeerUsername.textContent = showUsername ? `@${peerIdentity.username}` : "";
  }
  if (elements.callPeerAvatar) {
    applyAvatarNode(elements.callPeerAvatar, peerIdentity.displayName, peerIdentity.avatar, "Y");
    elements.callPeerAvatar.title = t("openProfile");
  }
  if (elements.callModeBadge) {
    elements.callModeBadge.textContent = "";
    elements.callModeBadge.dataset.svgIcon = normalizeCallMode(state.call.mode) === "video" ? "video" : "phone";
    renderSvgIcons(elements.callModeBadge);
  }
  elements.callStatus.textContent = getCallStatusLabel();
  const callChat = getCallChat();
  const groupMode = isGroupCallChat(callChat);

  if (!groupMode) {
    elements.callRemoteAudio.srcObject = state.call.remoteStream ?? null;
    elements.callRemoteAudio.muted = false;
    safePlayMediaElement(elements.callRemoteAudio);
    updateCallSpeakerState();
    if (elements.callRemoteVideo) {
      elements.callRemoteVideo.srcObject = state.call.remoteStream ?? null;
      elements.callRemoteVideo.muted = true;
      safePlayMediaElement(elements.callRemoteVideo);
    }
    if (elements.callLocalVideo) {
      elements.callLocalVideo.srcObject = state.call.localStream ?? null;
      safePlayMediaElement(elements.callLocalVideo);
    }
  } else {
    elements.callRemoteAudio.srcObject = null;
  }

  const incoming = state.call.status === "incoming";
  const ended = state.call.status === "ended";
  const inProgress = ["calling", "connecting", "connected"].includes(state.call.status);
  const videoMode = isVideoCallMode(state.call.mode);
  const canInviteToCallChat = Boolean(groupMode && callChat && canInviteMembers(callChat));
  const hasRemoteVideo = groupMode
    ? Object.values(state.call.remoteStreamsByPeer ?? {}).some((stream) => hasActiveVideoTrack(stream))
    : hasActiveVideoTrack(state.call.remoteStream);
  const hasRemoteAudio = groupMode
    ? Object.values(state.call.remoteStreamsByPeer ?? {}).some((stream) => hasLiveAudioTrack(stream))
    : hasLiveAudioTrack(state.call.remoteStream);
  const hasRemoteMedia = hasRemoteVideo || hasRemoteAudio;
  const localVideoTrackActive = hasActiveVideoTrack(state.call.localStream);
  const hasLocalVideo = Boolean(localVideoTrackActive && !state.call.screenSharing);
  const showVideo = groupMode || videoMode || hasRemoteVideo || localVideoTrackActive;
  const videoFocus = showVideo && inProgress;

  if (!groupMode && inProgress) {
    if (hasLocalVideo && !hasRemoteVideo) {
      state.call.videoFocus = "local";
    } else if (hasRemoteVideo && !hasLocalVideo) {
      state.call.videoFocus = "remote";
    }
  }

  elements.callAcceptBtn.classList.toggle("hidden", !incoming);
  elements.callDeclineBtn.classList.toggle("hidden", !incoming && !ended);
  elements.callHangupBtn.classList.toggle("hidden", !inProgress);
  if (elements.callDeclineBtn) {
    elements.callDeclineBtn.title = ended ? t("close") : t("callDecline");
    elements.callDeclineBtn.dataset.svgIcon = "x";
    renderSvgIcons(elements.callDeclineBtn);
  }
  elements.callMuteBtn.classList.toggle("hidden", !inProgress);
  const muteActionLabel = state.call.muted ? t("callUnmute") : t("callMute");
  elements.callMuteBtn.dataset.svgIcon = state.call.muted ? "mic" : "mic-off";
  renderSvgIcons(elements.callMuteBtn);
  elements.callMuteBtn.title = muteActionLabel;
  elements.callMuteBtn.classList.toggle("active", state.call.muted);
  if (elements.callSpeakerBtn) {
    elements.callSpeakerBtn.classList.toggle("hidden", !inProgress);
    const speakerActionLabel =
      state.call.audioRoute === "speaker"
        ? t("callAudioRouteSpeaker")
        : state.call.audioRoute === "bluetooth"
          ? t("callAudioRouteBluetooth")
          : t("callAudioRoutePhone");
    elements.callSpeakerBtn.dataset.svgIcon = "volume";
    renderSvgIcons(elements.callSpeakerBtn);
    elements.callSpeakerBtn.title = speakerActionLabel;
    elements.callSpeakerBtn.classList.toggle("active", state.call.audioRoute !== "phone");
  }
  if (elements.callCameraBtn) {
    elements.callCameraBtn.classList.toggle("hidden", !inProgress || !videoMode);
    const cameraActionLabel = state.call.videoEnabled ? t("callCameraOff") : t("callCameraOn");
    elements.callCameraBtn.dataset.svgIcon = state.call.videoEnabled ? "video-off" : "video";
    renderSvgIcons(elements.callCameraBtn);
    elements.callCameraBtn.title = cameraActionLabel;
    elements.callCameraBtn.classList.toggle("active", state.call.videoEnabled);
  }
  if (elements.callScreenBtn) {
    const canShareScreen = inProgress && videoMode;
    elements.callScreenBtn.classList.toggle("hidden", !canShareScreen);
    elements.callScreenBtn.dataset.svgIcon = "screen";
    renderSvgIcons(elements.callScreenBtn);
    elements.callScreenBtn.title = state.call.screenSharing ? t("callScreenShareStop") : t("callScreenShareStart");
    elements.callScreenBtn.classList.toggle("active", state.call.screenSharing);
  }
  if (elements.callMiniBtn) {
    const canToggleMini = inProgress && videoMode && !groupMode && state.call.screenSharing;
    elements.callMiniBtn.classList.toggle("hidden", !canToggleMini);
    elements.callMiniBtn.dataset.svgIcon = "layout";
    renderSvgIcons(elements.callMiniBtn);
    elements.callMiniBtn.title = state.call.showScreenMini ? t("callHideMiniVideos") : t("callShowMiniVideos");
    elements.callMiniBtn.classList.toggle("active", state.call.showScreenMini);
  }
  if (elements.callFullscreenBtn) {
    const canFullscreen = inProgress && showVideo;
    const fullscreenActive = isCallFullscreenActive();
    elements.callFullscreenBtn.classList.toggle("hidden", !canFullscreen);
    elements.callFullscreenBtn.dataset.svgIcon = fullscreenActive ? "minimize" : "maximize";
    renderSvgIcons(elements.callFullscreenBtn);
    elements.callFullscreenBtn.title = fullscreenActive ? t("callExitFullscreen") : t("callFullscreen");
    elements.callFullscreenBtn.classList.toggle("active", fullscreenActive);
  }
  if (elements.callExtraPanel) {
    const showExtraPanel = inProgress && (isIphonePlatform() ? state.call.controlsExpanded : true);
    elements.callExtraPanel.classList.toggle("hidden", !showExtraPanel);
  }
  if (elements.callAddBtn) {
    elements.callAddBtn.classList.toggle("hidden", !inProgress || !canInviteToCallChat);
  }
  if (elements.callNoiseBtn) {
    elements.callNoiseBtn.classList.toggle("hidden", !inProgress);
    elements.callNoiseBtn.classList.toggle("active", state.call.noiseCancellation !== false);
    elements.callNoiseBtn.title = state.call.noiseCancellation !== false ? t("callNoiseCancellationOn") : t("callNoiseCancellationOff");
  }
  if (elements.callKeypadBtn) {
    const showKeypadToggle = inProgress;
    elements.callKeypadBtn.classList.toggle("hidden", !showKeypadToggle);
    elements.callKeypadBtn.classList.toggle("active", Boolean(state.call.keypadOpen));
  }
  if (elements.callKeypadPanel) {
    const canShowKeypad = inProgress && state.call.keypadOpen && (isIphonePlatform() ? state.call.controlsExpanded : true);
    elements.callKeypadPanel.classList.toggle("hidden", !canShowKeypad);
  }
  if (elements.callKeypadDisplay) {
    elements.callKeypadDisplay.textContent = state.call.keypadDigits || t("callKeypadEmpty");
  }
  if (elements.callIncomingNote) {
    elements.callIncomingNote.classList.toggle("hidden", !incoming);
  }
  renderCallVerification({ groupMode, inProgress });
  if (elements.callVideoWrap) {
    elements.callVideoWrap.classList.toggle("hidden", !showVideo);
    elements.callVideoWrap.classList.toggle("local-focus", !groupMode && showVideo && state.call.videoFocus === "local");
  }
  if (elements.callCard) {
    elements.callCard.classList.toggle("incoming-mode", incoming);
    elements.callCard.classList.toggle("video-mode", showVideo);
    elements.callCard.classList.toggle("video-focus", videoFocus);
    elements.callCard.classList.toggle("group-mode", groupMode);
    elements.callCard.classList.toggle("call-controls-expanded", Boolean(state.call.controlsExpanded));
  }
  if (elements.callRemoteFallbackAvatar) {
    applyAvatarNode(elements.callRemoteFallbackAvatar, peerIdentity.displayName, peerIdentity.avatar, "Y");
  }
  if (elements.callLocalFallbackAvatar) {
    applyAvatarNode(
      elements.callLocalFallbackAvatar,
      getUserDisplayName(state.user),
      String(state.user?.avatar ?? ""),
      "Y",
    );
  }

  if (groupMode) {
    if (elements.callRemoteFallback) {
      elements.callRemoteFallback.classList.add("hidden");
    }
    if (elements.callLocalFallback) {
      elements.callLocalFallback.classList.add("hidden");
    }
    if (elements.callRemoteVideo) {
      elements.callRemoteVideo.classList.add("hidden");
    }
    if (elements.callLocalVideo) {
      elements.callLocalVideo.classList.add("hidden");
    }
    if (elements.callScreenMiniStrip) {
      elements.callScreenMiniStrip.classList.add("hidden");
    }
    renderGroupCallStage();
  } else {
    if (elements.callGroupStage) {
      elements.callGroupStage.classList.add("hidden");
    }
    if (elements.callRemoteVideo) {
      elements.callRemoteVideo.classList.remove("hidden");
    }
    if (elements.callLocalVideo) {
      elements.callLocalVideo.classList.remove("hidden");
    }
    if (elements.callRemoteFallback) {
      elements.callRemoteFallback.classList.toggle("hidden", !showVideo || hasRemoteVideo);
    }
    if (elements.callLocalFallback) {
      elements.callLocalFallback.classList.toggle("hidden", !showVideo || hasLocalVideo);
    }
    updateScreenMiniStrip({
      show: Boolean(state.call.showScreenMini && state.call.screenSharing && inProgress && videoMode),
      hasRemoteVideo,
      hasLocalVideo,
      peerIdentity,
    });
    applyCallMiniPosition();
  }
  updateCallSpeakerState();
  renderSvgIcons(elements.callPanel);
  syncCallConnectWatchdog({ force: Boolean(state.call.status === "connected" && inProgress && !hasRemoteMedia) });
}

function toggleCallControlsExpanded(forceValue = null) {
  if (state.call.status === "idle") {
    return;
  }
  state.call.controlsExpanded = typeof forceValue === "boolean" ? forceValue : !state.call.controlsExpanded;
  if (!state.call.controlsExpanded) {
    state.call.keypadOpen = false;
  }
  renderCallState();
}

function toggleCallKeypad(forceValue = null) {
  if (state.call.status === "idle") {
    return;
  }
  if (!state.call.controlsExpanded) {
    state.call.controlsExpanded = true;
  }
  state.call.keypadOpen = typeof forceValue === "boolean" ? forceValue : !state.call.keypadOpen;
  renderCallState();
}

function appendCallKeypadDigit(digit) {
  const safeDigit = String(digit ?? "").slice(0, 1);
  if (!safeDigit || state.call.status === "idle") {
    return;
  }
  state.call.keypadDigits = `${String(state.call.keypadDigits ?? "")}${safeDigit}`.slice(-24);
  if (!state.call.controlsExpanded) {
    state.call.controlsExpanded = true;
  }
  if (!state.call.keypadOpen) {
    state.call.keypadOpen = true;
  }
  renderCallState();
}

async function addParticipantToCallChat() {
  const callChat = getCallChat();
  if (!callChat || !isGroupCallChat(callChat) || !canInviteMembers(callChat)) {
    return;
  }
  const options = getManageMemberContactOptions(callChat);
  if (!options.length) {
    alert(t("noContacts"));
    return;
  }
  const memberId = await selectDialog({
    title: t("callAddParticipant"),
    options,
    submitText: t("addMember"),
  });
  if (!memberId) {
    return;
  }
  await addChatMemberWithBotFallback(callChat.id, { memberId }, { forceBots: false });
  await loadChats(callChat.id, true);
  const picked = options.find((entry) => entry.value === memberId);
  showInAppNotification({
    title: picked?.label ?? t("callAddParticipant"),
    body: t("callParticipantInvited"),
    chatId: callChat.id,
  });
}

function canUseAudioCalls() {
  return Boolean(window.RTCPeerConnection && navigator.mediaDevices?.getUserMedia);
}

function isTestCallSession(sessionId = state.call.sessionId) {
  return String(sessionId ?? "").startsWith("test-");
}

function normalizeIceServerEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }

  const urls = Array.isArray(entry.urls) ? entry.urls : entry.urls ? [entry.urls] : [];
  const normalizedUrls = urls
    .map((url) => String(url ?? "").trim())
    .filter(Boolean);
  if (!normalizedUrls.length) {
    return null;
  }

  const normalized = {
    urls: [...new Set(normalizedUrls)],
  };
  const username = String(entry.username ?? "").trim();
  const credential = String(entry.credential ?? "").trim();
  if (username && credential) {
    normalized.username = username;
    normalized.credential = credential;
  }
  return normalized;
}

function mergeIceServers(primary = [], fallback = []) {
  const merged = [];
  const seen = new Set();

  const pushUnique = (entry) => {
    const normalized = normalizeIceServerEntry(entry);
    if (!normalized) {
      return;
    }
    const key = `${normalized.urls.join("|")}::${normalized.username ?? ""}::${normalized.credential ?? ""}`;
    if (seen.has(key)) {
      return;
    }
    seen.add(key);
    merged.push(normalized);
  };

  for (const entry of primary) {
    pushUnique(entry);
  }
  for (const entry of fallback) {
    pushUnique(entry);
  }
  return merged;
}

function getRtcConfig() {
  const configured = Array.isArray(state.webrtcConfig?.iceServers) ? state.webrtcConfig.iceServers : [];
  const iceServers = mergeIceServers(configured, FALLBACK_ICE_SERVERS);
  return {
    iceServers: iceServers.length ? iceServers : FALLBACK_ICE_SERVERS,
    iceCandidatePoolSize: 8,
  };
}

function getChatSettings(chat) {
  return {
    allowMemberInvites: Boolean(chat?.settings?.allowMemberInvites),
    reactionsEnabled: chat?.settings?.reactionsEnabled !== false,
    commentsEnabled: chat?.settings?.commentsEnabled !== false,
    hideParticipants: Boolean(chat?.settings?.hideParticipants),
  };
}

function getChatSettingsFull(chat) {
  const permissions = chat?.settings?.permissions ?? {};
  const media = permissions.media ?? {};
  const wallpaperPresetRaw = String(chat?.settings?.wallpaperPreset ?? "");
  const wallpaperPreset = wallpaperPresetRaw === "none" ? "" : wallpaperPresetRaw;
  return {
    allowMemberInvites: Boolean(chat?.settings?.allowMemberInvites),
    reactionsEnabled: chat?.settings?.reactionsEnabled !== false,
    commentsEnabled: chat?.settings?.commentsEnabled !== false,
    hideParticipants: Boolean(chat?.settings?.hideParticipants),
    allowedReactions: Array.isArray(chat?.settings?.allowedReactions)
      ? [...new Set(chat.settings.allowedReactions.map((entry) => String(entry ?? "").trim()).filter(Boolean))]
      : [],
    topicsEnabled: Boolean(chat?.settings?.topicsEnabled),
    topicDisplayMode: String(chat?.settings?.topicDisplayMode ?? "sidebar"),
    autoDeleteDays: Math.max(0, Math.min(365, Number.parseInt(chat?.settings?.autoDeleteDays ?? 0, 10) || 0)),
    joinRequestsEnabled: Boolean(chat?.settings?.joinRequestsEnabled),
    signMessages: Boolean(chat?.settings?.signMessages),
    restrictContentSaving: Boolean(chat?.settings?.restrictContentSaving),
    stylePreset: String(chat?.settings?.stylePreset ?? "blue"),
    wallpaperPreset,
    wallpaper: String(chat?.settings?.wallpaper ?? ""),
    wallpaperBlur: Math.max(0, Math.min(100, Number.parseInt(chat?.settings?.wallpaperBlur ?? 0, 10) || 0)),
    wallpaperDim: Math.max(0, Math.min(100, Number.parseInt(chat?.settings?.wallpaperDim ?? 0, 10) || 0)),
    permissions: {
      sendMessages: permissions.sendMessages !== false,
      addMembers: permissions.addMembers !== false,
      pinMessages: Boolean(permissions.pinMessages),
      changeChatProfile: Boolean(permissions.changeChatProfile),
      slowModeSeconds: Math.max(0, Number.parseInt(permissions.slowModeSeconds ?? 0, 10) || 0),
      media: {
        photos: media.photos !== false,
        videos: media.videos !== false,
        files: media.files !== false,
        stickersGifs: media.stickersGifs !== false,
        polls: media.polls !== false,
      },
    },
  };
}

