function renderEntityChatWallpaperSection(chat) {
  if (!elements.entityPanelBody || !chat) {
    return;
  }
  const settings = getChatSettingsFull(chat);
  let draft = {
    preset: settings.wallpaperPreset,
    wallpaper: settings.wallpaper,
    blur: settings.wallpaperBlur ?? 0,
    tab: settings.wallpaper ? "photos" : "presets",
    patternId: CHAT_WALLPAPER_PATTERN_PRESETS[0]?.id ?? "dots",
    patternColor: CHAT_WALLPAPER_PATTERN_DEFAULT_COLOR,
  };
  syncWallpaperPatternDraft(draft);

  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  wrap.innerHTML = `
    <div class="chat-wallpaper-tabs">
      <button type="button" class="chat-wallpaper-tab" data-wallpaper-tab="presets">${t("chatWallpaperPresets")}</button>
      <button type="button" class="chat-wallpaper-tab" data-wallpaper-tab="photos">${t("chatWallpaperPhotos")}</button>
    </div>
    <div class="chat-wallpaper-help">${localeText("1) Выберите тип фона, 2) выберите вариант, 3) нажмите «Сохранить фон».", "1) Choose wallpaper type, 2) choose variant, 3) press Save wallpaper.")}</div>
    <div id="chat-wallpaper-selected" class="chat-wallpaper-selected"></div>
    <div id="chat-wallpaper-preview" class="chat-wallpaper-preview"></div>
    <div class="chat-wallpaper-pattern-group">
      <div class="chat-wallpaper-pattern-title">${localeText("Абстрактные узоры", "Abstract patterns")}</div>
      <div id="chat-wallpaper-patterns" class="chat-wallpaper-grid chat-wallpaper-pattern-grid"></div>
      <label for="chat-wallpaper-color">${localeText("Цвет узора", "Pattern color")}</label>
      <div class="chat-wallpaper-color-row">
        <div id="chat-wallpaper-color-swatches" class="chat-wallpaper-color-swatches"></div>
        <input id="chat-wallpaper-color" class="chat-wallpaper-color-input" type="color" value="${escapeHtml(draft.patternColor)}" />
      </div>
      <div class="hint">${localeText("Сначала выберите узор, затем цвет.", "Pick a pattern, then choose a color.")}</div>
    </div>
    <div id="chat-wallpaper-presets" class="chat-wallpaper-grid"></div>
    <div id="chat-wallpaper-photos" class="chat-wallpaper-photos hidden">
      <button type="button" id="chat-wallpaper-upload-btn" class="small">${t("chatWallpaperUpload")}</button>
      <input id="chat-wallpaper-upload-input" type="file" accept="image/*" class="hidden-input" />
    </div>
    <label>${t("chatWallpaperBlur")}</label>
    <input id="chat-wallpaper-blur" type="range" min="0" max="100" step="5" />
    <label class="settings-switch-row">
      <span class="settings-switch-main"><span class="svg-icon" data-svg-icon="image"></span><span>${t("chatWallpaperApplyAll")}</span></span>
      <input id="chat-wallpaper-apply-all" class="settings-switch-input" type="checkbox" />
    </label>
    <div class="settings-section-actions">
      <button type="button" id="chat-wallpaper-reset-btn" class="small ghost">${t("chatWallpaperReset")}</button>
      <button type="button" id="chat-wallpaper-save-btn" class="small">${t("chatWallpaperSave")}</button>
    </div>
  `;

  elements.entityPanelTitle.textContent = t("chatWallpaper");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
  renderSvgIcons(elements.entityPanelBody);

  const preview = wrap.querySelector("#chat-wallpaper-preview");
  const selectedNode = wrap.querySelector("#chat-wallpaper-selected");
  const patternGroup = wrap.querySelector(".chat-wallpaper-pattern-group");
  const patternWrap = wrap.querySelector("#chat-wallpaper-patterns");
  const colorSwatchesWrap = wrap.querySelector("#chat-wallpaper-color-swatches");
  const colorInput = wrap.querySelector("#chat-wallpaper-color");
  const presetsWrap = wrap.querySelector("#chat-wallpaper-presets");
  const photosWrap = wrap.querySelector("#chat-wallpaper-photos");
  const blurInput = wrap.querySelector("#chat-wallpaper-blur");
  const applyAllToggle = wrap.querySelector("#chat-wallpaper-apply-all");

  const updatePreview = () => {
    updateWallpaperPreviewNode(preview, draft);
    if (selectedNode) {
      selectedNode.textContent = getWallpaperSelectionText(draft);
    }
  };

  const setTab = (nextTab) => {
    draft.tab = nextTab;
    wrap.querySelectorAll(".chat-wallpaper-tab").forEach((button) => {
      button.classList.toggle("active", button.dataset.wallpaperTab === nextTab);
    });
    patternGroup?.classList.toggle("hidden", nextTab !== "presets");
    presetsWrap?.classList.toggle("hidden", nextTab !== "presets");
    photosWrap?.classList.toggle("hidden", nextTab !== "photos");
  };

  wrap.querySelectorAll(".chat-wallpaper-tab").forEach((button) => {
    button.addEventListener("click", () => {
      const tab = button.dataset.wallpaperTab === "photos" ? "photos" : "presets";
      setTab(tab);
      syncWallpaperPicker();
      updatePreview();
    });
  });

  const syncWallpaperPicker = mountWallpaperPatternPicker({
    draft,
    patternWrap,
    presetsWrap,
    colorSwatchesWrap,
    colorInput,
    setTab,
    updatePreview,
  });

  for (const preset of CHAT_WALLPAPER_PRESETS) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "chat-wallpaper-item";
    button.dataset.preset = preset.id;
    button.dataset.label = preset.label;
    button.title = preset.label;
    button.style.backgroundImage = preset.style;
    button.addEventListener("click", () => {
      draft.preset = preset.id;
      draft.wallpaper = "";
      setTab("presets");
      syncWallpaperPicker();
      updatePreview();
    });
    presetsWrap?.appendChild(button);
  }
  syncWallpaperPicker();

  const uploadBtn = wrap.querySelector("#chat-wallpaper-upload-btn");
  const uploadInput = wrap.querySelector("#chat-wallpaper-upload-input");
  uploadBtn?.addEventListener("click", () => {
    uploadInput?.click();
  });
  uploadInput?.addEventListener("change", () => {
    const file = uploadInput.files?.[0];
    uploadInput.value = "";
    if (!file) {
      return;
    }
    prepareWallpaperDataUrlFromFile(file, {
      maxBytes: WALLPAPER_UPLOAD_MAX_BYTES,
      maxDimension: WALLPAPER_MAX_DIMENSION,
    })
      .then((wallpaperData) => {
        draft.wallpaper = wallpaperData || "";
        draft.preset = "";
        setTab("photos");
        syncWallpaperPicker();
        updatePreview();
      })
      .catch((error) => {
        alert(error?.message ?? localeText("Не удалось загрузить фото.", "Failed to load photo."));
      });
  });

  if (blurInput) {
    blurInput.value = String(draft.blur ?? 0);
    blurInput.addEventListener("input", () => {
      draft.blur = Number.parseInt(blurInput.value, 10) || 0;
    });
  }
  wrap.querySelector("#chat-wallpaper-reset-btn")?.addEventListener("click", () => {
    draft.preset = "";
    draft.wallpaper = "";
    draft.blur = 0;
    draft.tab = "presets";
    draft.patternId = CHAT_WALLPAPER_PATTERN_PRESETS[0]?.id ?? "dots";
    draft.patternColor = CHAT_WALLPAPER_PATTERN_DEFAULT_COLOR;
    if (blurInput) blurInput.value = "0";
    setTab("presets");
    syncWallpaperPicker();
    updatePreview();
  });

  wrap.querySelector("#chat-wallpaper-save-btn")?.addEventListener("click", async () => {
    try {
      const settingsPatch = {
        wallpaper: draft.wallpaper || "",
        wallpaperBlur: Math.max(0, Math.min(100, Number.parseInt(draft.blur, 10) || 0)),
        wallpaperDim: 0,
      };
      if (draft.preset) {
        settingsPatch.wallpaperPreset = draft.preset;
      } else if (!draft.wallpaper) {
        settingsPatch.wallpaperPreset = "none";
      }
      await saveEntityChatPatch(chat, {
        settings: settingsPatch,
      }, "chat-wallpaper");

      if (applyAllToggle?.checked) {
        state.settings = state.settings ?? {};
        state.settings.appearance = {
          ...(state.settings.appearance ?? {}),
          globalWallpaperPreset: draft.preset || "",
          globalWallpaper: draft.wallpaper || "",
          globalWallpaperBlur: Math.max(0, Math.min(100, Number.parseInt(draft.blur, 10) || 0)),
          globalWallpaperDim: 0,
          syncWallpaperAcrossChats: true,
        };
        await saveSettingsPayloadSilently();
      }

      renderActiveChat();
      renderMessages({ keepScrollPosition: true });
    } catch (error) {
      alert(error.message);
    }
  });

  setTab(draft.tab);
  updatePreview();
}

function renderEntityManagementPermissions(chat) {
  if (!elements.entityPanelBody) {
    return;
  }
  const settings = getChatSettingsFull(chat);
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  const rows = [
    { id: "entity-permission-send-messages", icon: "chat", label: t("entityPermissionSendMessages"), checked: settings.permissions.sendMessages },
    { id: "entity-permission-add-members", icon: "users", label: t("entityPermissionAddMembers"), checked: settings.permissions.addMembers },
    { id: "entity-permission-pin-messages", icon: "pin", label: t("entityPermissionPinMessages"), checked: settings.permissions.pinMessages },
    { id: "entity-permission-change-info", icon: "edit", label: t("entityPermissionChangeInfo"), checked: settings.permissions.changeChatProfile },
    { id: "entity-permission-photo", icon: "image", label: t("entityPermissionMediaPhotos"), checked: settings.permissions.media.photos },
    { id: "entity-permission-video", icon: "video", label: t("entityPermissionMediaVideos"), checked: settings.permissions.media.videos },
    { id: "entity-permission-file", icon: "file", label: t("entityPermissionMediaFiles"), checked: settings.permissions.media.files },
    { id: "entity-permission-stickers", icon: "emoji", label: t("entityPermissionMediaStickers"), checked: settings.permissions.media.stickersGifs },
    { id: "entity-permission-polls", icon: "activity", label: t("entityPermissionMediaPolls"), checked: settings.permissions.media.polls },
  ];

  const form = document.createElement("form");
  form.id = "entity-manage-permissions-form";
  form.className = "settings-section-form";
  for (const rowData of rows) {
    form.appendChild(createSettingsSwitchRow({ id: rowData.id, icon: rowData.icon, label: rowData.label, checked: rowData.checked }));
  }
  const actions = document.createElement("div");
  actions.className = "settings-section-actions";
  actions.innerHTML = `<button type="submit" class="small">${t("saveSettings")}</button>`;
  form.appendChild(actions);
  wrap.appendChild(form);

  elements.entityPanelTitle.textContent = getEntityPanelSectionTitle(chat, "manage-permissions");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
  renderSvgIcons(elements.entityPanelBody);

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      await saveEntityChatPatch(chat, {
        settings: {
          permissions: {
            sendMessages: Boolean(form.querySelector("#entity-permission-send-messages")?.checked),
            addMembers: Boolean(form.querySelector("#entity-permission-add-members")?.checked),
            pinMessages: Boolean(form.querySelector("#entity-permission-pin-messages")?.checked),
            changeChatProfile: Boolean(form.querySelector("#entity-permission-change-info")?.checked),
            media: {
              photos: Boolean(form.querySelector("#entity-permission-photo")?.checked),
              videos: Boolean(form.querySelector("#entity-permission-video")?.checked),
              files: Boolean(form.querySelector("#entity-permission-file")?.checked),
              stickersGifs: Boolean(form.querySelector("#entity-permission-stickers")?.checked),
              polls: Boolean(form.querySelector("#entity-permission-polls")?.checked),
            },
          },
        },
      }, "manage-permissions");
    } catch (error) {
      alert(error.message);
    }
  });
}

