function renderEntityManagementAdmins(chat) {
  if (!elements.entityPanelBody) {
    return;
  }
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.className = "small ghost";
  addBtn.id = "entity-add-admin-btn";
  addBtn.textContent = localeText("Добавить администратора", "Add Admin");
  addBtn.addEventListener("click", async () => {
    if (chat.myRole !== "owner") {
      return;
    }
    const candidates = (chat.members ?? []).filter((member) => member.userId !== state.user?.id && member.role !== "owner");
    if (!candidates.length) {
      alert(localeText("Нет доступных участников", "No eligible members"));
      return;
    }
    const selected = await selectDialog({
      title: localeText("Добавить администратора", "Add Admin"),
      options: candidates.map((member) => ({
        value: member.userId,
        label: `${getUserDisplayName(member)}${member.role === "admin" ? ` (${localeText("админ", "admin")})` : ""}`,
      })),
      submitText: localeText("Выбрать", "Select"),
    });
    if (!selected) {
      return;
    }
    try {
      await api(`/api/chats/${chat.id}/members/${selected}`, {
        method: "PATCH",
        body: { role: "admin" },
      });
      await loadChats(chat.id, true);
      await openActiveEntityPanel();
    } catch (error) {
      alert(error.message);
    }
  });
  wrap.appendChild(addBtn);
  const list = document.createElement("div");
  list.className = "member-list";

  for (const member of chat.members ?? []) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "member-item member-item-button";
    const avatar = document.createElement("div");
    avatar.className = "settings-privacy-user-avatar avatar";
    applyAvatarNode(avatar, getUserDisplayName(member), member.avatar ?? "", "Y");
    const title = document.createElement("div");
    title.className = "member-title";
    title.innerHTML = `
      <strong>${escapeHtml(getUserDisplayName(member))}</strong>
      <span class="hint">@${escapeHtml(member.username || "")} · ${escapeHtml(member.role === "owner" ? localeText("владелец", "owner") : member.role === "admin" ? localeText("админ", "admin") : localeText("участник", "member"))}</span>
    `;
    const indicator = document.createElement("span");
    indicator.className = "settings-home-btn-value";
    indicator.textContent = member.role === "owner" ? localeText("Владелец", "Owner") : member.role === "admin" ? localeText("Админ", "Admin") : "";
    row.append(avatar, title, indicator);
    row.addEventListener("click", async () => {
      await openEntityMemberActions(chat, member);
    });
    list.appendChild(row);
  }

  wrap.appendChild(list);
  elements.entityPanelTitle.textContent = getEntityPanelSectionTitle(chat, "manage-admins");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
  renderSvgIcons(elements.entityPanelBody);
}

function renderEntityManagementMembers(chat) {
  if (!elements.entityPanelBody) {
    return;
  }
  const isChannel = chat.type === "channel";
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  const toolbar = document.createElement("div");
  toolbar.className = "settings-section-actions";
  const search = document.createElement("input");
  search.id = "entity-members-search";
  search.placeholder = localeText("Поиск участников", "Search members");
  toolbar.appendChild(search);
  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.id = isChannel ? "entity-add-subscriber-btn" : "entity-add-member-btn";
  addBtn.className = "small ghost";
  addBtn.textContent = isChannel ? t("entityAddSubscribers") : t("entityAddMembers");
  addBtn.addEventListener("click", async () => {
    closeEntityPanel();
    await openChatAddFlow(chat, "members");
  });
  toolbar.appendChild(addBtn);
  wrap.appendChild(toolbar);

  const list = document.createElement("div");
  list.className = "member-list";
  const renderList = () => {
    list.innerHTML = "";
    const query = String(search.value ?? "").trim().toLowerCase();
    const members = (chat.members ?? []).filter((member) => {
      if (!query) {
        return true;
      }
      const haystack = `${getUserDisplayName(member)} ${member.username ?? ""} ${member.role ?? ""}`.toLowerCase();
      return haystack.includes(query);
    });
    for (const member of members) {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "member-item member-item-button";
      const avatar = document.createElement("div");
      avatar.className = "settings-privacy-user-avatar avatar";
      applyAvatarNode(avatar, getUserDisplayName(member), member.avatar ?? "", "Y");
      const title = document.createElement("div");
      title.className = "member-title";
      title.innerHTML = `
        <strong>${escapeHtml(getUserDisplayName(member))}</strong>
        <span class="hint">@${escapeHtml(member.username || "")} · ${escapeHtml(member.role === "owner" ? localeText("владелец", "owner") : member.role === "admin" ? localeText("админ", "admin") : isChannel ? localeText("подписчик", "subscriber") : localeText("участник", "member"))}</span>
      `;
      const chevron = document.createElement("span");
      chevron.className = "settings-home-btn-value";
      chevron.textContent = "›";
      row.append(avatar, title, chevron);
      row.addEventListener("click", async () => {
        await openEntityMemberActions(chat, member);
      });
      list.appendChild(row);
    }
  };
  search.addEventListener("input", renderList);
  renderList();
  wrap.appendChild(list);
  elements.entityPanelTitle.textContent = getEntityPanelSectionTitle(chat, "manage-members");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
  renderSvgIcons(elements.entityPanelBody);
}

function renderEntityManagementBlacklist(chat) {
  if (!elements.entityPanelBody) {
    return;
  }
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.className = "small ghost";
  addBtn.id = "entity-blacklist-add-btn";
  addBtn.textContent = localeText("Добавить в черный список", "Add to Blacklist");
  addBtn.addEventListener("click", async () => {
    const candidates = (chat.members ?? []).filter((member) => member.role !== "owner" && member.userId !== state.user?.id);
    if (!candidates.length) {
      alert(localeText("Нет доступных участников", "No eligible members"));
      return;
    }
    const selected = await selectDialog({
      title: localeText("Добавить в черный список", "Add to Blacklist"),
      options: candidates.map((member) => ({ value: member.userId, label: getUserDisplayName(member) })),
      submitText: localeText("Заблокировать", "Ban"),
    });
    if (!selected) {
      return;
    }
    try {
      await api(`/api/chats/${chat.id}/moderation/bans`, {
        method: "POST",
        body: {
          userId: selected,
          reason: "Banned by chat admin",
        },
      });
      setChatBlacklist(chat.id, [...new Set([...getChatBlacklist(chat.id), selected])]);
      await loadChats(chat.id, true);
      await openActiveEntityPanel();
    } catch (error) {
      alert(error.message);
    }
  });
  wrap.appendChild(addBtn);
  const list = document.createElement("div");
  list.className = "member-list";
  const blacklist = getChatBlacklist(chat.id);
  const blockedUsers = blacklist.map((userId) => findKnownUserById(userId)).filter(Boolean);

  if (!blockedUsers.length) {
    const hint = document.createElement("div");
    hint.className = "hint";
    hint.textContent = t("entityNoBlockedMembers");
    wrap.appendChild(hint);
  } else {
    for (const user of blockedUsers) {
      const row = document.createElement("div");
      row.className = "member-item";
      const avatar = document.createElement("div");
      avatar.className = "settings-privacy-user-avatar avatar";
      applyAvatarNode(avatar, getUserDisplayName(user), user.avatar ?? "", "Y");
      row.appendChild(avatar);
      const title = document.createElement("div");
      title.className = "member-title";
      title.innerHTML = `
        <strong>${escapeHtml(getUserDisplayName(user))}</strong>
        <span class="hint">@${escapeHtml(user.username || "")}</span>
      `;
      row.appendChild(title);
      const unblockBtn = document.createElement("button");
      unblockBtn.type = "button";
      unblockBtn.className = "small ghost";
      unblockBtn.textContent = t("entityUnblockMember");
      unblockBtn.addEventListener("click", async () => {
        try {
          await api(`/api/chats/${chat.id}/moderation/bans/${user.id}`, { method: "DELETE" });
        } catch {
          // Fall back to local cleanup even if remote sync fails.
        }
        setChatBlacklist(chat.id, blacklist.filter((entry) => entry !== user.id));
        await loadChats(chat.id, true);
        await openActiveEntityPanel();
      });
      row.appendChild(unblockBtn);
      list.appendChild(row);
    }
    wrap.appendChild(list);
  }
  elements.entityPanelTitle.textContent = getEntityPanelSectionTitle(chat, "manage-blacklist");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
}

