function renderEntityChatNotificationsSection(chat) {
  if (!elements.entityPanelBody || !chat) {
    return false;
  }
  const config = getChatNotificationConfig(chat.id);
  const wrap = document.createElement("div");
  wrap.className = "settings-section-body entity-manage-screen";
  wrap.innerHTML = `
    <div class="settings-privacy-subsection">
      <label class="settings-switch-row">
        <span class="settings-switch-main"><span class="svg-icon" data-svg-icon="alert"></span><span>${t("notificationsAndSounds")}</span></span>
        <input id="entity-chat-notify-enabled" class="settings-switch-input" type="checkbox" ${config.enabled ? "checked" : ""} />
      </label>
      <button type="button" id="entity-chat-notify-sound-btn" class="settings-privacy-row">
        <span class="settings-privacy-row-main"><span>${t("chatNotificationSound")}</span></span>
        <span class="settings-privacy-row-value">${escapeHtml(getNotificationSoundLabel(config.sound, { includeDefault: true, kind: "message" }))}</span>
      </button>
      <label class="settings-privacy-radio-row ${config.enabled ? "" : "disabled"}">
        <input id="entity-chat-notify-preview" type="checkbox" ${config.showPreviews ? "checked" : ""} ${config.enabled ? "" : "disabled"} />
        <span>${t("chatNotificationShowPreviews")}</span>
      </label>
      <button type="button" id="entity-chat-notify-mute-btn" class="settings-privacy-row">
        <span class="settings-privacy-row-main"><span>${t("chatNotificationMuteTimer")}</span></span>
        <span class="settings-privacy-row-value">${escapeHtml(getChatMuteUntilLabel(chat.id))}</span>
      </button>
    </div>
  `;
  elements.entityPanelTitle.textContent = t("chatNotificationSettingsTitle");
  elements.entityPanelBody.innerHTML = "";
  elements.entityPanelBody.appendChild(wrap);
  renderSvgIcons(elements.entityPanelBody);

  wrap.querySelector("#entity-chat-notify-enabled")?.addEventListener("change", () => {
    const enabled = Boolean(wrap.querySelector("#entity-chat-notify-enabled")?.checked);
    setChatNotificationsEnabled(chat.id, enabled, {
      muteUntil: enabled ? "" : "forever",
    });
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });

  wrap.querySelector("#entity-chat-notify-preview")?.addEventListener("change", () => {
    setChatNotificationConfig(chat.id, {
      showPreviews: Boolean(wrap.querySelector("#entity-chat-notify-preview")?.checked),
    });
  });

  wrap.querySelector("#entity-chat-notify-sound-btn")?.addEventListener("click", async () => {
    const selected = await selectDialog({
      title: t("chatNotificationSound"),
      value: config.sound,
      options: getNotificationSoundOptions({ includeDefault: true, kind: "message" }),
      submitText: t("saveSettings"),
    });
    if (selected === null) {
      return;
    }
    setChatNotificationConfig(chat.id, {
      sound: String(selected).trim() || "default",
    });
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });

  wrap.querySelector("#entity-chat-notify-mute-btn")?.addEventListener("click", async () => {
    const selected = await selectDialog({
      title: t("chatNotificationMuteTimer"),
      value: config.enabled ? "off" : config.muteUntil || "forever",
      options: [
        { value: "off", label: t("settingsEnabledShort") },
        { value: "1h", label: t("chatNotificationMuteHour") },
        { value: "1d", label: t("chatNotificationMuteDay") },
        { value: "1w", label: t("chatNotificationMuteWeek") },
        { value: "forever", label: t("chatNotificationMuteForever") },
      ],
      submitText: t("saveSettings"),
    });
    if (selected === null) {
      return;
    }
    if (selected === "off") {
      setChatNotificationsEnabled(chat.id, true);
    } else {
      const durations = {
        "1h": 60 * 60 * 1000,
        "1d": 24 * 60 * 60 * 1000,
        "1w": 7 * 24 * 60 * 60 * 1000,
      };
      const muteUntil =
        selected === "forever" ? "forever" : new Date(Date.now() + (durations[selected] ?? durations["1h"])).toISOString();
      setChatNotificationsEnabled(chat.id, false, { muteUntil });
    }
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });
  return true;
}

function buildAvatarBadge(userLike) {
  const node = document.createElement("div");
  node.className = "avatar avatar-large";
  const title = getUserDisplayName(userLike);
  applyAvatarNode(node, title, userLike?.avatar, "Y");
  return node;
}

function findKnownUserById(userId) {
  const safeUserId = String(userId ?? "").trim();
  if (!safeUserId) {
    return null;
  }

  if (state.user?.id === safeUserId) {
    return {
      id: state.user.id,
      chatId: state.user.chatId,
      username: state.user.username,
      displayName: state.user.displayName,
      about: state.user.about ?? "",
      avatar: state.user.avatar ?? "",
      isPremium: Boolean(state.user.isPremium),
      premiumBadge: state.user.premiumBadge ?? null,
      isSelf: true,
    };
  }

  const messageUser = state.currentMessages.find((entry) => entry.sender?.id === safeUserId)?.sender;
  if (messageUser) {
    return {
      ...messageUser,
      id: messageUser.id,
      chatId: messageUser.chatId,
      username: messageUser.username,
      displayName: messageUser.displayName,
      about: messageUser.about ?? "",
      avatar: messageUser.avatar ?? "",
      isPremium: Boolean(messageUser.isPremium),
      premiumBadge: messageUser.premiumBadge ?? null,
      isSelf: false,
    };
  }

  for (const chat of state.chats) {
    const member = chat.members?.find((entry) => entry.userId === safeUserId);
    if (member) {
      return {
        id: member.userId,
        chatId: member.chatId,
        username: member.username,
        displayName: member.displayName,
        about: member.about ?? "",
        avatar: member.avatar ?? "",
        isPremium: Boolean(member.isPremium),
        premiumBadge: member.premiumBadge ?? null,
        isSelf: false,
      };
    }
  }

  return null;
}

async function renderUserEntityPanel(userLike) {
  if (!userLike || !elements.entityPanel) {
    return;
  }

  resetEntityPanelNavigation();
  elements.entityPanel.classList.remove("entity-chat-info-mode");
  elements.entityPanel.dataset.entityKind = "user";
  elements.entityPanelTitle.textContent = t("profileUserTitle");
  const safeUserId = userLike.id ?? userLike.userId;
  const safeDisplayName = getUserDisplayName({ id: safeUserId, displayName: userLike.displayName });
  const safeUsername = String(userLike.username ?? "").trim();
  const activeChatId = state.activeChatId;
  const bot = isBotUser(userLike);
  const online = bot ? false : isMemberOnline(activeChatId, safeUserId);
  const lastSeenAt = bot ? null : getMemberLastActivityAt(activeChatId, safeUserId);
  const statusLabel = bot ? t("botStatus") : online ? t("onlineNow") : formatRelativeTime(lastSeenAt);
  const hiddenContact = isContactHidden(safeUserId);
  const secretChat = findSecretChatByUserId(safeUserId);
  const secretChatActive = Boolean(secretChat);
  const secretTimerLabel = secretChat ? formatSecretTimerLabel(getSecretChatTimer(secretChat.id)) : t("secretChatTimerOff");

  const card = document.createElement("div");
  card.className = "profile-tg-card entity-profile-card";

  const cover = document.createElement("div");
  cover.className = "profile-tg-cover";
  card.appendChild(cover);

  const hero = document.createElement("div");
  hero.className = "profile-modern-head profile-tg-head";

  const avatarWrap = document.createElement("div");
  avatarWrap.className = "profile-avatar-editor";
  const heroAvatar = buildAvatarBadge({
    id: safeUserId,
    displayName: safeDisplayName,
    avatar: userLike.avatar ?? "",
  });
  heroAvatar.classList.add("entity-profile-avatar");
  avatarWrap.appendChild(heroAvatar);
  hero.appendChild(avatarWrap);

  const heroMeta = document.createElement("div");
  heroMeta.className = "profile-modern-meta";
  const nameNode = document.createElement("div");
  nameNode.className = "profile-modern-name";
  renderNameWithPremiumBadge(nameNode, safeDisplayName, userLike, { ellipsis: false });
  const statusNode = document.createElement("div");
  statusNode.className = "hint";
  statusNode.textContent = isPremiumUserLike(userLike) ? `${statusLabel} · ${t("settingsPremiumInfo")}` : statusLabel;
  const usernameNode = document.createElement("div");
  usernameNode.className = "profile-modern-username";
  usernameNode.textContent = safeUsername ? `@${safeUsername}` : "@";
  heroMeta.appendChild(nameNode);
  heroMeta.appendChild(statusNode);
  heroMeta.appendChild(usernameNode);
  hero.appendChild(heroMeta);
  card.appendChild(hero);

  const details = document.createElement("div");
  details.className = "profile-tg-info";
  const rows = [
    { label: t("usernameField"), value: safeUsername ? `@${safeUsername}` : "-" },
    { label: t("chatIdField"), value: String(userLike.chatId ?? "-") },
    { label: t("profileDescription"), value: String(userLike.about || "-") },
  ];
  if (secretChatActive) {
    rows.push(
      { label: t("secretChat"), value: t("secretChatEnabled") },
      { label: t("secretChatTimer"), value: secretTimerLabel },
    );
  }
  for (const row of rows) {
    const rowNode = document.createElement("div");
    rowNode.className = "profile-tg-static-row";
    const labelNode = document.createElement("span");
    labelNode.textContent = row.label;
    const valueNode = document.createElement("strong");
    valueNode.textContent = row.value;
    rowNode.appendChild(labelNode);
    rowNode.appendChild(valueNode);
    details.appendChild(rowNode);
  }
  card.appendChild(details);

  const actions = document.createElement("div");
  actions.className = "profile-tg-quick-actions entity-profile-actions";

  const createQuickActionButton = (icon, label, className = "small ghost") => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `${className} entity-quick-action`;
    button.innerHTML = `
      <span class="svg-icon" data-svg-icon="${icon}"></span>
      <span>${escapeHtml(label)}</span>
    `;
    return button;
  };

  const sendBtn = createQuickActionButton("chat", t("sendMessageAction"), "small");
  sendBtn.addEventListener("click", async () => {
    const ensuredChat = await ensureDirectChatWithUser(userLike);
    if (!ensuredChat?.id) {
      return;
    }
    await openChat(ensuredChat.id, false);
    closeEntityPanel();
  });
  actions.appendChild(sendBtn);

  const wallpaperBtn = createQuickActionButton("image", t("chatWallpaper"), "small ghost");
  wallpaperBtn.addEventListener("click", async () => {
    const ensuredChat = await ensureDirectChatWithUser(userLike);
    if (!ensuredChat?.id) {
      return;
    }
    await openChat(ensuredChat.id, false);
    openEntityPanelSection("chat-wallpaper");
    await openActiveEntityPanel();
  });
  actions.appendChild(wallpaperBtn);

  if (!bot) {
    const callBtn = createQuickActionButton("phone", t("callStart"), "small ghost");
    callBtn.addEventListener("click", async () => {
      const targetChat = await ensureDirectChatWithUser(userLike);
      if (targetChat?.id) {
        await openChat(targetChat.id, false);
      }
      closeEntityPanel();
      await startCall();
    });
    actions.appendChild(callBtn);

    const videoBtn = createQuickActionButton("video", t("callStartVideo"), "small ghost");
    videoBtn.addEventListener("click", async () => {
      const targetChat = await ensureDirectChatWithUser(userLike);
      if (targetChat?.id) {
        await openChat(targetChat.id, false);
      }
      closeEntityPanel();
      await startCall("video");
    });
    actions.appendChild(videoBtn);

    const secretBtn = createQuickActionButton(
      "lock",
      secretChatActive ? t("secretChatEnabled") : t("startSecretChat"),
      "small ghost",
    );
    secretBtn.id = "entity-start-secret-chat-btn";
    secretBtn.disabled = secretChatActive;
    secretBtn.addEventListener("click", async () => {
      const ensuredChat = await ensureSecretChatWithUser(userLike);
      if (!ensuredChat?.id) {
        return;
      }
      await openChat(ensuredChat.id, false);
    });
    actions.appendChild(secretBtn);

    if (secretChatActive && secretChat?.id) {
      const timerBtn = createQuickActionButton("clock", `${t("secretChatTimer")}: ${secretTimerLabel}`, "small ghost");
      timerBtn.id = "entity-secret-timer-btn";
      timerBtn.addEventListener("click", async () => {
        await promptSecretChatTimer(secretChat.id);
        renderActiveChat();
        renderMessages({ keepScrollPosition: true });
        await renderUserEntityPanel(userLike);
      });
      actions.appendChild(timerBtn);
    }
  }

  const contactBtn = createQuickActionButton("contact", hiddenContact ? t("addToContacts") : t("removeFromContacts"), "small ghost");
  contactBtn.addEventListener("click", async () => {
    setContactHidden(safeUserId, !hiddenContact);
    renderContacts();
    await renderUserEntityPanel(userLike);
  });
  actions.appendChild(contactBtn);

  const reportBtn = createQuickActionButton("alert", t("report"), "small ghost danger");
  reportBtn.addEventListener("click", async () => {
    const targetMessage = [...state.currentMessages].reverse().find((entry) => entry.sender?.id === safeUserId);
    if (!targetMessage) {
      alert(t("noReportMessages"));
      return;
    }

    const reason = await promptDialog({
      title: t("report"),
      message: t("reportReasonPrompt"),
      value: t("reportReasonDefault"),
      submitText: t("report"),
    });
    if (reason === null) {
      return;
    }

    await api(`/api/chats/${state.activeChatId}/messages/${targetMessage.id}/report`, {
      method: "POST",
      body: { reason: reason.trim() || t("reportReasonFallback") },
    });
  });
  actions.appendChild(reportBtn);

  card.appendChild(actions);
  elements.entityPanelBody.innerHTML = "";
  syncSidebarResizerInteractivity();
  elements.entityPanelBody.appendChild(card);
  renderSvgIcons(card);
  elements.entityPanel.classList.remove("hidden");
  syncEntityPanelHeader();
  syncSidebarResizerInteractivity();
}

async function openUserEntityPanel(userId) {
  const knownUser = findKnownUserById(userId);
  if (!knownUser) {
    return;
  }

  if (knownUser.isSelf) {
    openMyProfilePanel();
    return;
  }

  await renderUserEntityPanel({
    id: knownUser.id,
    chatId: knownUser.chatId,
    username: knownUser.username,
    displayName: knownUser.displayName,
    about: knownUser.about ?? "",
    avatar: knownUser.avatar ?? "",
    isBot: Boolean(knownUser.isBot),
    isSystemBot: Boolean(knownUser.isSystemBot),
  });
}

async function openCallPeerEntityPanel() {
  if (state.call.status === "idle") {
    return;
  }

  const selfId = String(state.user?.id ?? "").trim();
  const preferredParticipantId =
    state.call.focusParticipantId && state.call.focusParticipantId !== selfId
      ? state.call.focusParticipantId
      : state.call.peer?.id ?? getPrimaryRemoteParticipant()?.id;
  const knownUser = findKnownUserById(preferredParticipantId);
  if (knownUser) {
    await openUserEntityPanel(knownUser.id);
    return;
  }

  const callChat = state.chats.find((entry) => entry.id === state.call.chatId);
  if (!callChat) {
    return;
  }

  if (state.activeChatId !== callChat.id) {
    await openChat(callChat.id, true);
  }
  await openActiveEntityPanel();
}

async function openActiveEntityPanel() {
  const chat = getActiveChat();
  if (!chat || !elements.entityPanel) {
    return;
  }

  const preserveSection = !elements.entityPanel.classList.contains("hidden") && elements.entityPanel.dataset.entityKind === "chat";
  if (!preserveSection) {
    const requestedSection = String(state.entityPanelSection ?? "").trim();
    const keepRequestedSection = requestedSection && requestedSection !== "info";
    resetEntityPanelNavigation();
    state.entityPanelSection = keepRequestedSection ? requestedSection : "info";
  }

  elements.entityPanel.classList.remove("entity-chat-info-mode");
  elements.entityPanel.dataset.entityKind = "chat";
  elements.entityPanelBody.innerHTML = "";
  syncSidebarResizerInteractivity();

  if (chat.type === "direct") {
    if (state.entityPanelSection === "chat-wallpaper" && renderEntityManagementSection(chat)) {
      elements.entityPanel.classList.remove("hidden");
      syncEntityPanelHeader();
      syncSidebarResizerInteractivity();
      return;
    }
    const peer = getDirectPeer(chat);
    if (!peer) {
      return;
    }
    await renderUserEntityPanel({
      id: peer.userId,
      chatId: peer.chatId,
      username: peer.username,
      displayName: peer.displayName,
      about: peer.about || "",
      avatar: peer.avatar || "",
      isBot: Boolean(peer.isBot),
      isSystemBot: Boolean(peer.isSystemBot),
    });
    return;
  }

  if (state.entityPanelSection && renderEntityManagementSection(chat)) {
    elements.entityPanel.classList.remove("hidden");
    syncEntityPanelHeader();
    syncSidebarResizerInteractivity();
    return;
  }
  if (state.entityPanelSection === "chat-notifications" && renderEntityChatNotificationsSection(chat)) {
    elements.entityPanel.classList.remove("hidden");
    syncEntityPanelHeader();
    syncSidebarResizerInteractivity();
    return;
  }

  elements.entityPanel.classList.add("entity-chat-info-mode");
  const isChannel = chat.type === "channel";
  const cardTitle = isChannel ? t("entityChannelInfo") : t("entityGroupInfo");
  const memberCount = getChatMembersCount(chat);
  const roleAdmins = (chat.members ?? []).filter((entry) => ["owner", "admin"].includes(entry.role)).length;
  const notificationsEnabled = isChatNotificationsEnabled(chat.id);
  const canLeave = canLeaveChat(chat);
  const canManage = canManageChat(chat);
  const canInvite = canInviteMembers(chat);
  const showInfoShortcuts = canInvite || canManage;

  const addMembersLabel = isChannel ? t("entityAddSubscribers") : t("entityAddMembers");
  const manageLabel = isChannel ? t("entityManageChannel") : t("entityManageGroup");
  const leaveLabel = isChannel ? t("entityLeaveChannel") : t("entityLeaveGroup");
  const chatTitleText = chat.title || getChatTitle(chat);
  const memberCountLabel = `${memberCount} ${isChannel ? t("entitySubscribers") : t("members")}`;
  const groupMembersLabel = `${t("members")}: ${memberCount}`;
  const adminCountLabel = `${roleAdmins} ${t("entityAdministrators")}`;
  const descriptionHint = chat.description ? t("entityDescription") : t("entityIdShort");
  const infoValue = chat.description ? chat.description : chat.chatId ?? "-";

  elements.entityPanelTitle.textContent = cardTitle;

  const card = document.createElement("div");
  card.className = "entity-chat-info-card";
  card.innerHTML = `
    <div class="entity-chat-info-top">
      <h3 class="entity-chat-info-title">${escapeHtml(cardTitle)}</h3>
      <div class="entity-chat-info-top-actions">
        <button type="button" id="entity-chat-more-btn" class="ghost small icon-btn" data-svg-icon="more" title="${t("callsMenu")}"></button>
        <button type="button" id="entity-chat-close-btn" class="ghost small icon-btn" data-svg-icon="x" title="${t("close")}"></button>
        <div id="entity-chat-more-menu" class="entity-chat-info-more-menu hidden">
          <button type="button" id="entity-chat-auto-delete-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="clock"></span>
            <span>${t("entityAutoDelete")}</span>
          </button>
          <button type="button" id="entity-chat-add-members-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="users"></span>
            <span>${escapeHtml(addMembersLabel)}</span>
          </button>
          <button type="button" id="entity-chat-add-bots-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="star"></span>
            <span>${t("addBots")}</span>
          </button>
          <button type="button" id="entity-chat-manage-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="sliders"></span>
            <span>${escapeHtml(manageLabel)}</span>
          </button>
          <button type="button" id="entity-chat-wallpaper-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="image"></span>
            <span>${escapeHtml(t("chatWallpaper"))}</span>
          </button>
          <button type="button" id="entity-chat-folder-btn" class="small ghost">
            <span class="svg-icon" data-svg-icon="bookmark"></span>
            <span>${t("entityAddToFolder")}</span>
          </button>
          ${
            canLeave
              ? `
            <button type="button" id="entity-chat-leave-btn" class="small ghost danger">
              <span class="svg-icon" data-svg-icon="x"></span>
              <span>${escapeHtml(leaveLabel)}</span>
            </button>
          `
              : ""
          }
        </div>
      </div>
    </div>

    <div class="entity-chat-info-hero">
      <span id="entity-chat-avatar" class="avatar entity-chat-info-avatar">${getInitialSymbol(chatTitleText, "C")}</span>
      <span class="entity-chat-info-meta">
        <strong>${escapeHtml(chatTitleText)}</strong>
        <span>${escapeHtml(memberCountLabel)}</span>
      </span>
    </div>

    ${
      showInfoShortcuts
        ? `
      <div class="entity-chat-info-shortcuts">
        ${
          canInvite
            ? `<button type="button" id="entity-chat-add-members-shortcut-btn" class="small ghost">${escapeHtml(addMembersLabel)}</button>`
            : ""
        }
        ${
          canManage
            ? `<button type="button" id="entity-chat-manage-shortcut-btn" class="small ghost">${escapeHtml(manageLabel)}</button>`
            : ""
        }
      </div>
    `
        : ""
    }

    <div class="entity-chat-info-section">
      <div class="entity-chat-info-row">
        <span class="entity-chat-info-row-main">
          <span class="svg-icon" data-svg-icon="info"></span>
          <span class="hint">${escapeHtml(descriptionHint)}</span>
        </span>
        <strong>${escapeHtml(String(infoValue))}</strong>
      </div>
      <div class="entity-chat-info-row">
        <span class="entity-chat-info-row-main">
          <span class="svg-icon" data-svg-icon="alert"></span>
          <span>${t("notificationsAndSounds")}</span>
        </span>
        <span class="entity-chat-info-row-main">
          <button type="button" id="entity-chat-notifications-open-btn" class="small ghost">${escapeHtml(t("open"))}</button>
          <label class="switch">
            <input id="entity-chat-notifications-toggle" type="checkbox" ${notificationsEnabled ? "checked" : ""} />
            <span class="slider"></span>
          </label>
        </span>
      </div>
    </div>

    <div class="entity-chat-info-section">
      ${
        isChannel
          ? `
        <div class="entity-chat-info-row">
          <span class="entity-chat-info-row-main"><span class="svg-icon" data-svg-icon="users"></span><span>${escapeHtml(memberCountLabel)}</span></span>
          <button type="button" class="small ghost" id="entity-chat-add-subscriber-btn" data-svg-icon="users"></button>
        </div>
        <div class="entity-chat-info-row">
          <span class="entity-chat-info-row-main"><span class="svg-icon" data-svg-icon="star"></span><span>${escapeHtml(adminCountLabel)}</span></span>
          <button type="button" class="small ghost" id="entity-chat-admins-open-btn">${escapeHtml(t("open"))}</button>
        </div>
        <div class="entity-chat-info-row">
          <span class="entity-chat-info-row-main"><span class="svg-icon" data-svg-icon="sliders"></span><span>${t("entityChannelSettings")}</span></span>
          <button type="button" class="small ghost" id="entity-chat-settings-open-btn">${escapeHtml(t("open"))}</button>
        </div>
      `
          : `
        <div class="entity-chat-info-row">
          <span class="entity-chat-info-row-main"><span class="svg-icon" data-svg-icon="users"></span><span>${escapeHtml(groupMembersLabel)}</span></span>
          <button type="button" class="small ghost" id="entity-chat-add-members-quick-btn" data-svg-icon="users"></button>
        </div>
      `
      }
      <div id="entity-chat-members-wrap"></div>
    </div>
  `;

  elements.entityPanelBody.appendChild(card);
  renderSvgIcons(card);
  const avatar = card.querySelector("#entity-chat-avatar");
  applyAvatarNode(avatar, chatTitleText, chat.avatar ?? "", "C");
  const avatarInput = document.createElement("input");
  avatarInput.type = "file";
  avatarInput.accept = "image/*";
  avatarInput.className = "hidden-input";
  card.appendChild(avatarInput);
  if (canManage && avatar) {
    avatar.classList.add("entity-chat-info-avatar-editable");
    avatar.title = t("changeAvatar");
    avatar.addEventListener("click", () => {
      avatarInput.click();
    });
    avatarInput.addEventListener("change", async () => {
      const file = avatarInput.files?.[0];
      avatarInput.value = "";
      if (!file) {
        return;
      }
      let nextAvatar;
      try {
        nextAvatar = await openImageCropFromFile(file, {
          title: t("changeAvatar"),
          shape: "circle",
          aspect: 1,
          outputWidth: 512,
          outputHeight: 512,
        });
      } catch (error) {
        alert(error?.message || "Failed to process image");
        return;
      }
      if (!nextAvatar) {
        return;
      }
      applyAvatarNode(avatar, chatTitleText, nextAvatar, "C");
      try {
        await saveEntityChatPatch(chat, { avatar: nextAvatar }, state.entityPanelSection || "");
      } catch (error) {
        alert(error.message);
      }
    });
  }
  const addMembersBtn = card.querySelector("#entity-chat-add-members-btn");
  const addMembersQuickBtn = card.querySelector("#entity-chat-add-members-quick-btn");
  const addSubscriberBtn = card.querySelector("#entity-chat-add-subscriber-btn");
  const addBotsBtn = card.querySelector("#entity-chat-add-bots-btn");
  const manageBtn = card.querySelector("#entity-chat-manage-btn");

  addMembersBtn?.classList.toggle("hidden", !canInvite);
  addMembersQuickBtn?.classList.toggle("hidden", !canInvite);
  addSubscriberBtn?.classList.toggle("hidden", !canInvite);
  addBotsBtn?.classList.toggle("hidden", !canManage);
  manageBtn?.classList.toggle("hidden", !canManage);

  if ((chat.members ?? []).length) {
    const memberWrap = card.querySelector("#entity-chat-members-wrap");
    for (const member of (chat.members ?? []).slice(0, 8)) {
      const name = getUserDisplayName({ id: member.userId, displayName: member.displayName });
      const online = isMemberOnline(chat.id, member.userId);
      const memberStatus = isBotUser(member)
        ? t("botStatus")
        : online
          ? t("onlineNow")
          : formatRelativeTime(getMemberLastActivityAt(chat.id, member.userId));
      const node = document.createElement("button");
      node.type = "button";
      node.className = "entity-chat-info-member";
      node.innerHTML = `
        <span class="entity-chat-info-member-main">
          <span class="avatar entity-chat-info-member-avatar">${getInitialSymbol(name, "Y")}</span>
          <span class="entity-chat-info-meta">
            <strong>${escapeHtml(name)}</strong>
            <span>${escapeHtml(memberStatus)}</span>
          </span>
        </span>
        <strong>${escapeHtml(String(member.role ?? "member"))}</strong>
      `;
      const memberAvatar = node.querySelector(".entity-chat-info-member-avatar");
      applyAvatarNode(memberAvatar, name, member.avatar ?? "", "Y");
      node.addEventListener("click", async () => {
        if (canManage) {
          await openEntityMemberActions(chat, member);
          return;
        }
        await openUserEntityPanel(member.userId);
      });
      memberWrap.appendChild(node);
    }
  }

  const moreBtn = card.querySelector("#entity-chat-more-btn");
  const moreMenu = card.querySelector("#entity-chat-more-menu");

  const openAddFlow = async (mode) => {
    if (mode === "bots" && !canManage) {
      return;
    }
    if (mode !== "bots" && !canInvite) {
      return;
    }
    moreMenu?.classList.add("hidden");
    closeEntityPanel();
    try {
      await openChatAddFlow(chat, mode);
    } catch (error) {
      alert(error.message);
    }
  };

  card.querySelector("#entity-chat-close-btn")?.addEventListener("click", () => {
    closeEntityPanel();
  });

  card.querySelector("#entity-chat-notifications-toggle")?.addEventListener("change", (event) => {
    setChatNotificationsEnabled(chat.id, event.target.checked);
  });
  card.querySelector("#entity-chat-notifications-open-btn")?.addEventListener("click", () => {
    openEntityPanelSection("chat-notifications");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });
  card.querySelector("#entity-chat-admins-open-btn")?.addEventListener("click", () => {
    openEntityPanelSection("manage-admins");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });
  card.querySelector("#entity-chat-settings-open-btn")?.addEventListener("click", () => {
    openEntityPanelSection("manage-home");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });
  card.querySelector("#entity-chat-wallpaper-btn")?.addEventListener("click", () => {
    openEntityPanelSection("chat-wallpaper");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });

  moreBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (!moreMenu) {
      return;
    }
    if (!moreMenu.classList.contains("hidden")) {
      moreMenu.classList.add("hidden");
      return;
    }
    openAdaptiveFloatingMenu(moreMenu, moreBtn, {
      preferredVertical: "bottom",
      preferredHorizontal: "right",
      offset: 6,
      fallbackWidth: 230,
      fallbackHeight: 220,
      padding: 10,
    });
  });

  card.querySelector("#entity-chat-auto-delete-btn")?.addEventListener("click", async () => {
    moreMenu?.classList.add("hidden");
    const selected = await selectDialog({
      title: t("entityAutoDelete"),
      options: [
        { value: "off", label: t("settingsAutoDeleteOff") },
        { value: "1", label: t("settingsAutoDeleteDay") },
        { value: "7", label: t("settingsAutoDeleteWeek") },
        { value: "30", label: t("settingsAutoDeleteMonth") },
      ],
      value: "off",
      submitText: t("saveSettings"),
    });
    if (selected) {
      alert(`${t("entityAutoDelete")}: ${selected}`);
    }
  });

  card.querySelector("#entity-chat-manage-btn")?.addEventListener("click", () => {
    moreMenu?.classList.add("hidden");
    openEntityPanelSection("manage-home");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });

  card.querySelector("#entity-chat-folder-btn")?.addEventListener("click", () => {
    moreMenu?.classList.add("hidden");
    closeEntityPanel();
    openFoldersPanel();
  });

  card.querySelector("#entity-chat-add-members-btn")?.addEventListener("click", () => {
    openAddFlow("members");
  });

  card.querySelector("#entity-chat-add-bots-btn")?.addEventListener("click", () => {
    openAddFlow("bots");
  });

  card.querySelector("#entity-chat-add-members-quick-btn")?.addEventListener("click", () => {
    openAddFlow("members");
  });

  card.querySelector("#entity-chat-add-members-shortcut-btn")?.addEventListener("click", () => {
    openAddFlow("members");
  });

  card.querySelector("#entity-chat-add-subscriber-btn")?.addEventListener("click", () => {
    openAddFlow("members");
  });

  card.querySelector("#entity-chat-manage-shortcut-btn")?.addEventListener("click", () => {
    openEntityPanelSection("manage-home");
    openActiveEntityPanel().catch((error) => {
      alert(error.message);
    });
  });

  card.querySelector("#entity-chat-leave-btn")?.addEventListener("click", async () => {
    moreMenu?.classList.add("hidden");
    closeEntityPanel();
    elements.chatDeleteBtn?.click();
  });

  elements.entityPanel.addEventListener(
    "click",
    (event) => {
      if (!moreMenu || moreMenu.classList.contains("hidden")) {
        return;
      }
      if (!event.target.closest("#entity-chat-more-menu") && !event.target.closest("#entity-chat-more-btn")) {
        moreMenu.classList.add("hidden");
      }
    },
    { once: true },
  );

  elements.entityPanel.classList.remove("hidden");
  syncEntityPanelHeader();
  syncSidebarResizerInteractivity();
}

function saveVoiceTranscripts() {
  try {
    localStorage.setItem("yooh_voice_transcripts", JSON.stringify(state.voiceTranscripts ?? {}));
  } catch {
    // Ignore local transcript cache errors.
  }
}

function getVoiceMessageTranscript(message) {
  const key = String(message?.id ?? "").trim();
  if (!key) {
    return "";
  }
  return String(state.voiceTranscripts?.[key] ?? "").trim();
}

function buildVoiceMessageTranscript(message) {
  const sourceParts = [
    String(message?.text ?? "").trim(),
    getDisplayFileName(message?.file?.originalName ?? "").replace(/\.[a-z0-9]{2,5}$/i, "").trim(),
  ].filter(Boolean);
  const source = sourceParts[0] || t("voicePreviewTitle");
  return `${source}. ${t("voicePreviewTitle")} · ${new Date(message?.createdAt ?? Date.now()).toLocaleString(state.lang === "ru" ? "ru-RU" : "en-US")}`;
}

function buildVoiceWaveSeedHeights(seed, count = 52) {
  const safeSeed = String(seed ?? "voice");
  let hash = 2166136261;
  for (let index = 0; index < safeSeed.length; index += 1) {
    hash ^= safeSeed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
    hash >>>= 0;
  }
  const heights = [];
  for (let index = 0; index < count; index += 1) {
    hash ^= hash << 13;
    hash ^= hash >>> 17;
    hash ^= hash << 5;
    hash >>>= 0;
    const noise = (hash % 1000) / 1000;
    const arc = Math.sin(((index + 1) / (count + 1)) * Math.PI);
    const mixed = 0.18 + noise * 0.52 + arc * 0.26;
    heights.push(Math.max(0.14, Math.min(0.96, mixed)));
  }
  return heights;
}

function createAudioMessageNode(message, inlineUrl) {
  const wrapper = document.createElement("div");
  wrapper.className = "message-audio-wrap";
  wrapper.dataset.messageId = String(message.id ?? "");
  const audio = document.createElement("audio");
  audio.className = "message-audio-element";
  audio.src = inlineUrl;
  audio.preload = "metadata";
  wrapper.appendChild(audio);

  const waveSeed = `${message?.id ?? ""}|${message?.file?.id ?? ""}|${message?.createdAt ?? ""}`;
  const waveHeights = buildVoiceWaveSeedHeights(waveSeed);
  const waveMarkup = waveHeights
    .map((value, index) => `<span class="message-audio-wave-bar" style="--wave-h:${value.toFixed(3)}" data-wave-index="${index}"></span>`)
    .join("");

  const player = document.createElement("div");
  player.className = "message-audio-player";
  player.innerHTML = `
    <button type="button" class="message-audio-play-btn icon-btn" data-state="play" title="Play" data-svg-icon="play"></button>
    <div class="message-audio-content">
      <div class="message-audio-wave">${waveMarkup}</div>
      <div class="message-audio-time">
        <strong class="message-audio-current">0:00</strong>
        <span class="message-audio-size">${escapeHtml(formatBytes(Number(message?.file?.size ?? message?.file?.sizeBytes ?? 0)) || "")}</span>
        <span class="message-audio-dot" aria-hidden="true"></span>
        <span class="message-audio-duration">0:00</span>
      </div>
      <input type="range" class="message-audio-progress" min="0" max="1000" value="0" step="1" />
    </div>
  `;
  wrapper.appendChild(player);

  const playBtn = player.querySelector(".message-audio-play-btn");
  const progress = player.querySelector(".message-audio-progress");
  const currentTimeNode = player.querySelector(".message-audio-current");
  const durationNode = player.querySelector(".message-audio-duration");
  const waveBars = [...player.querySelectorAll(".message-audio-wave-bar")];

  const updatePlayState = (playing) => {
    playBtn.dataset.state = playing ? "pause" : "play";
    playBtn.dataset.svgIcon = playing ? "pause" : "play";
    playBtn.setAttribute("title", playing ? "Pause" : "Play");
    renderSvgIcons(playBtn);
  };

  const updateProgress = () => {
    const duration = Number(audio.duration);
    const currentTime = Number(audio.currentTime);
    if (currentTimeNode) {
      currentTimeNode.textContent = formatDuration(currentTime);
    }
    if (durationNode) {
      durationNode.textContent = Number.isFinite(duration) && duration > 0 ? formatDuration(duration) : "0:00";
    }
    if (progress) {
      const ratio = Number.isFinite(duration) && duration > 0 ? Math.max(0, Math.min(1, currentTime / duration)) : 0;
      progress.value = String(Math.round(ratio * 1000));
      const playedCount = Math.round(ratio * waveBars.length);
      for (let index = 0; index < waveBars.length; index += 1) {
        waveBars[index].classList.toggle("is-played", index < playedCount);
      }
    }
  };

  playBtn?.addEventListener("click", async () => {
    if (!audio.paused) {
      audio.pause();
      updatePlayState(false);
      return;
    }
    const peers = document.querySelectorAll(".message-audio-element");
    for (const peer of peers) {
      if (peer !== audio) {
        peer.pause();
      }
    }
    try {
      await audio.play();
      updatePlayState(true);
    } catch {
      updatePlayState(false);
    }
  });

  progress?.addEventListener("input", () => {
    const duration = Number(audio.duration);
    if (!Number.isFinite(duration) || duration <= 0) {
      return;
    }
    const ratio = (Number(progress.value) || 0) / 1000;
    audio.currentTime = Math.max(0, Math.min(duration, ratio * duration));
    updateProgress();
  });

  audio.addEventListener("loadedmetadata", updateProgress);
  audio.addEventListener("durationchange", updateProgress);
  audio.addEventListener("timeupdate", updateProgress);
  audio.addEventListener("play", () => updatePlayState(true));
  audio.addEventListener("pause", () => updatePlayState(false));
  audio.addEventListener("ended", () => {
    updatePlayState(false);
    updateProgress();
  });
  updatePlayState(false);
  updateProgress();

  const meta = document.createElement("div");
  meta.className = "message-audio-meta";
  const actions = document.createElement("div");
  actions.className = "message-audio-actions";

  const speedBtn = document.createElement("button");
  speedBtn.type = "button";
  speedBtn.className = "message-audio-speed-btn";
  speedBtn.dataset.messageId = String(message.id ?? "");
  speedBtn.dataset.speed = "1";
  speedBtn.textContent = "1x";
  actions.appendChild(speedBtn);

  if (isYoohPlusUser()) {
    const transcriptBtn = document.createElement("button");
    transcriptBtn.type = "button";
    transcriptBtn.className = "message-audio-transcribe-btn";
    transcriptBtn.dataset.messageId = String(message.id ?? "");
    transcriptBtn.textContent = "T";
    actions.appendChild(transcriptBtn);
  }

  meta.appendChild(actions);
  wrapper.appendChild(meta);

  const transcript = getVoiceMessageTranscript(message);
  if (transcript) {
    const transcriptNode = document.createElement("div");
    transcriptNode.className = "message-audio-transcript";
    transcriptNode.dataset.messageId = String(message.id ?? "");
    transcriptNode.textContent = transcript;
    wrapper.appendChild(transcriptNode);
  }

  renderSvgIcons(wrapper);
  return wrapper;
}

function renderMessages(options = {}) {
  const keepScrollPosition = Boolean(options?.keepScrollPosition);
  const previousScrollTop = keepScrollPosition ? Number(elements.messageList?.scrollTop ?? 0) : 0;
  const previousScrollHeight = keepScrollPosition ? Number(elements.messageList?.scrollHeight ?? 0) : 0;
  const chat = getActiveChat();
  const secretChatActive = Boolean(chat && chat.type === "direct" && isSecretChat(chat.id));
  const visibleMessages = secretChatActive
    ? state.currentMessages.filter((message) => !isSecretMessageHidden(chat.id, message.id))
    : state.currentMessages;
  const selectionActive = isMessageSelectionActive();
  elements.messageList.innerHTML = "";
  if (!visibleMessages.length) {
    const node = document.createElement("div");
    node.className = "hint";
    node.textContent = secretChatActive && state.currentMessages.length ? t("secretChatMessagesExpired") : t("noMessages");
    elements.messageList.appendChild(node);
    updatePinnedStrip();
    return;
  }

  for (const message of visibleMessages) {
    const fragment = elements.messageTemplate.content.cloneNode(true);
    const row = fragment.querySelector(".message-row");
    const node = fragment.querySelector(".message");
    const avatarNode = fragment.querySelector(".message-avatar");
    row.dataset.messageId = String(message.id ?? "");
    node.dataset.messageId = String(message.id ?? "");
    const mine = message.sender?.id === state.user?.id;
    row.classList.toggle("mine", mine);
    row.classList.toggle("selected", isMessageSelected(message.id));
    row.classList.toggle("pinned", isMessagePinned(state.activeChatId, message.id));
    row.classList.toggle("selection-mode", selectionActive);
    node.classList.toggle("mine", mine);

    const authorName = message.sender
      ? getUserDisplayName({ id: message.sender.id, displayName: message.sender.displayName })
      : t("unknownUser");
    renderNameWithPremiumBadge(fragment.querySelector(".message-author"), authorName, message.sender, { ellipsis: true });
    const messageTimeNode = fragment.querySelector(".message-time");
    const baseTime = `${formatTime(message.createdAt)}${message.editedAt ? ` • ${t("messageEdited")}` : ""}`;
    messageTimeNode.textContent = baseTime;
    if (mine) {
      const deliveryNode = createMessageDeliveryNode(message);
      if (deliveryNode) {
        messageTimeNode.append(" ", deliveryNode);
      }
    }
    avatarNode.title = authorName;
    avatarNode.dataset.userId = message.sender?.id ?? "";
    applyAvatarNode(avatarNode, authorName, message.sender?.avatar ?? "", "Y");

    const body = fragment.querySelector(".message-body");
    const actionsNode = fragment.querySelector(".message-actions");

    if (selectionActive) {
      const selectToggle = document.createElement("button");
      selectToggle.type = "button";
      selectToggle.className = "message-select-toggle";
      selectToggle.dataset.messageId = String(message.id ?? "");
      selectToggle.innerHTML = `<span class="message-select-circle"></span>`;
      selectToggle.addEventListener("click", (event) => {
        event.stopPropagation();
        toggleMessageSelection(message.id);
        renderMessages({ keepScrollPosition: true });
      });
      row.insertBefore(selectToggle, row.firstChild);
    }

    row.addEventListener("contextmenu", (event) => {
      const target = event.target;
      if (target.closest("textarea, input, select")) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      openMessageContextMenu(event.clientX, event.clientY, message.id);
    });

    let longPressTimer = null;
    let longPressStartX = 0;
    let longPressStartY = 0;
    let longPressFired = false;
    let swipeStartX = 0;
    let swipeStartY = 0;
    let swipeDx = 0;
    let swipeDy = 0;
    let swipeActive = false;
    let swipeHandled = false;
    let lastTapAt = 0;
    let lastTapX = 0;
    let lastTapY = 0;
    const clearLongPress = () => {
      if (longPressTimer) {
        clearTimeout(longPressTimer);
      }
      longPressTimer = null;
    };
    row.addEventListener("pointerdown", (event) => {
      if (selectionActive) {
        return;
      }
      if (event.pointerType === "mouse") {
        return;
      }
      if (event.target.closest("textarea, input, select")) {
        return;
      }
      if (typeof row.setPointerCapture === "function") {
        try {
          row.setPointerCapture(event.pointerId);
        } catch {
          // Ignore capture errors for non-capturable pointers.
        }
      }
      swipeStartX = event.clientX;
      swipeStartY = event.clientY;
      swipeDx = 0;
      swipeDy = 0;
      swipeActive = true;
      swipeHandled = false;
      row.style.transition = "none";
      row.style.transform = "";
      longPressFired = false;
      longPressStartX = event.clientX;
      longPressStartY = event.clientY;
      clearLongPress();
      longPressTimer = setTimeout(() => {
        longPressFired = true;
        openMessageContextMenu(event.clientX, event.clientY, message.id);
      }, CONTEXT_LONG_PRESS_MS);
    });
    row.addEventListener("pointermove", (event) => {
      if (swipeActive) {
        swipeDx = event.clientX - swipeStartX;
        swipeDy = event.clientY - swipeStartY;
        if (swipeDx > 10 && Math.abs(swipeDx) > Math.abs(swipeDy)) {
          clearLongPress();
          row.style.transform = `translateX(${Math.min(56, swipeDx * 0.85)}px)`;
        }
      }
      if (!longPressTimer) {
        return;
      }
      if (
        Math.abs(event.clientX - longPressStartX) > CONTEXT_LONG_PRESS_MOVE_THRESHOLD_PX ||
        Math.abs(event.clientY - longPressStartY) > CONTEXT_LONG_PRESS_MOVE_THRESHOLD_PX
      ) {
        clearLongPress();
      }
    });
    row.addEventListener("pointerup", (event) => {
      if (selectionActive) {
        return;
      }
      if (typeof row.releasePointerCapture === "function") {
        try {
          row.releasePointerCapture(event.pointerId);
        } catch {
          // Ignore release errors.
        }
      }
      if (longPressFired) {
        event.preventDefault();
      }
      if (
        swipeActive &&
        !swipeHandled &&
        swipeDx > MESSAGE_REPLY_SWIPE_THRESHOLD_PX &&
        Math.abs(swipeDx) > Math.abs(swipeDy)
      ) {
        event.preventDefault();
        swipeHandled = true;
        setReplyTarget(message);
      }
      const interactiveTarget = event.target.closest("a, audio, video, textarea, input, button");
      const tapLikeGesture =
        !longPressFired &&
        !swipeHandled &&
        !interactiveTarget &&
        Math.abs(swipeDx) < 10 &&
        Math.abs(swipeDy) < 10 &&
        (state.platform === "iphone" || state.platform === "android");
      if (tapLikeGesture) {
        const now = Date.now();
        const isDoubleTap =
          now - lastTapAt <= 360 &&
          Math.abs(event.clientX - lastTapX) <= 24 &&
          Math.abs(event.clientY - lastTapY) <= 24;
        lastTapAt = now;
        lastTapX = event.clientX;
        lastTapY = event.clientY;
        if (isDoubleTap) {
          lastTapAt = 0;
          toggleMessageReaction(message.id, DEFAULT_QUICK_REACTION).catch((error) => {
            alert(error.message);
          });
        }
      }
      swipeActive = false;
      swipeDx = 0;
      swipeDy = 0;
      row.style.transition = "";
      row.style.transform = "";
      clearLongPress();
      longPressFired = false;
    });
    row.addEventListener("pointercancel", (event) => {
      if (typeof row.releasePointerCapture === "function") {
        try {
          row.releasePointerCapture(event.pointerId);
        } catch {
          // Ignore release errors.
        }
      }
      swipeActive = false;
      swipeDx = 0;
      swipeDy = 0;
      row.style.transition = "";
      row.style.transform = "";
      clearLongPress();
      longPressFired = false;
    });

    row.addEventListener("click", (event) => {
      if (!isMessageSelectionActive()) {
        return;
      }
      if (event.target.closest("a, audio, video, textarea, input, button, .message-reaction-btn, .message-action-btn")) {
        return;
      }
      toggleMessageSelection(message.id);
      renderMessages({ keepScrollPosition: true });
    });
    row.addEventListener("pointerleave", () => {
      if (!swipeActive) {
        row.style.transform = "";
      }
      clearLongPress();
    });

    if (message.replyTo) {
      const replyButton = document.createElement("button");
      replyButton.type = "button";
      replyButton.className = "message-reply-link";
      replyButton.dataset.jumpMessageId = message.replyTo.id ?? "";
      const replyAuthor = message.replyTo.sender
        ? getUserDisplayName({
            id: message.replyTo.sender.id,
            displayName: message.replyTo.sender.displayName,
          })
        : authorName;
      const replyText = message.replyTo.deleted ? t("messageReplyDeleted") : getMessagePreviewText(message.replyTo);
      replyButton.innerHTML = `<strong>${escapeHtml(replyAuthor)}</strong><span>${escapeHtml(replyText)}</span>`;
      body.appendChild(replyButton);
    }

    if (message.type === "call" && message.call) {
      let label = t("callNoAnswer");
      if (message.call.status === "busy") {
        label = t("callBusyStatus");
      } else if (message.call.status === "canceled") {
        label = t("callCanceled");
      } else if (message.call.status === "completed") {
        label = message.call.callerId === state.user?.id ? t("callOutgoing") : t("callIncoming");
      }
      const callNode = document.createElement("div");
      callNode.textContent = `${getCallModeIcon(message.call.mode)} ${label}`;
      body.appendChild(callNode);
    } else if (message.type === "file" && message.file) {
      const downloadUrl = buildFileUrl(message.file.id, "download");
      const inlineUrl = buildFileUrl(message.file.id, "inline");
      const openUrl = isMobilePlatform() ? inlineUrl : downloadUrl;
      const fileDisplayName = getDisplayFileName(message.file.originalName);
      const isImage = String(message.file.mimeType ?? "").startsWith("image/");
      const isVideo = String(message.file.mimeType ?? "").startsWith("video/");
      const isAudio = String(message.file.mimeType ?? "").startsWith("audio/");
      const caption = message.text && message.text !== fileDisplayName ? message.text : "";

      if (isImage || isVideo) {
        const previewButton = document.createElement("button");
        previewButton.type = "button";
        previewButton.className = "image-open-btn";
        previewButton.dataset.messageId = message.id;
        if (isVideo) {
          const video = document.createElement("video");
          video.className = "message-video";
          video.src = inlineUrl;
          video.muted = true;
          video.loop = true;
          video.playsInline = true;
          video.preload = "metadata";
          video.autoplay = true;
          previewButton.appendChild(video);
        } else {
          const image = document.createElement("img");
          image.className = "message-image";
          image.src = inlineUrl;
          image.alt = fileDisplayName || "image";
          image.loading = "lazy";
          previewButton.appendChild(image);
        }
        body.appendChild(previewButton);
      } else if (isAudio) {
        body.appendChild(createAudioMessageNode(message, inlineUrl));
      }

      if (!isImage && !isVideo && !isAudio) {
        const filePreview = createFilePreviewNode(
          {
            ...message.file,
            originalName: fileDisplayName,
          },
          openUrl,
        );
        body.appendChild(filePreview);
      }

      if (caption) {
        const captionNode = document.createElement("div");
        captionNode.className = "message-caption";
        captionNode.textContent = caption;
        body.appendChild(captionNode);
      }
    } else if (message.type === "location" && message.location) {
      appendLocationMessageContent(body, message);
    } else if (message.type === "poll" && message.poll) {
      appendPollMessageContent(body, message);
    } else {
      renderRichMessageBody(body, message);
    }

    if (isChannelLikeChat(chat) && getChatSettings(chat).commentsEnabled && (message.stream ?? "main") === "main") {
      const commentsBtn = document.createElement("button");
      commentsBtn.type = "button";
      commentsBtn.className = "message-action-btn";
      commentsBtn.dataset.action = "comments";
      commentsBtn.dataset.messageId = message.id;
      commentsBtn.dataset.svgIcon = "chat";
      commentsBtn.title = t("commentsForPost");
      commentsBtn.innerHTML = `<span class="svg-icon" data-svg-icon="chat"></span><span>${escapeHtml(t("commentsForPost"))}</span>`;
      actionsNode.appendChild(commentsBtn);
    }

    if (isMessagePinned(state.activeChatId, message.id)) {
      const pinnedNode = document.createElement("span");
      pinnedNode.className = "message-pinned-badge";
      pinnedNode.textContent = t("pinMessage");
      actionsNode.appendChild(pinnedNode);
    }

    const reactionEntries = Array.isArray(message.reactions) ? message.reactions : [];
    if (reactionEntries.length) {
      const reactionsNode = document.createElement("div");
      reactionsNode.className = "message-reactions";
      for (const reaction of reactionEntries) {
        const reactionBtn = document.createElement("button");
        reactionBtn.type = "button";
        reactionBtn.className = "message-reaction-btn";
        reactionBtn.classList.toggle("active", Boolean(reaction.mine));
        reactionBtn.dataset.emoji = reaction.emoji;
        reactionBtn.dataset.messageId = message.id;
        const emojiNode = createEmojiGlyphNode(reaction.emoji);
        const countNode = document.createElement("strong");
        countNode.textContent = String(Number(reaction.count) || 0);
        reactionBtn.appendChild(emojiNode);
        reactionBtn.appendChild(countNode);
        reactionsNode.appendChild(reactionBtn);
      }
      node.appendChild(reactionsNode);
    }

    elements.messageList.appendChild(fragment);
    if (secretChatActive) {
      scheduleSecretMessageExpiry(chat.id, message);
    }
  }

  renderSvgIcons(elements.messageList);
  if (keepScrollPosition) {
    const nextHeight = Number(elements.messageList.scrollHeight ?? 0);
    const delta = nextHeight - previousScrollHeight;
    elements.messageList.scrollTop = Math.max(0, previousScrollTop + delta);
  } else {
    elements.messageList.scrollTop = elements.messageList.scrollHeight;
  }
  emitReadReceiptForActiveChat();
  updatePinnedStrip();
  updateMessageSelectionToolbar();
}

function didMessagesChange(previousMessages, nextMessages) {
  if (!Array.isArray(previousMessages) || !Array.isArray(nextMessages)) {
    return true;
  }

  if (previousMessages.length !== nextMessages.length) {
    return true;
  }

  for (let index = 0; index < nextMessages.length; index += 1) {
    const previous = previousMessages[index] ?? {};
    const next = nextMessages[index] ?? {};
    if (String(previous.id ?? "") !== String(next.id ?? "")) {
      return true;
    }

    if (String(previous.updatedAt ?? previous.editedAt ?? "") !== String(next.updatedAt ?? next.editedAt ?? "")) {
      return true;
    }

    if (String(previous.body ?? "") !== String(next.body ?? "")) {
      return true;
    }

    if (String(previous.fileId ?? previous.file?.id ?? "") !== String(next.fileId ?? next.file?.id ?? "")) {
      return true;
    }
  }

  return false;
}

async function loadMe() {
  const payload = await api("/api/me");
  state.user = normalizePremiumUserLike(payload.user);
  state.privacyPreferences = readPrivacyPreferences(state.user?.id);
  state.unreadByChat = readUnreadByChat(state.user?.id);
  state.storyRuntime = readStoryRuntime(state.user?.id);
  state.storyStore = {
    own: [],
    peer: [],
    hydrated: false,
  };
  state.secretChats = readSecretChats(state.user?.id);
  state.secretChatTimers = readSecretChatTimers(state.user?.id);
  state.secretHiddenMessages = readSecretHiddenMessages(state.user?.id);
  state.secretChatMessages = readSecretChatMessages(state.user?.id);
  renderProfile();
}

function applyChatFoldersFromSettings(settings) {
  const nextFolders = getChatFoldersFromSettings(settings);
  if (!nextFolders) {
    return;
  }

  suppressChatFoldersSync = true;
  try {
    state.chatFolders = nextFolders;
    state.activeFolderId = normalizeFolderId(state.activeFolderId);
    saveChatFolders({ syncBackend: false });
    saveActiveFolder();
  } finally {
    suppressChatFoldersSync = false;
  }
}

async function loadSettings() {
  const payload = await api("/api/me/settings");
  state.settings = payload.settings ?? {};
  state.customNotificationSounds = normalizeCustomNotificationSounds(
    state.settings?.notifications?.customSounds ?? state.customNotificationSounds,
  );
  saveCustomNotificationSounds();
  applyChatFoldersFromSettings(state.settings);

  if (state.settings.language && i18n[state.settings.language]) {
    state.lang = state.settings.language;
    localStorage.setItem("yooh_lang", state.lang);
  }

  applyI18n();
  bindSettingsToForm();
  applyAppearance(state.settings.appearance ?? {});
  await ensureIphoneDefaultScale();
}

async function loadCalls() {
  try {
    const payload = await api("/api/calls?limit=200");
    state.callHistory = Array.isArray(payload.calls) ? payload.calls : [];
  } catch {
    state.callHistory = [];
  }
  renderCalls();
}

async function loadMessages() {
  if (!state.activeChatId) {
    if (state.messageLoadController) {
      state.messageLoadController.abort();
      state.messageLoadController = null;
    }
    state.currentMessages = [];
    renderMessages();
    return;
  }

  if (state.messageLoadController) {
    state.messageLoadController.abort();
  }
  const controller = new AbortController();
  state.messageLoadController = controller;
  const requestId = state.messageLoadRequestId + 1;
  state.messageLoadRequestId = requestId;
  const expectedChatId = state.activeChatId;
  const expectedStream = state.activeStream;
  const expectedThreadRootId = state.activeCommentThreadId;

  if (isSecretChat(expectedChatId)) {
    const nextMessages = getSecretChatMessages(expectedChatId);
    const changed = didMessagesChange(state.currentMessages, nextMessages);
    if (state.messageLoadController === controller) {
      state.messageLoadController = null;
    }
    state.currentMessages = nextMessages;
    if (changed) {
      renderMessages();
    } else {
      renderMessages({ keepScrollPosition: true });
    }
    return;
  }

  let endpoint = expectedStream === "comment" ? `/api/chats/${expectedChatId}/comments` : `/api/chats/${expectedChatId}/messages`;
  if (expectedStream === "comment" && expectedThreadRootId) {
    const params = new URLSearchParams();
    params.set("threadRootId", expectedThreadRootId);
    endpoint += `?${params.toString()}`;
  }

  try {
    const payload = await api(endpoint, { signal: controller.signal });
    const isStale =
      requestId !== state.messageLoadRequestId ||
      expectedChatId !== state.activeChatId ||
      expectedStream !== state.activeStream ||
      expectedThreadRootId !== state.activeCommentThreadId;
    if (isStale) {
      return;
    }
    const nextMessages = normalizeIncomingMessagesList(payload.messages);
    const changed = didMessagesChange(state.currentMessages, nextMessages);
    state.currentMessages = nextMessages;
    if (changed) {
      renderMessages();
    }
    const activeChat = getActiveChat();
    if (isServerChat(activeChat)) {
      renderServerPanels(activeChat).catch(() => {
        // Ignore transient server panel refresh errors.
      });
    }
  } catch (error) {
    if (controller.signal.aborted || error?.name === "AbortError") {
      return;
    }
    throw error;
  } finally {
    if (state.messageLoadController === controller) {
      state.messageLoadController = null;
    }
  }
}

async function openChat(chatId, preserveStream = true) {
  if (!isChatArchived(chatId)) {
    state.archiveListOpen = false;
  }
  const switchingToAnotherChat = Boolean(state.activeChatId && state.activeChatId !== chatId);
  const visible = getChatsForListView().some((entry) => entry.id === chatId);
  if (!visible) {
    const exists = state.chats.some((entry) => entry.id === chatId);
    if (exists && !isGameMode()) {
      state.activeFolderId = "all";
      saveActiveFolder();
      renderSideFolders();
    } else {
      state.activeChatId = null;
      state.currentMessages = [];
      renderChats();
      renderActiveChat();
      renderMessages();
      return;
    }
  }

  const visibleAfterFolderFallback = getVisibleChats().some((entry) => entry.id === chatId);
  if (!visibleAfterFolderFallback) {
    state.activeChatId = null;
    state.currentMessages = [];
    renderChats();
    renderActiveChat();
    renderMessages();
    return;
  }

  if (switchingToAnotherChat) {
    stopLocalTypingSignal(true);
    state.activeCommentThreadId = null;
    clearReplyTarget();
    clearMessageSelection();
  }

  state.activeChatId = chatId;
  markChatAsRead(chatId);
  if (!preserveStream) {
    state.activeStream = "main";
    state.activeCommentThreadId = null;
  }
  if (isMobilePlatform()) {
    if (state.iphoneEditMode) {
      setIphoneEditMode(false);
    }
    setMobileChatView("chat");
  }

  clearPendingFile();
  closeImageViewer();
  closeEntityPanel();
  renderChats();
  renderContacts();
  renderActiveChat();
  if (!elements.chatManagePanel.classList.contains("hidden")) {
    const chat = getActiveChat();
    if (chat && chat.type !== "direct") {
      openChatManagePanel(chat);
    } else {
      closeChatManagePanel();
    }
  }
  await loadMessages();
}

async function loadChats(targetChatId = state.activeChatId, preserveStream = true, options = {}) {
  const skipActiveMessagesReload = Boolean(options.skipActiveMessagesReload);
  const payload = await api("/api/chats");
  state.chats = buildChatsWithVirtualSecrets(payload.chats);
  syncUnreadMapWithChats();
  const visibleChats = getVisibleChats();

  if (state.call.chatId) {
    const callChat = state.chats.find((entry) => entry.id === state.call.chatId);
    if (!callChat && isActiveCallStatus()) {
      resetCallState();
    } else if (callChat) {
      const peer = getDirectPeer(callChat);
      if (peer) {
        state.call.peer = {
          id: peer.userId,
          chatId: peer.chatId,
          username: peer.username,
          displayName: peer.displayName,
          avatar: peer.avatar ?? "",
        };
        upsertCallParticipant(state.call.peer);
      } else if (isGroupCallChat(callChat)) {
        mergeCallParticipants(callChat.members ?? []);
      }
      renderCallState();
    }
  }

  if (state.socket) {
    state.chats.filter((chat) => !isLocalOnlyChat(chat)).forEach((chat) => state.socket.emit("chat:join", chat.id));
  }

  renderChats();
  renderActiveChat();

  const hasTarget = targetChatId && visibleChats.some((chat) => chat.id === targetChatId);
  if (hasTarget) {
    const switchingChat = state.activeChatId !== targetChatId;
    if (switchingChat) {
      await openChat(targetChatId, preserveStream);
      return;
    }

    markChatAsRead(targetChatId);

    if (!preserveStream && state.activeStream !== "main") {
      state.activeStream = "main";
      renderActiveChat();
    }

    renderChats();
    if (!skipActiveMessagesReload || state.currentMessages.length === 0) {
      await loadMessages();
    }
    return;
  }

  if (!state.activeChatId && visibleChats.length && !isMobilePlatform()) {
    const preferredChat = visibleChats.find((entry) => !isSupportBotChat(entry)) ?? visibleChats[0];
    await openChat(preferredChat.id, false);
    return;
  }

  if (!visibleChats.some((chat) => chat.id === state.activeChatId)) {
    state.activeChatId = null;
    state.currentMessages = [];
    renderMessages();
    renderActiveChat();
    if (isMobilePlatform()) {
      setMobileChatView("list");
    }
  }
}

function clearScheduledChatReload() {
  if (state.chatReloadTimer) {
    clearTimeout(state.chatReloadTimer);
  }
  state.chatReloadTimer = null;
  state.pendingChatReload = null;
}

function scheduleChatsReload(targetChatId = state.activeChatId, preserveStream = true) {
  const safeTargetChatId = targetChatId || state.activeChatId || null;
  if (!state.pendingChatReload) {
    state.pendingChatReload = {
      targetChatId: safeTargetChatId,
      preserveStream,
    };
  } else {
    if (!state.pendingChatReload.targetChatId && safeTargetChatId) {
      state.pendingChatReload.targetChatId = safeTargetChatId;
    }
    state.pendingChatReload.preserveStream = state.pendingChatReload.preserveStream && preserveStream;
  }

  if (state.chatReloadTimer) {
    return;
  }

  state.chatReloadTimer = setTimeout(() => {
    const pending = state.pendingChatReload;
    clearScheduledChatReload();
    loadChats(pending?.targetChatId ?? state.activeChatId, pending?.preserveStream ?? true).catch(() => {
      // Ignore transient reload errors.
    });
  }, CHAT_RELOAD_DEBOUNCE_MS);
}

async function syncAppState() {
  if (!state.token || state.syncInFlight || document.hidden || isActiveCallStatus()) {
    return;
  }

  state.syncInFlight = true;
  try {
    await Promise.all([
      loadChats(state.activeChatId, true, { skipActiveMessagesReload: true }),
      loadStories(),
    ]);
  } catch {
    // Ignore background sync errors; next tick will retry.
  } finally {
    state.syncInFlight = false;
  }
}

function stopBackgroundSync() {
  if (!state.syncTimer) {
    return;
  }
  clearInterval(state.syncTimer);
  state.syncTimer = null;
}

function startBackgroundSync() {
  stopBackgroundSync();
  state.syncTimer = setInterval(() => {
    syncAppState().catch(() => {
      // Ignore interval sync failures.
    });
  }, BACKGROUND_SYNC_INTERVAL_MS);
}

function isNotificationAllowedForChat(chat) {
  if (!chat) {
    return false;
  }
  const notifications = state.settings?.notifications ?? {};
  if (chat.type === "direct") {
    return Boolean(notifications.privateChats);
  }
  if (chat.type === "group" || chat.type === "server") {
    return Boolean(notifications.groups);
  }
  if (chat.type === "channel") {
    return Boolean(notifications.channels);
  }
  return true;
}

function isNotificationEnabledForChat(chat) {
  if (!chat) {
    return false;
  }
  return isNotificationAllowedForChat(chat) && isChatNotificationsEnabled(chat.id);
}

function playTone({ frequency = 740, type = "sine", peakGain = 0.06, durationSeconds = 0.19 } = {}) {
  if (!audioUserGestureUnlocked) {
    return;
  }
  const AudioContextCtor = globalThis.AudioContext || globalThis.webkitAudioContext;
  if (typeof AudioContextCtor !== "function") {
    return;
  }
  const context = new AudioContextCtor();
  const startTone = () => {
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = type;
    oscillator.frequency.value = frequency;
    gain.gain.value = 0.0001;
    oscillator.connect(gain);
    gain.connect(context.destination);
    const now = context.currentTime;
    gain.gain.exponentialRampToValueAtTime(peakGain, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + durationSeconds);
    oscillator.start(now);
    oscillator.stop(now + durationSeconds + 0.01);
    oscillator.onended = () => {
      context.close().catch(() => {});
    };
  };
  if (context.state === "suspended") {
    context
      .resume()
      .then(() => {
        startTone();
      })
      .catch(() => {
        context.close().catch(() => {});
      });
    return;
  }
  startTone();
}

function canPlayUiSounds() {
  const notifications = getNotificationSettings();
  return Boolean(notifications.sounds && notifications.inAppSounds);
}

function shouldPlayUiSound(kind, cooldownMs = 0) {
  const safeKind = String(kind ?? "").trim();
  if (!safeKind) {
    return false;
  }
  if (!canPlayUiSounds()) {
    return false;
  }
  const now = Date.now();
  const lastPlayedAt = Number(uiSoundLastPlayedAt[safeKind] ?? 0);
  if (cooldownMs > 0 && now - lastPlayedAt < cooldownMs) {
    return false;
  }
  uiSoundLastPlayedAt[safeKind] = now;
  return true;
}

function playToneBurst(notes = []) {
  let offsetMs = 0;
  for (const note of notes) {
    const {
      frequency = 740,
      type = "sine",
      peakGain = 0.06,
      durationSeconds = 0.18,
      gapMs = 55,
    } = note ?? {};
    const noteOffset = offsetMs;
    setTimeout(() => {
      playTone({ frequency, type, peakGain, durationSeconds });
    }, noteOffset);
    const durationMs = Math.max(30, Math.round(Number(durationSeconds) * 1000));
    offsetMs += durationMs + Math.max(0, Number(gapMs) || 0);
  }
}

function playNotificationSound() {
  if (!shouldPlayUiSound("notification", 120)) {
    return;
  }
  const selectedSoundId = getNotificationSettings().messageSound;
  const selectedSound =
    getCustomNotificationSounds().find((entry) => entry.id === selectedSoundId) ??
    getBuiltInNotificationSoundEntry(selectedSoundId, { kind: "message" });
  if (selectedSound?.dataUrl || selectedSound?.src) {
    try {
      const audio = new Audio(selectedSound.dataUrl || selectedSound.src);
      audio.volume = 0.8;
      void audio.play();
      return;
    } catch {
      // Fall back to generated sound below.
    }
  }
  try {
    playToneBurst([{ frequency: 760, type: "sine", peakGain: 0.06, durationSeconds: 0.16 }]);
  } catch {
    // Ignore sound playback errors.
  }
}

function getCallRingtonePattern(soundId) {
  switch (normalizeNotificationSoundId(soundId, { kind: "call" })) {
    case "iphone-5":
      return [
        { frequency: 740, type: "triangle", peakGain: 0.065, durationSeconds: 0.16, gapMs: 45 },
        { frequency: 880, type: "triangle", peakGain: 0.07, durationSeconds: 0.2, gapMs: 40 },
        { frequency: 988, type: "triangle", peakGain: 0.07, durationSeconds: 0.22, gapMs: 0 },
      ];
    case "iphone-7":
      return [
        { frequency: 640, type: "sine", peakGain: 0.06, durationSeconds: 0.14, gapMs: 30 },
        { frequency: 760, type: "sine", peakGain: 0.065, durationSeconds: 0.18, gapMs: 35 },
        { frequency: 920, type: "sine", peakGain: 0.07, durationSeconds: 0.2, gapMs: 0 },
      ];
    case "smartphone":
      return [
        { frequency: 580, type: "square", peakGain: 0.05, durationSeconds: 0.1, gapMs: 30 },
        { frequency: 720, type: "square", peakGain: 0.055, durationSeconds: 0.12, gapMs: 30 },
        { frequency: 860, type: "square", peakGain: 0.06, durationSeconds: 0.16, gapMs: 0 },
      ];
    case "iphone-x":
    default:
      return [
        { frequency: 620, type: "triangle", peakGain: 0.07, durationSeconds: 0.22, gapMs: 40 },
        { frequency: 720, type: "triangle", peakGain: 0.07, durationSeconds: 0.22, gapMs: 0 },
      ];
  }
}

function stopAudioPlayback(audio) {
  if (!audio) {
    return;
  }
  try {
    audio.pause();
    audio.currentTime = 0;
  } catch {
    // Ignore media cleanup errors.
  }
}

function getNotificationSoundSource(soundId, { kind = "message" } = {}) {
  const safeId = normalizeNotificationSoundId(soundId, { kind });
  const customSound = getCustomNotificationSounds().find((entry) => entry.id === safeId);
  if (customSound?.dataUrl) {
    return customSound.dataUrl;
  }
  return getBuiltInNotificationSoundEntry(safeId, { kind })?.src ?? "";
}

function playIncomingCallRingtonePulse() {
  if (!canPlayUiSounds()) {
    return;
  }
  const source = getNotificationSoundSource(getNotificationSettings().ringtone, { kind: "call" });
  if (source) {
    stopAudioPlayback(incomingCallRingtoneAudio);
    incomingCallRingtoneAudio = null;
    try {
      incomingCallRingtoneAudio = new Audio(source);
      incomingCallRingtoneAudio.volume = 0.88;
      incomingCallRingtoneAudio.loop = true;
      void incomingCallRingtoneAudio.play();
      return;
    } catch {
      stopAudioPlayback(incomingCallRingtoneAudio);
      incomingCallRingtoneAudio = null;
    }
  }
  try {
    playToneBurst(getCallRingtonePattern(getNotificationSettings().ringtone));
  } catch {
    // Ignore ringtone playback errors.
  }
}

function previewCallRingtone(soundId) {
  if (!canPlayUiSounds()) {
    return;
  }
  stopAudioPlayback(ringtonePreviewAudio);
  ringtonePreviewAudio = null;
  const source = getNotificationSoundSource(soundId, { kind: "call" });
  if (source) {
    try {
      ringtonePreviewAudio = new Audio(source);
      ringtonePreviewAudio.volume = 0.88;
      ringtonePreviewAudio.addEventListener(
        "ended",
        () => {
          ringtonePreviewAudio = null;
        },
        { once: true },
      );
      void ringtonePreviewAudio.play();
      return;
    } catch {
      stopAudioPlayback(ringtonePreviewAudio);
      ringtonePreviewAudio = null;
    }
  }
  try {
    playToneBurst(getCallRingtonePattern(soundId));
  } catch {
    // Ignore ringtone preview errors.
  }
}

