function stopIncomingCallRingtone() {
  stopAudioPlayback(incomingCallRingtoneAudio);
  incomingCallRingtoneAudio = null;
  if (!incomingCallRingtoneTimer) {
    return;
  }
  clearInterval(incomingCallRingtoneTimer);
  incomingCallRingtoneTimer = null;
}

function startIncomingCallRingtone() {
  if (!canPlayUiSounds()) {
    return;
  }
  stopIncomingCallRingtone();
  playIncomingCallRingtonePulse();
  if (incomingCallRingtoneAudio) {
    return;
  }
  incomingCallRingtoneTimer = setInterval(() => {
    if (state.call.status !== "incoming") {
      stopIncomingCallRingtone();
      return;
    }
    playIncomingCallRingtonePulse();
  }, 1600);
}

function showInAppNotification({ title, body, avatar = "", chatId = "" }) {
  if (!elements.appNotificationStack) {
    return;
  }
  const toast = document.createElement("div");
  toast.className = "app-notification-toast";
  toast.innerHTML = `
    <span class="avatar app-notification-avatar">Y</span>
    <span class="app-notification-meta">
      <span class="app-notification-title">${title}</span>
      <span class="app-notification-body">${body}</span>
    </span>
    <button type="button" class="app-notification-close" data-svg-icon="x" title="${t("close")}"></button>
  `;
  const avatarNode = toast.querySelector(".app-notification-avatar");
  applyAvatarNode(avatarNode, title, avatar, "Y");
  renderSvgIcons(toast);
  elements.appNotificationStack.appendChild(toast);

  const close = () => {
    toast.remove();
  };
  toast.querySelector(".app-notification-close")?.addEventListener("click", close);
  toast.addEventListener("click", async (event) => {
    if (event.target.closest(".app-notification-close")) {
      return;
    }
    close();
    if (chatId) {
      await openChat(chatId, false).catch(() => {});
    }
  });
  setTimeout(close, 6200);
}

function showDesktopNotification({ title, body, avatar = "" }) {
  if (typeof Notification === "undefined") {
    return;
  }
  if (Notification.permission === "default") {
    Notification.requestPermission().catch(() => {});
    return;
  }
  if (Notification.permission !== "granted") {
    return;
  }
  try {
    const notification = new Notification(title, {
      body,
      icon: avatar || "/icons/icon-192.png",
      silent: !state.settings?.notifications?.sounds,
    });
    setTimeout(() => {
      notification.close();
    }, 6500);
  } catch {
    // Ignore system notification failures.
  }
}

function maybeShowMessageNotification(message) {
  if (!message || !message.chatId || !state.user) {
    return;
  }
  if (String(message.sender?.id ?? "") === String(state.user.id ?? "")) {
    return;
  }

  const chat = state.chats.find((entry) => entry.id === message.chatId);
  if (!isNotificationEnabledForChat(chat)) {
    return;
  }

  const title = chat.type === "direct" ? getUserDisplayName(message.sender) : chat.title || getChatTitle(chat);
  const body = state.settings?.notifications?.messagePreview ? getMessagePreview(message) : t("newMessage");
  const avatar = message.sender?.avatar ?? "";
  showInAppNotification({
    title,
    body,
    avatar,
    chatId: chat.id,
  });

  if (document.hidden || document.visibilityState === "hidden") {
    showDesktopNotification({ title, body, avatar });
  }
  playNotificationSound();
}

function isMessageInActiveStream(messageLike) {
  const stream = String(messageLike?.stream ?? "main");
  if (stream !== state.activeStream) {
    return false;
  }
  if (stream !== "comment") {
    return true;
  }
  const activeThreadId = String(state.activeCommentThreadId ?? "").trim();
  if (!activeThreadId) {
    return true;
  }
  return String(messageLike?.threadRootId ?? "").trim() === activeThreadId;
}

function findCurrentMessageIndex(messageLike) {
  if (!messageLike) {
    return -1;
  }
  const messageId = String(messageLike.id ?? "").trim();
  const clientMessageId = String(messageLike.clientMessageId ?? "").trim();
  if (messageId) {
    const byId = state.currentMessages.findIndex((entry) => String(entry?.id ?? "").trim() === messageId);
    if (byId >= 0) {
      return byId;
    }
  }
  if (clientMessageId) {
    return state.currentMessages.findIndex(
      (entry) => String(entry?.clientMessageId ?? "").trim() === clientMessageId,
    );
  }
  return -1;
}

function upsertCurrentMessage(message, { rerender = true } = {}) {
  const normalizedMessage = normalizeIncomingMessagePayload(message);
  if (!normalizedMessage || !normalizedMessage.chatId) {
    return false;
  }
  if (normalizedMessage.chatId !== state.activeChatId) {
    return false;
  }
  if (!isMessageInActiveStream(normalizedMessage)) {
    return false;
  }

  const existingIndex = findCurrentMessageIndex(normalizedMessage);
  if (existingIndex >= 0) {
    const mergedMessage = {
      ...state.currentMessages[existingIndex],
      ...normalizedMessage,
    };
    const hasServerMessageId =
      String(normalizedMessage.id ?? "").trim() && !String(normalizedMessage.id ?? "").trim().startsWith("pending-");
    if (hasServerMessageId) {
      mergedMessage.pendingStatus = "";
    }
    state.currentMessages[existingIndex] = mergedMessage;
  } else {
    state.currentMessages.push(normalizedMessage);
  }

  if (rerender) {
    renderMessages();
  }
  return true;
}

function appendReadByUserToMessage(message, readerUserId) {
  const safeReaderUserId = String(readerUserId ?? "").trim();
  if (!safeReaderUserId || !message) {
    return message;
  }
  const current = Array.isArray(message.readByUserIds)
    ? message.readByUserIds.map((entry) => String(entry ?? "").trim()).filter(Boolean)
    : [];
  if (current.includes(safeReaderUserId)) {
    return message;
  }
  return {
    ...message,
    readByUserIds: [...current, safeReaderUserId],
    pendingStatus: "",
  };
}

function markChatMessagesReadByUser(chatId, stream, readerUserId, upToMessageId = "") {
  const safeChatId = String(chatId ?? "").trim();
  const safeReaderUserId = String(readerUserId ?? "").trim();
  if (!safeChatId || !safeReaderUserId) {
    return false;
  }
  const safeStream = String(stream ?? "main").trim() || "main";
  const limitMessageId = String(upToMessageId ?? "").trim();
  let limitTimestamp = Number.POSITIVE_INFINITY;
  if (limitMessageId) {
    const marker = state.currentMessages.find((entry) => String(entry?.id ?? "").trim() === limitMessageId);
    if (marker) {
      limitTimestamp = new Date(marker.createdAt ?? 0).getTime();
    }
  }
  let updated = false;
  for (let index = 0; index < state.currentMessages.length; index += 1) {
    const message = state.currentMessages[index];
    if (!message || String(message.chatId ?? "").trim() !== safeChatId) {
      continue;
    }
    if (String(message.stream ?? "main").trim() !== safeStream) {
      continue;
    }
    if (String(message.sender?.id ?? "") !== String(state.user?.id ?? "")) {
      continue;
    }
    const createdAtMs = new Date(message.createdAt ?? 0).getTime();
    if (Number.isFinite(limitTimestamp) && createdAtMs > limitTimestamp) {
      continue;
    }
    const next = appendReadByUserToMessage(message, safeReaderUserId);
    if (next !== message) {
      state.currentMessages[index] = next;
      updated = true;
    }
  }
  return updated;
}

function handleChatReadReceipt(payload) {
  const chatId = String(payload?.chatId ?? "").trim();
  if (!chatId) {
    return;
  }
  const stream = String(payload?.stream ?? state.activeStream ?? "main").trim() || "main";
  const readerUserId = String(payload?.fromUser?.id ?? "").trim();
  if (!readerUserId || readerUserId === String(state.user?.id ?? "")) {
    return;
  }
  const messageId = String(payload?.messageId ?? "").trim();
  const changed = markChatMessagesReadByUser(chatId, stream, readerUserId, messageId);
  if (changed && chatId === state.activeChatId) {
    renderMessages({ keepScrollPosition: true });
  }
}

function emitReadReceiptForMessage(message) {
  if (!state.socket?.connected || !message) {
    return false;
  }
  if (document.hidden || document.visibilityState === "hidden") {
    return false;
  }

  const chatId = String(message.chatId ?? "").trim();
  if (!chatId || chatId !== String(state.activeChatId ?? "").trim()) {
    return false;
  }

  const stream = String(message.stream ?? state.activeStream ?? "main").trim() || "main";
  if (!isMessageInActiveStream(message)) {
    return false;
  }

  const senderId = String(message.sender?.id ?? "").trim();
  if (!senderId || senderId === String(state.user?.id ?? "").trim()) {
    return false;
  }

  const messageId = String(message.id ?? "").trim();
  const cursorKey = buildReadCursorKey(chatId, stream);
  if (!messageId || !cursorKey) {
    return false;
  }
  if (String(state.chatReadCursorByChat?.[cursorKey] ?? "") === messageId) {
    return false;
  }

  state.chatReadCursorByChat[cursorKey] = messageId;
  state.socket.emit("chat:read", {
    chatId,
    stream,
    messageId,
  });
  return true;
}

function emitReadReceiptForActiveChat() {
  if (!state.socket?.connected || !state.activeChatId || !Array.isArray(state.currentMessages) || !state.currentMessages.length) {
    return;
  }
  if (document.hidden || document.visibilityState === "hidden") {
    return;
  }
  const stream = state.activeStream === "comment" ? "comment" : "main";
  let targetMessage = null;
  for (let index = state.currentMessages.length - 1; index >= 0; index -= 1) {
    const message = state.currentMessages[index];
    if (!message) {
      continue;
    }
    if (String(message.chatId ?? "").trim() !== String(state.activeChatId ?? "").trim()) {
      continue;
    }
    if (String(message.stream ?? "main") !== stream) {
      continue;
    }
    const senderId = String(message.sender?.id ?? "").trim();
    if (!senderId || senderId === String(state.user?.id ?? "").trim()) {
      continue;
    }
    targetMessage = message;
    break;
  }
  if (!targetMessage) {
    return;
  }
  emitReadReceiptForMessage({
    ...targetMessage,
    stream,
  });
}

function handleIncomingMessage(message) {
  const normalizedMessage = normalizeIncomingMessagePayload(message);
  if (!normalizedMessage || !normalizedMessage.chatId) {
    return;
  }

  const isCurrentChat = normalizedMessage.chatId === state.activeChatId;
  const isCurrentStream = isMessageInActiveStream(normalizedMessage);
  const fromUserId = String(normalizedMessage.sender?.id ?? "").trim();
  const isMine = fromUserId && fromUserId === String(state.user?.id ?? "").trim();

  if (isCurrentChat && isCurrentStream) {
    upsertCurrentMessage(normalizedMessage, { rerender: true });
    if (!isMine) {
      emitReadReceiptForMessage(normalizedMessage);
    }
  }

  if (!isMine && (!isCurrentChat || !isCurrentStream)) {
    incrementUnreadCount(normalizedMessage.chatId, 1);
  }

  if (!isCurrentChat || !isCurrentStream) {
    maybeShowMessageNotification(normalizedMessage);
  }

  if (isCurrentChat && isSupportBotChat(getActiveChat())) {
    void syncSupportTicketState({ force: true });
  }

  scheduleChatsReload(state.activeChatId, true);
}

function handleIncomingMessageUpdated(message) {
  const normalizedMessage = normalizeIncomingMessagePayload(message);
  if (!normalizedMessage || !normalizedMessage.chatId) {
    return;
  }

  const isCurrentChat = normalizedMessage.chatId === state.activeChatId;
  const isCurrentStream = isMessageInActiveStream(normalizedMessage);
  if (isCurrentChat && isCurrentStream) {
    const index = findCurrentMessageIndex(normalizedMessage);
    if (index >= 0) {
      state.currentMessages[index] = normalizedMessage;
      renderMessages();
    }
  }

  scheduleChatsReload(state.activeChatId, true);
}

function handleIncomingMessageDeleted(payload) {
  if (!payload?.chatId) {
    return;
  }

  const isCurrentChat = payload.chatId === state.activeChatId;
  if (payload?.messageId == null) {
    const isCurrentStream = String(payload.stream ?? "main") === state.activeStream;
    if (isCurrentChat && isCurrentStream) {
      state.currentMessages = [];
      renderMessages();
    }
    scheduleChatsReload(state.activeChatId, true);
    return;
  }
  const isCurrentStream = isMessageInActiveStream(payload);
  if (isCurrentChat && isCurrentStream) {
    setSecretMessageExpiry(payload.chatId, payload.messageId, 0);
    state.currentMessages = state.currentMessages.filter((entry) => entry.id !== payload.messageId);
    renderMessages();
  }

  scheduleChatsReload(state.activeChatId, true);
}

function handleChatUpdated(payload) {
  const chatId = payload?.chatId ?? null;
  if (!chatId || chatId === state.activeChatId) {
    if (isSupportBotChat(getActiveChat())) {
      void syncSupportTicketState({ force: true });
    }
  }
  scheduleChatsReload(chatId || state.activeChatId, true);
}

function requestPresenceRender() {
  if (presenceRenderFrameId !== null) {
    return;
  }
  const requestFrame = globalThis.requestAnimationFrame ?? ((callback) => setTimeout(callback, 16));
  presenceRenderFrameId = requestFrame(() => {
    presenceRenderFrameId = null;
    renderChats();
    renderContacts();
    renderProfile();
    renderActiveChat();
  });
}

function applyPresenceSnapshot(payload) {
  state.presenceByUser = {};

  const onlineUserIds = Array.isArray(payload?.onlineUserIds) ? payload.onlineUserIds : [];
  for (const userId of onlineUserIds) {
    const safeUserId = String(userId ?? "").trim();
    if (!safeUserId) {
      continue;
    }
    state.presenceByUser[safeUserId] = {
      online: true,
      lastSeenAt: null,
      lastSeenHidden: false,
    };
  }

  const lastSeenByUser = payload?.lastSeenAtByUser && typeof payload.lastSeenAtByUser === "object" ? payload.lastSeenAtByUser : {};
  for (const [userId, lastSeenAt] of Object.entries(lastSeenByUser)) {
    const safeUserId = String(userId ?? "").trim();
    if (!safeUserId) {
      continue;
    }
    if (!state.presenceByUser[safeUserId]) {
      state.presenceByUser[safeUserId] = {
        online: false,
        lastSeenAt: lastSeenAt || null,
        lastSeenHidden: false,
      };
      continue;
    }
    state.presenceByUser[safeUserId].lastSeenAt = lastSeenAt || null;
    state.presenceByUser[safeUserId].lastSeenHidden = false;
  }

  const hiddenUserIds = Array.isArray(payload?.hiddenUserIds) ? payload.hiddenUserIds : [];
  for (const userId of hiddenUserIds) {
    const safeUserId = String(userId ?? "").trim();
    if (!safeUserId || safeUserId === String(state.user?.id ?? "").trim()) {
      continue;
    }
    state.presenceByUser[safeUserId] = {
      online: false,
      lastSeenAt: null,
      lastSeenHidden: true,
    };
  }

  requestPresenceRender();
}

function handlePresenceUpdate(payload) {
  const safeUserId = String(payload?.userId ?? "").trim();
  if (!safeUserId) {
    return;
  }

  state.presenceByUser[safeUserId] = {
    online: Boolean(payload?.online),
    lastSeenAt: payload?.lastSeenAt ? new Date(payload.lastSeenAt).toISOString() : null,
    lastSeenHidden: Boolean(payload?.lastSeenHidden),
  };
  if (state.presenceByUser[safeUserId].lastSeenHidden) {
    state.presenceByUser[safeUserId].online = false;
    state.presenceByUser[safeUserId].lastSeenAt = null;
  }

  if (safeUserId === String(state.user?.id ?? "").trim()) {
    state.presenceByUser[safeUserId].online = true;
    state.presenceByUser[safeUserId].lastSeenAt = null;
    state.presenceByUser[safeUserId].lastSeenHidden = false;
  }
  requestPresenceRender();
}

function handleSessionRevoked(payload) {
  const revokedSessionIds = Array.isArray(payload?.sessionIds)
    ? payload.sessionIds
        .map((entry) => String(entry ?? "").trim())
        .filter(Boolean)
    : [];
  if (!revokedSessionIds.length) {
    return;
  }

  const currentSessionId = String(state.user?.sessionId ?? "").trim();
  if (!currentSessionId) {
    return;
  }

  if (revokedSessionIds.includes(currentSessionId)) {
    resetToAuth();
    alert("Сеанс завершен на этом устройстве. Выполните вход снова.");
    return;
  }

  if (state.settingsSection === "privacy-sessions") {
    loadAuthSessions()
      .then(() => {
        if (state.settingsSection === "privacy-sessions") {
          renderSettingsPrivacySessionsSection();
        }
      })
      .catch(() => {
        // Keep current sessions list if refresh failed.
      });
  }
}

async function syncSettingsFromRealtime() {
  if (!state.token) {
    return;
  }
  if (settingsRealtimeSyncInFlight) {
    settingsRealtimeSyncQueued = true;
    return;
  }
  settingsRealtimeSyncInFlight = true;
  try {
    await loadSettings();
    applyChatWallpaper(getActiveChat());
    if (state.settingsSection) {
      renderSettingsSection();
    }
  } catch {
    // Ignore transient settings sync errors.
  } finally {
    settingsRealtimeSyncInFlight = false;
    if (settingsRealtimeSyncQueued) {
      settingsRealtimeSyncQueued = false;
      syncSettingsFromRealtime().catch(() => {
        // Ignore follow-up sync errors.
      });
    }
  }
  syncAuthCodeTargetHint();
  updateAuthCodeResendHint();
  syncAuthEntryHeader();
}

function connectSocket() {
  if (state.socket) {
    state.socket.disconnect();
  }
  const iphoneProfile = isIphonePlatform();

  state.socket = io({
    auth: {
      token: state.token,
    },
    transports: ["websocket", "polling"],
    reconnection: true,
    reconnectionAttempts: Number.MAX_SAFE_INTEGER,
    reconnectionDelay: iphoneProfile ? 500 : 900,
    reconnectionDelayMax: iphoneProfile ? 3200 : 5000,
    timeout: iphoneProfile ? 18000 : 10000,
    closeOnBeforeunload: false,
  });

  state.socket.on("connect", () => {
    clearCallSignalDisconnectTimer();
    if (state.user?.id) {
      state.presenceByUser[String(state.user.id)] = { online: true, lastSeenAt: null, lastSeenHidden: false };
    }
    requestPresenceRender();
    if (isActiveCallStatus()) {
      if (shouldReconnectCallSession()) {
        state.call.status = "connecting";
        renderCallState();
        syncCallPeerConnections().catch(() => {
          // Ignore reconnect sync failures, watchdog handles fallback.
        });
      } else {
        renderCallState();
      }
    }
    syncAppState().catch(() => {
      // Ignore connect sync failures.
    });
  });

  state.socket.on("chat:message", handleIncomingMessage);
  state.socket.on("chat:message:updated", handleIncomingMessageUpdated);
  state.socket.on("chat:message:deleted", handleIncomingMessageDeleted);
  state.socket.on("chat:updated", handleChatUpdated);
  state.socket.on("presence:snapshot", applyPresenceSnapshot);
  state.socket.on("presence:update", handlePresenceUpdate);
  state.socket.on("auth:session-revoked", handleSessionRevoked);
  state.socket.on("chat:typing", handleIncomingTyping);
  state.socket.on("chat:read", handleChatReadReceipt);
  state.socket.on("settings:updated", () => {
    syncSettingsFromRealtime().catch(() => {
      // Ignore transient realtime settings errors.
    });
  });
  state.socket.on("story:updated", () => {
    loadStories().catch(() => {
      // Ignore transient story sync errors.
    });
  });
  state.socket.on("calls:updated", () => {
    loadCalls().catch(() => {
      // Ignore transient call history sync errors.
    });
  });
  state.socket.on("call:incoming", handleIncomingCall);
  state.socket.on("call:accepted", handleCallAccepted);
  state.socket.on("call:participants", handleCallParticipants);
  state.socket.on("call:participant-left", handleCallParticipantLeft);
  state.socket.on("call:declined", handleCallDeclined);
  state.socket.on("call:hangup", handleCallHangup);
  state.socket.on("call:signal", (payload) => {
    handleCallSignal(payload).catch(() => {
      // Ignore malformed realtime signal packets.
    });
  });
  state.socket.on("disconnect", () => {
    stopLocalTypingSignal(false);
    stopIncomingCallRingtone();
    state.typingByChat = {};
    const disconnectedAt = new Date().toISOString();
    for (const [userId, entry] of Object.entries(state.presenceByUser)) {
      const hidden = Boolean(entry?.lastSeenHidden);
      state.presenceByUser[userId] = {
        online: false,
        lastSeenAt: hidden ? null : entry?.lastSeenAt ?? disconnectedAt,
        lastSeenHidden: hidden,
      };
    }
    requestPresenceRender();
    if (isActiveCallStatus()) {
      if (shouldReconnectCallSession()) {
        state.call.status = "connecting";
        renderCallState();
        clearCallSignalDisconnectTimer();
        const sessionIdSnapshot = state.call.sessionId;
        scheduleCallSignalDisconnectTimer(sessionIdSnapshot);
      } else {
        renderCallState();
      }
    }
  });

  state.socket.on("connect_error", () => {
    syncAppState().catch(() => {
      // Ignore fallback sync failures.
    });
  });
}

function resetToAuth() {
  stopIncomingCallRingtone();
  clearCallSignalDisconnectTimer();
  settingsRealtimeSyncInFlight = false;
  settingsRealtimeSyncQueued = false;
  stopSidebarResizeSession();
  stopBackgroundSync();
  clearScheduledChatReload();
  if (bootstrapRecoveryTimer) {
    clearTimeout(bootstrapRecoveryTimer);
    bootstrapRecoveryTimer = null;
  }
  if (chatFoldersSyncTimer) {
    clearTimeout(chatFoldersSyncTimer);
    chatFoldersSyncTimer = null;
  }
  chatFoldersSyncInFlight = false;
  chatFoldersSyncQueued = false;
  suppressChatFoldersSync = false;
  stopLocalTypingSignal(false);
  if (state.messageLoadController) {
    state.messageLoadController.abort();
    state.messageLoadController = null;
  }
  if (state.socket) {
    state.socket.disconnect();
    state.socket = null;
  }
  if (state.voiceRecorder?.active) {
    try {
      state.voiceRecorder.recorder.stop();
    } catch {
      // Ignore recorder stop errors on logout.
    }
  }
  setVoiceRecordingUi(false, { state: "idle" });
  closeCallPeerConnection();
  for (const track of [state.call.microphoneTrack, state.call.screenAudioTrack]) {
    if (!track || track.readyState !== "live") {
      continue;
    }
    try {
      track.onended = null;
      track.stop();
    } catch {
      // Ignore media track stop errors.
    }
  }
  stopMediaStream(state.call.localStream);
  stopMediaStream(state.call.remoteStream);

  localStorage.removeItem("yooh_token");
  state.token = "";
  state.user = null;
  state.settings = null;
  state.privacyPreferences = createDefaultPrivacyPreferences();
  state.authSessions = { current: null, others: [] };
  state.authSessionsLoading = false;
  state.chats = [];
  state.unreadByChat = {};
  state.secretChats = {};
  state.secretChatTimers = {};
  state.secretHiddenMessages = {};
  state.secretChatMessages = {};
  state.activeChatId = null;
  state.supportTicket = {
    chatId: "",
    active: null,
    panel: "menu",
    loading: false,
    updatedAt: 0,
    request: null,
  };
  state.mobileChatView = "list";
  state.currentMessages = [];
  state.globalSearchResults = [];
  state.authBusy = false;
  state.callHistory = [];
  state.drawerOpen = false;
  state.drawerTab = "menu";
  state.pendingFiles = [];
  state.dragDepth = 0;
  state.imageViewerMessageId = null;
  state.pendingLoginTicket = "";
  state.pendingPhone = "";
  state.pendingEmail = "";
  state.authLoginMethod = "phone";
  state.authRegisterStep = "code";
  resetAuthRegisterDraft();
  clearAuthCodeResendCountdown();
  state.authCodeResendUntil = 0;
  setAuthCodeValue("");
  state.authQrToken = "";
  state.authQrExpiresAt = "";
  stopAuthQrPolling();
  state.voiceRecorder = null;
  state.voiceRecordingState = "idle";
  destroyVoiceDraft();
  state.webrtcConfig = null;
  state.syncInFlight = false;
  state.messageLoadRequestId = 0;
  state.typingByChat = {};
  state.presenceByUser = {};
  state.sendDeduper = { map: {} };
  state.chatReadCursorByChat = {};
  state.closedCallSessions = {};
  state.call = createDefaultCallState();

  elements.verifyCodeForm.classList.add("hidden");
  elements.authView.classList.remove("hidden");
  elements.appView.classList.add("hidden");
  document.body.classList.remove("app-authenticated");
  document.documentElement.classList.remove("yooh-has-token-boot");
  closeSettingsPanel();
  elements.chatManagePanel.classList.add("hidden");
  elements.imageViewer.classList.add("hidden");
  closeVoicePreview(false);
  closeDialog(null);
  finishImageCropModal(null);
  closeEntityPanel();
  closeCreateFlow();
  closeDrawer();
  setServerChatMode(false);
  syncAuthCodeTargetHint();
  updateAuthCodeResendHint();
  renderCallState();
  setAuthBusy(false);
  setAuthLoginMethod("phone");
  setAuthEntryMode(isQrAuthAvailable() ? "qr" : "phone");
  applyMobileChatView();
}

async function bootstrapApp() {
  document.documentElement.classList.add("yooh-has-token-boot");
  stopAuthQrPolling();
  elements.authView.classList.add("hidden");
  elements.appView.classList.remove("hidden");
  document.body.classList.add("app-authenticated");
  setStatus("");

  await loadMe();
  await Promise.all([loadSettings(), loadWebrtcConfig(), loadChats(), loadStories()]);
  await processPendingDeepLink();
  await processPendingOpenChat();
  connectSocket();
  startBackgroundSync();
  if (bootstrapRecoveryTimer) {
    clearTimeout(bootstrapRecoveryTimer);
    bootstrapRecoveryTimer = null;
  }
  loadCalls().catch(() => {
    // Call history can load in background after initial paint.
  });
  loadAuthSessions().catch(() => {
    // Active sessions can load in background after initial paint.
  });
}

async function bootstrapAppWithRetry(maxAttempts = 3) {
  const attempts = Math.max(1, Math.min(5, Number(maxAttempts) || 1));
  let lastError = null;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      await bootstrapApp();
      return;
    } catch (error) {
      lastError = error;
      stopBackgroundSync();
      clearScheduledChatReload();
      if (state.socket) {
        state.socket.disconnect();
        state.socket = null;
      }
      if (attempt < attempts) {
        await wait(450 * attempt);
      }
    }
  }
  throw lastError ?? new Error("Failed to initialize session");
}

function isAuthBootstrapError(error) {
  const message = String(error?.message ?? error ?? "")
    .trim()
    .toLowerCase();
  if (!message) {
    return false;
  }
  return (
    message.includes("http 401") ||
    message.includes("session is invalid or expired") ||
    message.includes("token is invalid") ||
    message.includes("token payload is invalid") ||
    message.includes("token is missing") ||
    message.includes("user not found")
  );
}

function scheduleBootstrapRecovery() {
  if (bootstrapRecoveryTimer || !state.token) {
    return;
  }
  bootstrapRecoveryTimer = setTimeout(() => {
    bootstrapRecoveryTimer = null;
    if (!state.token) {
      return;
    }
    bootstrapAppWithRetry(2).catch((error) => {
      if (isAuthBootstrapError(error)) {
        resetToAuth();
        return;
      }
      setStatus(String(error?.message ?? "Temporary connection issue"));
      scheduleBootstrapRecovery();
    });
  }, BOOTSTRAP_RECOVERY_DELAY_MS);
}

function clearProfileUsernameCheckTimer() {
  if (state.profileUsernameCheckTimer) {
    clearTimeout(state.profileUsernameCheckTimer);
    state.profileUsernameCheckTimer = null;
  }
}

function setProfileUsernameCheckState(status = "idle", messageKey = "", fallbackText = "") {
  state.profileUsernameCheckState = {
    value: normalizeUsernameInput(elements.profileUsername?.value ?? "").toLowerCase(),
    status,
  };
  if (!elements.profileUsernameStatus) {
    return;
  }

  elements.profileUsernameStatus.classList.remove("success", "error", "pending");
  const text = messageKey ? t(messageKey) : String(fallbackText ?? "").trim();
  if (!text) {
    elements.profileUsernameStatus.textContent = "";
    elements.profileUsernameStatus.classList.add("hidden");
    return;
  }

  elements.profileUsernameStatus.textContent = text;
  elements.profileUsernameStatus.classList.remove("hidden");
  if (status === "available" || status === "current") {
    elements.profileUsernameStatus.classList.add("success");
  } else if (status === "invalid" || status === "taken" || status === "error") {
    elements.profileUsernameStatus.classList.add("error");
  } else {
    elements.profileUsernameStatus.classList.add("pending");
  }
}

async function checkProfileUsernameAvailability(strict = false) {
  if (!state.user || !elements.profileUsername) {
    return true;
  }

  const normalized = normalizeUsernameInput(elements.profileUsername.value).toLowerCase();
  if (elements.profileUsername.value !== normalized) {
    elements.profileUsername.value = normalized;
  }

  if (!normalized) {
    if (strict) {
      setProfileUsernameCheckState("invalid", "profileUsernameInvalid");
      return false;
    }
    setProfileUsernameCheckState("idle");
    return true;
  }

  if (!PROFILE_USERNAME_PATTERN.test(normalized)) {
    setProfileUsernameCheckState("invalid", "profileUsernameInvalid");
    return false;
  }

  const currentUsername = String(state.user.username ?? "").trim().toLowerCase();
  if (normalized === currentUsername) {
    setProfileUsernameCheckState("current", "profileUsernameCurrent");
    return true;
  }

  const requestId = Number(state.profileUsernameCheckSeq ?? 0) + 1;
  state.profileUsernameCheckSeq = requestId;
  setProfileUsernameCheckState("checking", "profileUsernameCheckPending");

  try {
    const response = await api(`/api/me/username-availability?username=${encodeURIComponent(normalized)}`, {
      retryTransient: false,
      retries: 1,
      requestTimeoutMs: 12_000,
    });
    if (requestId !== state.profileUsernameCheckSeq) {
      return null;
    }
    if (response?.available) {
      setProfileUsernameCheckState("available", "profileUsernameAvailable");
      return true;
    }
    setProfileUsernameCheckState("taken", "profileUsernameTaken");
    return false;
  } catch {
    if (requestId !== state.profileUsernameCheckSeq) {
      return null;
    }
    setProfileUsernameCheckState("error", "profileUsernameCheckFailed");
    return null;
  }
}

function scheduleProfileUsernameAvailabilityCheck(options = {}) {
  const immediate = Boolean(options.immediate);
  const strict = Boolean(options.strict);
  clearProfileUsernameCheckTimer();
  if (!state.profileEditorOpen) {
    return;
  }
  if (immediate) {
    void checkProfileUsernameAvailability(strict);
    return;
  }
  state.profileUsernameCheckTimer = setTimeout(() => {
    state.profileUsernameCheckTimer = null;
    void checkProfileUsernameAvailability(false);
  }, PROFILE_USERNAME_CHECK_DEBOUNCE_MS);
}

function bindProfileToForm() {
  if (!state.user) {
    return;
  }
  state.profilePremiumEditorOpen = false;
  clearProfileUsernameCheckTimer();
  state.profileUsernameCheckSeq = 0;

  const safeUsername = String(state.user.username ?? "").trim();
  const safeChatId = String(state.user.chatId ?? "").trim();
  const maxBioLength = Math.max(1, Number.parseInt(getYoohPlusLimits().maxBioLength ?? 70, 10) || 70);
  elements.profileDisplayName.value = state.user.displayName ?? "";
  if (elements.profileSelfAvatar) {
    applyAvatarNode(elements.profileSelfAvatar, getUserDisplayName(state.user), state.user.avatar ?? "", "Y");
  }
  if (elements.profileModernName) {
    renderNameWithPremiumBadge(elements.profileModernName, getUserDisplayName(state.user), state.user, { ellipsis: false });
  }
  if (elements.profileModernStatus) {
    elements.profileModernStatus.textContent = t("onlineNow");
  }
  if (elements.profileModernUsername) {
    elements.profileModernUsername.textContent = state.user.username ? `@${state.user.username}` : "@";
  }
  if (elements.profileModernChatId) {
    elements.profileModernChatId.textContent = state.user.chatId ?? "-";
  }
  if (elements.profileUsernameCopy) {
    elements.profileUsernameCopy.textContent = state.user.username ? `@${state.user.username}` : "@";
  }
  if (elements.profileModernUsername) {
    elements.profileModernUsername.textContent = safeUsername ? `@${safeUsername}` : "@";
  }
  if (elements.profileModernChatId) {
    elements.profileModernChatId.textContent = safeChatId || "-";
  }
  elements.profileUsername.value = state.user.username ?? "";
  if (safeUsername) {
    setProfileUsernameCheckState("current", "profileUsernameCurrent");
  } else {
    setProfileUsernameCheckState("idle");
  }
  if (elements.profileUsernameCopy) {
    elements.profileUsernameCopy.textContent = safeUsername ? `@${safeUsername}` : "@";
  }
  elements.profileChatId.value = safeChatId;
  if (elements.profileAbout) {
    elements.profileAbout.value = state.user.about ?? "";
    elements.profileAbout.maxLength = maxBioLength;
  }
  if (elements.profileAvatarData) {
    elements.profileAvatarData.value = state.user.avatar ?? "";
  }
  if (elements.profileAvatarPreview) {
    applyAvatarNode(elements.profileAvatarPreview, state.user.displayName ?? "Y", state.user.avatar ?? "", "Y");
  }
  syncProfilePremiumBadgeEditor();
}

