if (elements.authRegisterUsernameForm) {
  elements.authRegisterUsernameForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (state.authBusy) {
      return;
    }
    const normalizedInput = normalizeUsernameInput(elements.usernameInput?.value ?? "");
    if (!/^[a-zA-Z0-9_]{5,32}$/.test(normalizedInput)) {
      setStatus(localeText("Юзернейм: 5-32 символов, только латиница, цифры и _.", "Username must be 5-32 chars: latin letters, digits, and _."), true);
      return;
    }
    const username = normalizedInput.toLowerCase();
    state.authRegisterDraft.username = username;
    if (elements.usernameInput) {
      elements.usernameInput.value = username;
    }
    if (!String(elements.displayNameInput?.value ?? "").trim() && !String(state.authRegisterDraft.displayName ?? "").trim()) {
      state.authRegisterDraft.displayName = username;
      if (elements.displayNameInput) {
        elements.displayNameInput.value = username;
      }
    }
    setAuthRegisterStep("profile");
    setStatus("");
  });
}

async function submitAuthRegisterProfile({ skipAvatar = false } = {}) {
  if (state.authBusy || state.authMode !== "register") {
    return;
  }

  const code = normalizeAuthCodeValue(state.authRegisterDraft.code || getAuthCodeValue());
  if (code.length !== 6) {
    setAuthRegisterStep("code");
    setStatus(localeText("Введите 6-значный код.", "Enter the 6-digit code."), true);
    return;
  }

  const usernameInput = normalizeUsernameInput(elements.usernameInput?.value ?? state.authRegisterDraft.username ?? "");
  if (!/^[a-zA-Z0-9_]{5,32}$/.test(usernameInput)) {
    setAuthRegisterStep("username");
    setStatus(localeText("Юзернейм: 5-32 символов, только латиница, цифры и _.", "Username must be 5-32 chars: latin letters, digits, and _."), true);
    return;
  }

  const username = usernameInput.toLowerCase();
  const displayNameInput = String(elements.displayNameInput?.value ?? state.authRegisterDraft.displayName ?? "").trim();
  const displayName = displayNameInput || username;
  if (displayName.length > 80) {
    setStatus(localeText("Имя слишком длинное (максимум 80 символов).", "Display name is too long (max 80 characters)."), true);
    return;
  }

  const phone = state.pendingPhone || normalizePhoneForRequest(elements.phoneInput?.value);
  if (!phone) {
    setAuthRegisterStep("code");
    setStatus(localeText("Сначала запросите код для номера телефона.", "Request phone code first."), true);
    return;
  }

  state.authRegisterDraft.code = code;
  state.authRegisterDraft.username = username;
  state.authRegisterDraft.displayName = displayName;

  try {
    setAuthBusy(true);
    setStatus(t("loading"));

    const payload = await api(
      "/api/auth/register/verify-code",
      {
        method: "POST",
        body: {
          phone,
          code,
          username,
          displayName,
          locale: state.lang,
          device: getDeviceContext(),
        },
        retryTransient: true,
        retries: 5,
        retryDelayMs: 900,
      },
      false,
    );

    state.token = payload.token;
    localStorage.setItem("yooh_token", state.token);
    await bootstrapAppWithRetry(4);

    const avatar = skipAvatar ? "" : String(state.authRegisterDraft.avatar ?? "").trim();
    if (avatar) {
      try {
        const profilePayload = await api("/api/me/profile", {
          method: "PATCH",
          body: { avatar },
        });
        if (profilePayload?.user) {
          state.user = profilePayload.user;
          renderProfile();
          renderChats();
          renderActiveChat();
          renderMessages();
        }
      } catch {
        // Avatar upload failure should not break completed auth.
      }
    }
    setStatus("");
  } catch (error) {
    setStatus(error.message, true);
  } finally {
    setAuthBusy(false);
  }
}

