elements.requestCodeForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (state.authBusy) {
    return;
  }
  try {
    setAuthBusy(true);
    setStatus(t("loading"));
    const isLoginEmail = state.authMode === "login" && state.authLoginMethod === "email";
    const phone = isLoginEmail ? "" : normalizePhoneForRequest(elements.phoneInput.value);
    const email = isLoginEmail ? normalizeEmailForRequest(elements.emailInput?.value) : "";
    const body = isLoginEmail ? { email } : { phone };
    let requestMode = state.authMode;
    let requestPayload;
    try {
      requestPayload = await api(
        `/api/auth/${requestMode}/request-code`,
        { method: "POST", body, retryTransient: true, retries: 6, retryDelayMs: 850 },
        false,
      );
    } catch (primaryError) {
      if (!isLoginEmail && requestMode === "login" && isAuthNotRegisteredError(primaryError)) {
        requestMode = "register";
        setAuthMode("register", { reset: false });
        requestPayload = await api(
          "/api/auth/register/request-code",
          { method: "POST", body, retryTransient: true, retries: 6, retryDelayMs: 850 },
          false,
        );
      } else if (!isLoginEmail && requestMode === "register" && isAuthAlreadyRegisteredError(primaryError)) {
        requestMode = "login";
        setAuthMode("login", { reset: false });
        requestPayload = await api(
          "/api/auth/login/request-code",
          { method: "POST", body, retryTransient: true, retries: 6, retryDelayMs: 850 },
          false,
        );
      } else {
        throw primaryError;
      }
    }

    if (state.authMode !== requestMode) {
      setAuthMode(requestMode, { reset: false });
    }
    state.pendingPhone = phone;
    state.pendingEmail = email;
    setAuthCodeValue("");
    startAuthCodeResendCountdown(requestPayload?.expiresInSeconds ?? 60);
    syncAuthCodeTargetHint();
    if (requestMode === "register") {
      resetAuthRegisterDraft();
      state.authRegisterDraft.code = "";
      setAuthRegisterStep("code");
    } else {
      hideAuthRegisterStepForms();
      elements.verifyCodeForm.classList.remove("hidden");
    }
    elements.cloudPasswordForm?.classList.add("hidden");
    state.pendingLoginTicket = "";
    syncAuthEntryHeader();
    setStatus(
      requestMode === "register"
        ? localeText("Код отправлен. Продолжите регистрацию.", "Code sent. Continue registration.")
        : t("otpSentSupport"),
    );
  } catch (error) {
    setStatus(error.message, true);
  } finally {
    setAuthBusy(false);
  }
});

elements.verifyCodeForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (state.authBusy) {
    return;
  }

  try {
    setAuthBusy(true);
    const normalizedCode = getAuthCodeValue();
    if (normalizedCode.length !== 6) {
      setStatus(localeText("Введите 6-значный код.", "Enter the 6-digit code."), true);
      return;
    }

    if (state.authMode === "register") {
      state.authRegisterDraft.code = normalizedCode;
      setAuthRegisterStep("username");
      setStatus("");
      return;
    }

    setStatus(t("loading"));
    const isLoginEmail = state.authMode === "login" && state.authLoginMethod === "email";
    const body = {
      code: normalizedCode,
      locale: state.lang,
      device: getDeviceContext(),
    };

    if (isLoginEmail) {
      body.email = state.pendingEmail || normalizeEmailForRequest(elements.emailInput?.value);
    } else {
      body.phone = state.pendingPhone || normalizePhoneForRequest(elements.phoneInput.value);
    }

    const payload = await api(
      `/api/auth/${state.authMode}/verify-code`,
      { method: "POST", body, retryTransient: true, retries: 5, retryDelayMs: 900 },
      false,
    );

    if (payload?.requiresCloudPassword && payload?.loginTicket) {
      state.pendingLoginTicket = String(payload.loginTicket);
      if (elements.cloudUsernameInput) {
        elements.cloudUsernameInput.value = isLoginEmail
          ? String(body.email ?? "").trim()
          : String(body.phone ?? "").trim();
      }
      if (elements.cloudPasswordInput) {
        elements.cloudPasswordInput.type = "password";
      }
      elements.verifyCodeForm.classList.add("hidden");
      elements.cloudPasswordForm?.classList.remove("hidden");
      syncCloudPasswordToggleUi();
      syncAuthEntryHeader();
      setStatus(t("cloudPasswordRequired"));
      return;
    }

    state.token = payload.token;
    localStorage.setItem("yooh_token", state.token);

    await bootstrapAppWithRetry(4);
  } catch (error) {
    setStatus(error.message, true);
  } finally {
    setAuthBusy(false);
  }
});

if (elements.cloudPasswordForm) {
  elements.cloudPasswordForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (state.authBusy || !state.pendingLoginTicket) {
      return;
    }

    try {
      setAuthBusy(true);
      setStatus(t("loading"));
      const payload = await api(
        "/api/auth/login/verify-cloud-password",
        {
          method: "POST",
          body: {
            loginTicket: state.pendingLoginTicket,
            password: String(elements.cloudPasswordInput?.value ?? "").trim(),
            locale: state.lang,
          },
          retryTransient: true,
          retries: 3,
          retryDelayMs: 800,
        },
        false,
      );

      state.pendingLoginTicket = "";
      if (elements.cloudPasswordInput) {
        elements.cloudPasswordInput.value = "";
        elements.cloudPasswordInput.type = "password";
      }
      if (elements.cloudUsernameInput) {
        elements.cloudUsernameInput.value = "";
      }
      syncCloudPasswordToggleUi();
      state.token = payload.token;
      localStorage.setItem("yooh_token", state.token);
      await bootstrapAppWithRetry(4);
    } catch (error) {
      setStatus(error.message, true);
    } finally {
      setAuthBusy(false);
    }
  });
}

