async function runGlobalSearch() {
  const raw = elements.globalSearchInput.value.trim();
  if (!raw) {
    state.globalSearchResults = [];
    renderGlobalSearchResults();
    return;
  }
  const { mode, query } = parseSearchPrefix(raw);

  const normalizedUserQuery = normalizeUsernameInput(mode ? query : raw);
  const normalizedChatQuery = normalizeHandleInput(mode ? query : raw);
  const fetchUsers = !isGameMode() && (mode === "@" || mode === "" || mode === "*");
  const fetchChats = mode !== "*" && (mode === "%" || mode === "&" || mode === "$" || mode === "");
  const usersBotsOnly = mode === "*";

  let users = [];
  let chats = [];

  if (fetchUsers) {
    const params = new URLSearchParams();
    params.set("q", normalizedUserQuery);
    if (usersBotsOnly) {
      params.set("bot", "1");
    }
    const payload = await api(`/api/users/search?${params.toString()}`);
    users = Array.isArray(payload.users) ? payload.users : [];
    if (usersBotsOnly) {
      users.sort((a, b) => Number(Boolean(b.isSystemBot)) - Number(Boolean(a.isSystemBot)));
    }
  }

  if (fetchChats) {
    const payload = await api(`/api/chats/discovery?q=${encodeURIComponent(normalizedChatQuery)}`);
    chats = Array.isArray(payload.chats) ? payload.chats : [];
  }

  const filteredChats =
    isGameMode()
      ? chats.filter((entry) => entry.type === "server")
      : mode === "%"
        ? chats.filter((entry) => entry.type === "channel")
        : mode === "&"
          ? chats.filter((entry) => entry.type === "group")
          : mode === "$"
            ? chats.filter((entry) => entry.type === "server")
            : chats;

  state.globalSearchResults = [
    ...users.map((user) => ({ kind: "user", ...user })),
    ...filteredChats.map((chat) => ({ kind: "chat", ...chat })),
  ];
  if (mode === "*" && !state.globalSearchResults.length) {
    state.globalSearchResults = [{ kind: "info", message: t("botSearchEmpty") }];
  }
  renderGlobalSearchResults();
}

