elements.createChatForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  try {
    const type = elements.chatTypeSelect.value;
    const title = elements.chatTitleInput.value.trim();
    const supportsPublicPublishing = type === "group";
    if (type === "server" && !isGameMode()) {
      alert(t("serverCreateGameMode"));
      return;
    }
    if (type === "group" && title && !isValidGroupTitleInput(title)) {
      alert(t("invalidGroupTitle"));
      return;
    }

    const payload = await api("/api/chats", {
      method: "POST",
      body: {
        type,
        title: title || undefined,
        description: elements.chatDescriptionInput.value.trim() || undefined,
        memberId: elements.chatMemberIdInput.value.trim() || undefined,
        memberUsername: normalizeUsernameInput(elements.chatMemberUsernameInput.value) || undefined,
        isPublic: supportsPublicPublishing ? elements.chatPublicInput.checked : false,
        handle: supportsPublicPublishing ? normalizeHandleInput(elements.chatHandleInput.value) || undefined : undefined,
        interfaceMode: isGameMode() ? "game" : "chat",
        settings: {
          allowMemberInvites: elements.chatAllowInvitesInput.checked,
          commentsEnabled: elements.chatCommentsEnabledInput.checked,
        },
      },
    });

    await loadChats(payload.chat.id, false);
    elements.chatTitleInput.value = "";
    elements.chatDescriptionInput.value = "";
    elements.chatMemberIdInput.value = "";
    elements.chatMemberUsernameInput.value = "";
    elements.chatAllowInvitesInput.checked = true;
    elements.chatCommentsEnabledInput.checked = false;
    elements.chatPublicInput.checked = false;
    elements.chatHandleInput.value = "";
    closeDrawer();
  } catch (error) {
    alert(error.message);
  }
});

