if (elements.callCard && elements.callCard.dataset.iphoneCallGestureBound !== "1") {
  elements.callCard.dataset.iphoneCallGestureBound = "1";
  elements.callCard.addEventListener("pointerdown", (event) => {
    if (state.platform !== "iphone" || state.call.status === "idle" || event.pointerType === "mouse" || !event.isPrimary) {
      callControlsGesture = null;
      return;
    }
    const target = event.target instanceof Element ? event.target : null;
    if (!target || target.closest(".call-action-btn, .call-extra-btn, .call-keypad-panel, #call-local-video, #call-remote-video")) {
      callControlsGesture = null;
      return;
    }
    callControlsGesture = {
      startX: Number(event.clientX ?? 0),
      startY: Number(event.clientY ?? 0),
    };
  });
  elements.callCard.addEventListener("pointerup", (event) => {
    if (!callControlsGesture || state.platform !== "iphone" || state.call.status === "idle") {
      callControlsGesture = null;
      return;
    }
    const dx = Number(event.clientX ?? 0) - callControlsGesture.startX;
    const dy = Number(event.clientY ?? 0) - callControlsGesture.startY;
    if (Math.abs(dy) > Math.abs(dx) && dy <= -72) {
      playUiSwipeSound();
      toggleCallControlsExpanded(true);
    } else if (Math.abs(dy) > Math.abs(dx) && dy >= 72) {
      playUiSwipeSound();
      if (state.call.keypadOpen) {
        toggleCallKeypad(false);
      } else {
        toggleCallControlsExpanded(false);
      }
    }
    callControlsGesture = null;
  });
  elements.callCard.addEventListener("pointercancel", () => {
    callControlsGesture = null;
  });
}

