elements.sendMessageForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!state.activeChatId) {
    return;
  }

  const chat = getActiveChat();
  if (!chat) {
    return;
  }

  const canWrite = canPublishToStream(chat, state.activeStream);
  if (!canWrite) {
    updateComposerState();
    return;
  }

  if (isSupportBotChat(chat)) {
    try {
      await syncSupportTicketState({ force: true });
    } catch {
      // Ignore transient support state load errors and keep composer blocked.
    }
    if (!getActiveSupportTicketForChat(chat)) {
      updateComposerState();
      return;
    }
  }

  try {
    const composerText = String(elements.messageInput.value ?? "").trim();
    const pendingFiles = Array.isArray(state.pendingFiles) ? state.pendingFiles.filter((entry) => entry instanceof File) : [];
    if (!composerText && !pendingFiles.length) {
      return;
    }
    const replyToMessageId = String(state.replyToMessageId ?? "").trim();
    const threadRootId = state.activeStream === "comment" ? state.activeCommentThreadId || "" : "";
    const sendFingerprint = buildSendFingerprint({
      chatId: state.activeChatId,
      stream: state.activeStream,
      text: composerText,
      fileNames: pendingFiles.map((file) => file.name),
      replyToMessageId,
      threadRootId,
    });
    if (isDuplicateRecentSend(sendFingerprint)) {
      return;
    }
    rememberSendFingerprint(sendFingerprint);
    triggerHapticFeedback("impact");

    const filesToSend = [...pendingFiles];
    elements.messageInput.value = "";
    stopLocalTypingSignal(true);
    clearPendingFile();
    clearReplyTarget();
    updateEmojiSmartRow();
    syncComposerActionMode();

    if (isSecretChat(state.activeChatId)) {
      if (filesToSend.length) {
        for (let index = 0; index < filesToSend.length; index += 1) {
          const file = filesToSend[index];
          await sendLocalSecretMessage({
            text: index === 0 ? composerText : "",
            fileUpload: file,
          });
        }
      } else {
        await sendLocalSecretMessage({ text: composerText });
      }
      playMessageSentSound();
      return;
    }

    if (filesToSend.length) {
      for (let index = 0; index < filesToSend.length; index += 1) {
        const file = filesToSend[index];
        const formData = new FormData();
        formData.append("file", file);
        if (composerText && index === 0) {
          formData.append("text", composerText);
        }
        formData.append("stream", state.activeStream);
        if (replyToMessageId) {
          formData.append("replyToMessageId", replyToMessageId);
        }
        if (threadRootId) {
          formData.append("threadRootId", threadRootId);
        }
        formData.append("clientMessageId", generateClientMessageId());

        const payload = await api("/api/chats/" + state.activeChatId + "/files", {
          method: "POST",
          body: formData,
        });
        if (payload?.message) {
          upsertCurrentMessage(payload.message, { rerender: true });
        }
      }
    } else {
      const clientMessageId = generateClientMessageId();
      const optimistic = buildOptimisticTextMessage({
        chatId: state.activeChatId,
        text: composerText,
        stream: state.activeStream,
        clientMessageId,
        replyToMessageId,
        threadRootId,
      });
      upsertCurrentMessage(optimistic, { rerender: true });
      const endpoint =
        state.activeStream === "comment"
          ? "/api/chats/" + state.activeChatId + "/comments"
          : "/api/chats/" + state.activeChatId + "/messages";

      const payload = await api(endpoint, {
        method: "POST",
        body: {
          text: composerText,
          clientMessageId,
          replyToMessageId: replyToMessageId || undefined,
          threadRootId: threadRootId || undefined,
        },
      });
      if (payload?.message) {
        upsertCurrentMessage(payload.message, { rerender: true });
      } else {
        markPendingMessageStatus(clientMessageId, "");
      }
    }
    playMessageSentSound();
  } catch (error) {
    const pendingMine = state.currentMessages
      .filter((entry) => entry?.pendingStatus === "sending" && String(entry.sender?.id ?? "") === String(state.user?.id ?? ""))
      .slice(-4);
    for (const item of pendingMine) {
      if (item?.clientMessageId) {
        markPendingMessageStatus(item.clientMessageId, "failed");
      }
    }
    alert(error.message);
  }
});

if (elements.supportKeyboardActions) {
  elements.supportKeyboardActions.addEventListener("click", async (event) => {
    const categoryButton = event.target.closest("button[data-support-category]");
    const actionButton = event.target.closest("button[data-support-action]");
    if (!categoryButton && !actionButton) {
      return;
    }

    if (actionButton) {
      const action = String(actionButton.dataset.supportAction ?? "").trim();
      if (action === "open-ticket") {
        state.supportTicket.panel = "categories";
        renderSupportKeyboard();
        return;
      }
      if (action === "back") {
        state.supportTicket.panel = "menu";
        renderSupportKeyboard();
        return;
      }
      if (action === "status") {
        const active = getActiveSupportTicketForChat(getActiveChat());
        if (active?.number) {
          alert(`#${active.number} · ${active.categoryLabel || active.category || ""}`);
        } else {
          alert(t("supportTicketWaiting"));
        }
        return;
      }
      if (action === "faq") {
        alert(getSupportFaqText());
      }
      return;
    }

    const category = String(categoryButton?.dataset.supportCategory ?? "").trim();
    if (!category) {
      return;
    }
    try {
      await createSupportTicketFromCategory(category);
    } catch (error) {
      alert(error.message || "Request failed");
    }
  });
}

