elements.emojiToggleBtn.addEventListener("click", () => {
  emitTypingSignal("emoji");
  triggerHapticFeedback("selection");
  const nextOpen = elements.emojiPanel.classList.contains("hidden");
  elements.emojiPanel.classList.toggle("hidden", !nextOpen);
  if (!nextOpen) {
    closeEmojiTonePicker();
    return;
  }
  if (nextOpen) {
    state.emojiPanelQuery = "";
    if (elements.emojiPanelSearchInput) {
      elements.emojiPanelSearchInput.value = "";
    }
    if (state.emojiPanelTab === "emoji") {
      void loadEmojiCatalog();
    } else if (state.emojiPanelTab === "stickers") {
      void loadStickerPackCatalog({ query: "" });
    } else {
      void loadGifPanelItems("");
    }
    renderEmojiPanelContent();
    updateEmojiPanelPosition();
  }
});
