if (elements.emojiPanel) {
  let emojiPanelPointerStartX = 0;
  let emojiPanelPointerStartY = 0;
  elements.emojiPanel.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  elements.emojiPanel.addEventListener("pointerdown", (event) => {
    if (event.target.closest("button, input")) {
      return;
    }
    emojiPanelPointerStartX = event.clientX;
    emojiPanelPointerStartY = event.clientY;
  });
  elements.emojiPanel.addEventListener("pointerup", (event) => {
    const dx = event.clientX - emojiPanelPointerStartX;
    const dy = event.clientY - emojiPanelPointerStartY;
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)) {
      const tabs = ["emoji", "stickers", "gif"];
      const currentIndex = Math.max(0, tabs.indexOf(state.emojiPanelTab));
      const nextIndex = Math.max(0, Math.min(tabs.length - 1, currentIndex + (dx < 0 ? 1 : -1)));
      if (nextIndex !== currentIndex) {
        state.emojiPanelTab = tabs[nextIndex];
        renderEmojiPanelContent();
      }
      return;
    }
    if (dy > 90 && Math.abs(dy) > Math.abs(dx)) {
      elements.emojiPanel.classList.add("hidden");
      closeEmojiTonePicker();
    }
  });
}

elements.dialogForm.addEventListener("submit", (event) => {
  event.preventDefault();
  if (dialogState.mode === "prompt") {
    const value = elements.dialogInput.value;
    if (dialogState.requireValue && !value.trim()) {
      return;
    }
    closeDialog(value);
    return;
  }

  if (dialogState.mode === "select") {
    const value = elements.dialogSelect.value;
    if (dialogState.requireValue && !value) {
      return;
    }
    closeDialog(value);
    return;
  }

  if (dialogState.mode === "confirm" && dialogState.checkboxEnabled) {
    closeDialog({
      confirmed: true,
      checked: Boolean(elements.dialogCheckbox?.checked),
    });
    return;
  }

  closeDialog(true);
});

