document.querySelectorAll("[data-menu-action]").forEach((button) => {
  button.addEventListener("click", async () => {
    const action = String(button.dataset.menuAction ?? "").trim();
    if (!action) {
      return;
    }

    if (action === "create-group") {
      openCreateFlow("group");
      closeDrawer();
      return;
    }

    if (action === "create-channel") {
      openCreateFlow("channel");
      closeDrawer();
      return;
    }

    if (action === "favorites") {
      if (normalizeFolderId(state.activeFolderId) !== "all") {
        state.activeFolderId = "all";
        saveActiveFolder();
      }
      try {
        const favoritesChat = await getOrCreateSavedMessagesChat();
        if (!favoritesChat) {
          return;
        }
        await openChat(favoritesChat.id, false);
      } catch (error) {
        alert(error.message);
      } finally {
        closeDrawer();
      }
      return;
    }

    if (action === "feedback") {
      try {
        await openFeedbackComposer();
      } catch (error) {
        alert(error.message || t("feedbackBlocked"));
      } finally {
        closeDrawer();
      }
      return;
    }

    if (action === "about") {
      alert(`${t("aboutTitle")}\n${t("aboutDescription")}`);
      closeDrawer();
      return;
    }

    if (action === "yooh-plus") {
      if (state.platform === "iphone") {
        openIphoneDrawerTab("settings", { presentation: "push" });
      } else {
        setDrawerTab("settings");
      }
      openSettingsSection("premium-info");
      return;
    }
  });
});

