if (elements.imageCropPanel && elements.imageCropStage && elements.imageCropZoom) {
  elements.imageCropPanel.addEventListener("click", (event) => {
    if (event.target === elements.imageCropPanel) {
      finishImageCropModal(null);
    }
  });

  elements.imageCropCloseBtn?.addEventListener("click", () => {
    finishImageCropModal(null);
  });

  elements.imageCropCancelBtn?.addEventListener("click", () => {
    finishImageCropModal(null);
  });

  elements.imageCropApplyBtn?.addEventListener("click", () => {
    applyImageCropModal();
  });

  elements.imageCropZoom.addEventListener("input", () => {
    imageCropRuntime.zoom = clampImageCropValue(elements.imageCropZoom.value, IMAGE_CROP_MIN_ZOOM, IMAGE_CROP_MAX_ZOOM);
    imageCropRuntime.offset = clampImageCropOffset(imageCropRuntime.offset, imageCropRuntime.zoom);
    updateImageCropUi();
  });

  elements.imageCropStage.addEventListener("wheel", (event) => {
    if (!imageCropRuntime.config) {
      return;
    }
    event.preventDefault();
    const delta = event.deltaY > 0 ? -0.08 : 0.08;
    imageCropRuntime.zoom = clampImageCropValue(imageCropRuntime.zoom + delta, IMAGE_CROP_MIN_ZOOM, IMAGE_CROP_MAX_ZOOM);
    imageCropRuntime.offset = clampImageCropOffset(imageCropRuntime.offset, imageCropRuntime.zoom);
    updateImageCropUi();
  }, { passive: false });

  elements.imageCropStage.addEventListener("pointerdown", (event) => {
    if (!imageCropRuntime.config) {
      return;
    }
    event.preventDefault();
    imageCropRuntime.drag = {
      pointerId: Number.isFinite(Number(event.pointerId)) ? Number(event.pointerId) : null,
      startX: Number(event.clientX || 0),
      startY: Number(event.clientY || 0),
      origin: { ...imageCropRuntime.offset },
    };
    elements.imageCropStage.setPointerCapture?.(event.pointerId);
  });

  window.addEventListener("pointermove", (event) => {
    if (!imageCropRuntime.drag || !imageCropRuntime.config) {
      return;
    }
    if (
      Number.isFinite(Number(imageCropRuntime.drag.pointerId)) &&
      Number.isFinite(Number(event.pointerId)) &&
      Number(event.pointerId) !== Number(imageCropRuntime.drag.pointerId)
    ) {
      return;
    }
    const nextOffset = {
      x: imageCropRuntime.drag.origin.x + (Number(event.clientX || 0) - imageCropRuntime.drag.startX),
      y: imageCropRuntime.drag.origin.y + (Number(event.clientY || 0) - imageCropRuntime.drag.startY),
    };
    imageCropRuntime.offset = clampImageCropOffset(nextOffset, imageCropRuntime.zoom);
    updateImageCropUi();
  });

  const stopCropDrag = () => {
    imageCropRuntime.drag = null;
  };
  window.addEventListener("pointerup", stopCropDrag);
  window.addEventListener("pointercancel", stopCropDrag);

  window.addEventListener("resize", () => {
    if (imageCropRuntime.config && !elements.imageCropPanel.classList.contains("hidden")) {
      updateImageCropUi();
    }
  });
}

