if (elements.chatContextArchiveBtn) {
  elements.chatContextArchiveBtn.addEventListener("click", async () => {
    const chatId = state.chatContextChatId;
    if (!chatId) {
      closeChatContextMenu();
      return;
    }
    const nextArchived = !isChatArchived(chatId);
    setChatArchived(chatId, nextArchived);
    if (nextArchived && state.activeChatId === chatId) {
      state.activeChatId = null;
      state.currentMessages = [];
    }
    renderChats();
    renderActiveChat();
    if (state.settingsSection === "folders") {
      renderSettingsFoldersSection();
    }
    closeChatContextMenu();
    if (!nextArchived && !state.activeChatId) {
      await openChat(chatId, true).catch(() => {
        // Ignore transient open errors.
      });
    }
  });
}

