if (elements.chatContextNotificationsBtn) {
  elements.chatContextNotificationsBtn.addEventListener("click", async () => {
    if (!state.chatContextChatId) {
      return;
    }
    const chatId = state.chatContextChatId;
    const nextEnabled = !isChatNotificationsEnabled(chatId);
    if (!nextEnabled) {
      const selected = await selectDialog({
        title: t("chatNotificationMuteTimer"),
        value: "forever",
        options: [
          { value: "1h", label: t("chatNotificationMuteHour") },
          { value: "1d", label: t("chatNotificationMuteDay") },
          { value: "1w", label: t("chatNotificationMuteWeek") },
          { value: "forever", label: t("chatNotificationMuteForever") },
        ],
        submitText: t("saveSettings"),
      });
      if (selected === null) {
        return;
      }
      const durations = {
        "1h": 60 * 60 * 1000,
        "1d": 24 * 60 * 60 * 1000,
        "1w": 7 * 24 * 60 * 60 * 1000,
      };
      const muteUntil =
        selected === "forever" ? "forever" : new Date(Date.now() + (durations[selected] ?? durations["1h"])).toISOString();
      setChatNotificationsEnabled(chatId, false, { muteUntil });
    } else {
      setChatNotificationsEnabled(chatId, true);
    }
    renderChats();
    if (state.activeChatId === chatId && elements.entityPanel && !elements.entityPanel.classList.contains("hidden")) {
      openActiveEntityPanel().catch(() => {
        // Ignore panel refresh errors.
      });
    }
    closeChatContextMenu();
  });
}

