if (elements.chatContextClearHistoryBtn) {
  elements.chatContextClearHistoryBtn.addEventListener("click", async () => {
    const chatId = state.chatContextChatId;
    const chat = state.chats.find((entry) => entry.id === chatId) ?? null;
    closeChatContextMenu();
    if (!chatId || !chat || !canClearChatHistory(chat)) {
      return;
    }
    try {
      const confirmed = await confirmDialog({
        title: t("clearHistory"),
        message: t("clearHistoryConfirm"),
        submitText: t("clearHistory"),
      });
      if (!confirmed) {
        return;
      }
      if (isSecretChat(chatId)) {
        pruneSecretMessageExpiries(chatId, false);
        setSecretChatMessages(chatId, []);
        if (state.activeChatId === chatId) {
          state.currentMessages = [];
          renderMessages();
        }
        renderChats();
        renderActiveChat();
        return;
      }
      await api(`/api/chats/${chatId}/clear-history`, { method: "POST" });
      if (state.activeChatId === chatId) {
        state.currentMessages = [];
        renderMessages();
      }
      await loadChats(chatId, true);
    } catch (error) {
      alert(error.message);
    }
  });
}

if (elements.chatContextLeaveBtn) {
  elements.chatContextLeaveBtn.addEventListener("click", async () => {
    const chatId = state.chatContextChatId;
    const chat = state.chats.find((entry) => entry.id === chatId) ?? null;
    closeChatContextMenu();
    if (!chatId || !chat || !canLeaveChat(chat)) {
      return;
    }
    try {
      const confirmed = await confirmDialog({
        title: t("leaveChat"),
        message: chat.type === "channel" ? t("entityLeaveChannel") : t("entityLeaveGroup"),
        submitText: t("leaveChat"),
      });
      if (!confirmed) {
        return;
      }
      await api(`/api/chats/${chatId}/members/${state.user?.id}`, { method: "DELETE" });
      if (state.activeChatId === chatId) {
        state.activeChatId = null;
        state.currentMessages = [];
      }
      setChatPinned(chatId, false);
      setChatArchived(chatId, false);
      await loadChats(state.activeChatId, true);
    } catch (error) {
      alert(error.message);
    }
  });
}

if (elements.chatContextDeleteBtn) {
  elements.chatContextDeleteBtn.addEventListener("click", async () => {
    const chatId = state.chatContextChatId;
    closeChatContextMenu();
    if (!chatId) {
      return;
    }
    try {
      const confirmed = await confirmDialog({
        title: t("deleteChat"),
        message: t("deleteChatConfirm"),
        submitText: t("deleteChat"),
      });
      if (!confirmed) {
        return;
      }
      if (isSecretChat(chatId)) {
        setSecretChatEnabled(chatId, false);
        if (state.activeChatId === chatId) {
          state.activeChatId = null;
          state.currentMessages = [];
        }
        setChatPinned(chatId, false);
        setChatArchived(chatId, false);
        markChatAsRead(chatId);
        renderChats();
        renderActiveChat();
        renderMessages();
        return;
      }
      await api(`/api/chats/${chatId}`, {
        method: "DELETE",
      });
      if (state.activeChatId === chatId) {
        state.activeChatId = null;
      }
      setChatPinned(chatId, false);
      await loadChats(state.activeChatId, true);
    } catch (error) {
      alert(error.message);
    }
  });
}

