if (elements.globalSearchForm && elements.globalSearchInput) {
  let searchGestureStartY = 0;
  let searchGestureStartX = 0;
  elements.globalSearchForm.addEventListener("pointerdown", (event) => {
    if (!isIphonePlatform() || document.activeElement !== elements.globalSearchInput || event.pointerType === "mouse") {
      return;
    }
    searchGestureStartY = event.clientY;
    searchGestureStartX = event.clientX;
  });
  elements.globalSearchForm.addEventListener("pointerup", (event) => {
    if (!isIphonePlatform() || document.activeElement !== elements.globalSearchInput || event.pointerType === "mouse") {
      return;
    }
    const deltaY = event.clientY - searchGestureStartY;
    const deltaX = Math.abs(event.clientX - searchGestureStartX);
    if (deltaY > 42 && deltaY > deltaX) {
      closeIphoneSearch();
    }
  });
}

