elements.profileForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  try {
    const normalizedUsername = normalizeUsernameInput(elements.profileUsername?.value ?? "").toLowerCase();
    if (elements.profileUsername) {
      elements.profileUsername.value = normalizedUsername;
    }
    const availability = await checkProfileUsernameAvailability(true);
    if (availability === false) {
      elements.profileUsername?.focus();
      return;
    }

    const nextProfilePayload = {
      displayName: elements.profileDisplayName.value.trim(),
      username: normalizedUsername,
      about: elements.profileAbout?.value?.trim() ?? "",
      avatar: elements.profileAvatarData?.value?.trim() ?? "",
      locale: state.lang,
    };
    if (isYoohPlusUser()) {
      nextProfilePayload.premiumBadge = getProfilePremiumBadgeDraft();
    }

    const payload = await api("/api/me/profile", {
      method: "PATCH",
      body: nextProfilePayload,
    });

    state.user = normalizePremiumUserLike(payload.user);
    renderProfile();
    bindProfileToForm();
    renderContacts();
    await loadChats(state.activeChatId, true);
    await loadCalls();
  } catch (error) {
    alert(error.message);
  }
});

elements.settingsForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  try {
    const selectedPlatform = normalizePlatform(elements.sPlatformMode?.value) || state.platform || detectPlatformFromUserAgent();
    const payload = await api("/api/me/settings", {
      method: "PATCH",
      body: collectSettingsPayload(),
    });

    state.settings = payload.settings;
    if (state.settings?.language && i18n[state.settings.language]) {
      state.lang = state.settings.language;
      localStorage.setItem("yooh_lang", state.lang);
    }
    applyI18n();
    bindSettingsToForm();
    applyAppearance(state.settings?.appearance ?? {});
    applyPlatform(selectedPlatform);
    closeDrawer();
  } catch (error) {
    alert(error.message);
  }
});

