elements.chatPrivacyBtn.addEventListener("click", async () => {
  const chat = getActiveChat();
  if (!chat || chat.type !== "group") {
    return;
  }

  try {
    if (chat.isPublic) {
      const confirmed = await confirmDialog({
        title: t("togglePublic"),
        message: t("makePrivateConfirm"),
        submitText: t("makePrivate"),
      });
      if (!confirmed) {
        return;
      }

      await api("/api/chats/" + chat.id, {
        method: "PATCH",
        body: {
          isPublic: false,
          handle: null,
        },
      });
    } else {
      const handleInput = await promptDialog({
        title: t("makePublic"),
        message: t("publicHandlePrompt"),
        value: chat.handle ? formatChatHandle(chat.type, chat.handle) : "",
        submitText: t("saveSettings"),
        requireValue: true,
      });
      if (handleInput === null) {
        return;
      }

      const handle = normalizeHandleInput(handleInput);
      if (!handle) {
        alert(t("handleRequired"));
        return;
      }

      await api("/api/chats/" + chat.id, {
        method: "PATCH",
        body: {
          isPublic: true,
          handle,
        },
      });
    }

    await loadChats(chat.id, true);
  } catch (error) {
    alert(error.message);
  }
});

