if (elements.storyViewerStage) {
  let holdPause = false;
  let storyStageStartX = 0;
  let storyStageStartY = 0;
  let storyStageDx = 0;
  let storyStageDy = 0;
  elements.storyViewerStage.addEventListener("pointerdown", (event) => {
    if (event.target.closest("button, input, form")) {
      return;
    }
    holdPause = true;
    storyStageStartX = event.clientX;
    storyStageStartY = event.clientY;
    storyStageDx = 0;
    storyStageDy = 0;
    clearStoryViewerAutoTimer();
  });
  elements.storyViewerStage.addEventListener("pointermove", (event) => {
    if (!holdPause) {
      return;
    }
    storyStageDx = event.clientX - storyStageStartX;
    storyStageDy = event.clientY - storyStageStartY;
  });
  const resume = () => {
    if (!holdPause) {
      return;
    }
    holdPause = false;
    storyStageDx = 0;
    storyStageDy = 0;
    scheduleStoryViewerAutoAdvance();
  };
  elements.storyViewerStage.addEventListener("pointerup", (event) => {
    if (!event.target.closest("button, input, form")) {
      const isHorizontalSwipe = Math.abs(storyStageDx) > 70 && Math.abs(storyStageDx) > Math.abs(storyStageDy);
      const isVerticalSwipe = storyStageDy > 80 && Math.abs(storyStageDy) > Math.abs(storyStageDx);
      const isUpSwipe = storyStageDy < -80 && Math.abs(storyStageDy) > Math.abs(storyStageDx);
      if (isVerticalSwipe) {
        closeStoryViewer();
        resume();
        return;
      }
      if (isUpSwipe) {
        elements.storyViewerReactionMenu?.classList.add("hidden");
        openAdaptiveFloatingMenu(elements.storyViewerMoreMenu, elements.storyViewerMoreBtn, {
          preferredVertical: "top",
          preferredHorizontal: "right",
          offset: 8,
          fallbackWidth: 240,
          fallbackHeight: 220,
          padding: 12,
        });
        resume();
        return;
      }
      if (isHorizontalSwipe) {
        stepStoryViewer(storyStageDx > 0 ? -1 : 1);
        resume();
        return;
      }
      const rect = elements.storyViewerStage.getBoundingClientRect();
      const x = event.clientX - rect.left;
      if (x < rect.width * 0.33) {
        stepStoryViewer(-1);
      } else if (x > rect.width * 0.67) {
        stepStoryViewer(1);
      }
    }
    resume();
  });
  elements.storyViewerStage.addEventListener("pointercancel", resume);
  elements.storyViewerStage.addEventListener("pointerleave", resume);
  elements.storyViewerStage.addEventListener("dblclick", (event) => {
    if (event.target.closest("button, input, form") || getActiveStory()?.isSelf) {
      return;
    }
    setStoryReactionValue("\uD83D\uDC4D").catch((error) => {
      alert(error.message);
    });
  });
}

