bindIphoneRuntimeGestures();
bindDropZone(elements.sendMessageForm);
bindDropZone(elements.messageList);

window.addEventListener("error", (event) => {
  void sendClientErrorLog({
    endpoint: window.location.pathname,
    message: event?.error ?? event?.message ?? "Unhandled error",
    stack: event?.error?.stack ?? null,
    url: event?.filename ?? window.location.href,
    extra: {
      line: event?.lineno ?? null,
      column: event?.colno ?? null,
    },
  });
});

window.addEventListener("unhandledrejection", (event) => {
  const reason = event?.reason;
  void sendClientErrorLog({
    endpoint: window.location.pathname,
    message: reason instanceof Error ? reason.message : reason ?? "Unhandled rejection",
    stack: reason instanceof Error ? reason.stack : null,
    url: window.location.href,
    extra: {
      type: "unhandledrejection",
    },
  });
});

if (globalThis.__YOOH_ENABLE_TEST_HOOKS__) {
  globalThis.__yoohTest = {
    state,
    openChat,
    ensureDirectChatWithUser,
    ensureSecretChatWithUser,
    renderCallState,
    setConnectedCall(chatId, mode = "audio") {
      const targetChat = state.chats.find((entry) => String(entry.id) === String(chatId));
      if (!targetChat) {
        throw new Error(`Chat ${chatId} not found`);
      }
      const safeMode = normalizeCallMode(mode);
      state.call = {
        ...createDefaultCallState(),
        sessionId: `test-connected-${targetChat.id}`,
        status: "connected",
        mode: safeMode,
        chatId: targetChat.id,
        peer: {
          id: targetChat.id,
          displayName: targetChat.title,
        },
        participants: buildCallParticipantsForChat(targetChat),
        incoming: false,
        accepted: true,
        videoEnabled: safeMode === "video",
      };
      renderCallState();
    },
    setIncomingCall(chatId, mode = "audio") {
      const targetChat = state.chats.find((entry) => String(entry.id) === String(chatId));
      if (!targetChat) {
        throw new Error(`Chat ${chatId} not found`);
      }
      const safeMode = normalizeCallMode(mode);
      const directPeer = targetChat.type === "direct" ? normalizeCallParticipant(getDirectPeer(targetChat)) : null;
      const fallbackPeer =
        directPeer ??
        normalizeCallParticipant((targetChat.members ?? []).find((entry) => String(entry.userId ?? "") !== String(state.user?.id ?? ""))) ?? {
          id: targetChat.id,
          displayName: targetChat.title,
          username: targetChat.handle ?? "",
          avatar: "",
        };
      state.call = {
        ...createDefaultCallState(),
        sessionId: `test-incoming-${targetChat.id}`,
        chatId: targetChat.id,
        mode: safeMode,
        participants: buildCallParticipantsForChat(targetChat),
        peer: fallbackPeer,
        incoming: true,
        status: "incoming",
      };
      renderCallState();
    },
    resetCall() {
      state.call.status = "idle";
      renderCallState();
    },
  };
}

if (normalizePlatform(state.platformChoice || state.platform)) {
  applyPlatform(state.platformChoice || state.platform);
  hidePlatformPicker();
} else {
  applyPlatform(detectPlatformFromUserAgent());
  showPlatformPicker();
}

state.activeFolderId = normalizeFolderId(state.activeFolderId);
saveChatFolders();
saveActiveFolder();
applyAppearance();
bindAuthCodeDigits();
syncAuthRegisterAvatarPreview();
applyI18n();
installIphoneInteractiveFeedback();
installUiSoundInteractions();
document.body.classList.toggle("battery-saver", state.settingsBatterySaver);
setAuthMode("login");
setAuthEntryMode(isQrAuthAvailable() ? "qr" : "phone");
updateCreateChatFields();
globalThis.__yoohAdmin = createYoohAdminConsoleApi();

if (state.token) {
  bootstrapAppWithRetry(4).catch((error) => {
    if (isAuthBootstrapError(error)) {
      resetToAuth();
      return;
    }
    setStatus(String(error?.message ?? "Temporary connection issue"));
    scheduleBootstrapRecovery();
  });
}

